async function startBenchmark() {
    const source = document.getElementById('benchmarkSourceInput').value.trim();
    if (!source) {
        showToast('Introduce un enlace de YouTube o ruta local para el benchmark', 'info');
        return;
    }

    const pBox = document.getElementById('benchmarkProgressBox');
    const pBar = document.getElementById('benchmarkProgressBar');
    const pPct = document.getElementById('benchmarkProgressPct');
    const pTitle = document.getElementById('benchmarkProgressTitle');
    const pLog = document.getElementById('benchmarkProgressLog');

    pBox.style.display = 'block';
    pBar.style.width = '2%';
    pPct.innerText = '2%';
    pTitle.innerText = 'Iniciando 12 combinaciones...';
    pLog.innerText = 'Descargando y recortando clip de 10s...';

    try {
        const res = await fetch('/api/benchmark/run', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ source })
        });
        const data = await res.json();
        const jobId = data.job_id;

        const eventSource = new EventSource(`/api/jobs/${jobId}/stream`);

        eventSource.onmessage = (event) => {
            const msg = JSON.parse(event.data);
            if (msg.type === 'progress') {
                const p = Math.round(msg.progress);
                pBar.style.width = `${p}%`;
                pPct.innerText = `${p}%`;
                pTitle.innerText = msg.message;
                pLog.innerText = msg.log || '';
            } else if (msg.type === 'completed') {
                pBar.style.width = '100%';
                pPct.innerText = '100%';
                eventSource.close();
                showToast('¡Benchmark completado con éxito!', 'success');

                setTimeout(() => {
                    pBox.style.display = 'none';
                    displayBenchmarkResults(msg.result);
                    loadBenchmarkHistory();
                }, 600);
            } else if (msg.type === 'error') {
                eventSource.close();
                showToast('Error en el benchmark: ' + msg.error, 'error');
            }
        };

        eventSource.onerror = () => {
            eventSource.close();
        };

    } catch (e) {
        pBox.style.display = 'none';
        showToast('Error al iniciar benchmark: ' + e, 'error');
    }
}

function displayBenchmarkResults(result) {
    state.currentBenchmark = result;

    // Show sections
    document.getElementById('benchmarkKpiGrid').style.display = 'grid';
    document.getElementById('benchmarkGallerySection').style.display = 'block';
    document.getElementById('benchmarkTableSection').style.display = 'block';

    // Populate KPIs
    document.getElementById('kpiFastestCombo').innerText = result.fastest_combo || '--';
    document.getElementById('kpiFastestTime').innerText = `${result.fastest_time_sec}s (${result.fastest_time_per_sec} s/s)`;
    
    const speedup = result.gpu_speedup_percent;
    document.getElementById('kpiGpuSpeedup').innerText = speedup >= 0 ? `+${speedup}%` : `${speedup}%`;
    document.getElementById('kpiRatio4k').innerText = `${result.ratio_4k_vs_1080p}x más lento`;
    document.getElementById('kpiBlurReduction').innerText = `${result.blur_reduction_percent}% ahorro`;

    // Populate 12-row Table
    const tbody = document.getElementById('benchDetailTableBody');
    let html = '';
    result.results.forEach(row => {
        const isFastest = (row.render_time_sec === result.fastest_time_sec);
        html += `
            <tr style="${isFastest ? 'background: rgba(16, 185, 129, 0.1);' : ''}">
                <td><strong>${escapeHtml(row.resolution)}</strong></td>
                <td><span class="badge-channel" style="background: rgba(255,255,255,0.1);">${escapeHtml(row.hardware)}</span></td>
                <td>${escapeHtml(row.blur_level)}</td>
                <td><strong>${escapeHtml(row.render_time_sec)} s</strong></td>
                <td><span style="color: var(--accent-cyan); font-family: 'JetBrains Mono';">${escapeHtml(row.time_per_sec_video)} s/s</span></td>
                <td>${escapeHtml(row.speedup_realtime)}x real</td>
                <td>${escapeHtml(row.file_size_mb)} MB</td>
            </tr>
        `;
    });
    tbody.innerHTML = html;

    // Update gallery videos
    updateBenchmarkGalleryDisplay();
}

function updateBenchmarkGalleryDisplay() {
    if (!state.currentBenchmark) return;

    const activeRes = document.querySelector('#benchFilterRes .pill.active').dataset.res;
    const activeHw = document.querySelector('#benchFilterHw .pill.active').dataset.hw;

    const v100 = document.getElementById('benchVideo100');
    const v75 = document.getElementById('benchVideo75');
    const v50 = document.getElementById('benchVideo50');

    const t100 = document.getElementById('benchTime100');
    const t75 = document.getElementById('benchTime75');
    const t50 = document.getElementById('benchTime50');

    const matches = state.currentBenchmark.results.filter(r => 
        r.resolution === activeRes && r.hardware === activeHw
    );

    const r100 = matches.find(r => r.blur_label === '100%');
    const r75 = matches.find(r => r.blur_label === '75%');
    const r50 = matches.find(r => r.blur_label === '50%');

    if (r100 && r100.video_url) {
        v100.src = r100.video_url;
        t100.innerText = `${r100.render_time_sec}s (${r100.time_per_sec_video} s/s)`;
    }
    if (r75 && r75.video_url) {
        v75.src = r75.video_url;
        t75.innerText = `${r75.render_time_sec}s (${r75.time_per_sec_video} s/s)`;
    }
    if (r50 && r50.video_url) {
        v50.src = r50.video_url;
        t50.innerText = `${r50.render_time_sec}s (${r50.time_per_sec_video} s/s)`;
    }
}

async function loadBenchmarkHistory() {
    const listEl = document.getElementById('benchmarkHistoryList');
    try {
        const res = await fetch('/api/benchmark/history');
        const data = await res.json();
        state.benchmarkHistory = data.history || [];

        if (state.benchmarkHistory.length === 0) {
            listEl.innerHTML = '<div class="text-muted text-center py-4">No hay ejecuciones de benchmark guardadas.</div>';
            return;
        }

        let html = '';
        state.benchmarkHistory.forEach((run, idx) => {
            html += `
                <div class="trailer-row" style="cursor: pointer;" onclick="loadHistoryRunIntoView(${idx})">
                    <div class="trailer-meta">
                        <div class="trailer-game-tag">
                            📅 ${escapeHtml(run.date)}
                            <span class="badge-channel badge-igd">Clip: ${escapeHtml(run.clip_duration_sec)}s</span>
                        </div>
                        <div class="trailer-title"><strong>Origen:</strong> ${escapeHtml(run.source)}</div>
                        <div class="trailer-date">⚡ <strong>Más Rápida:</strong> ${escapeHtml(run.fastest_combo)} (${escapeHtml(run.fastest_time_sec)}s) • 4K vs 1080p: ${escapeHtml(run.ratio_4k_vs_1080p)}x</div>
                    </div>
                    <div class="trailer-actions">
                        <button class="btn btn-primary btn-sm">Ver Resultados</button>
                    </div>
                </div>
            `;
        });
        listEl.innerHTML = html;

        // Auto-load most recent run if none is active
        if (!state.currentBenchmark && state.benchmarkHistory.length > 0) {
            displayBenchmarkResults(state.benchmarkHistory[0]);
        }

    } catch (e) {
        listEl.innerHTML = `<div class="text-muted">Error cargando historial: ${escapeHtml(e && e.message ? e.message : e)}</div>`;
    }
}

window.loadHistoryRunIntoView = function(idx) {
    if (state.benchmarkHistory[idx]) {
        displayBenchmarkResults(state.benchmarkHistory[idx]);
        showToast('Resultados del benchmark cargados', 'info');
        window.scrollTo({ top: 400, behavior: 'smooth' });
    }
};


