function hexToRgb(hex) {
    if (!hex) return '124, 58, 237';
    let c = hex.replace('#', '').trim();
    if (c.length === 3) {
        c = c.split('').map(x => x + x).join('');
    }
    const num = parseInt(c, 16);
    if (isNaN(num)) return '124, 58, 237';
    const r = (num >> 16) & 255;
    const g = (num >> 8) & 255;
    const b = num & 255;
    return `${r}, ${g}, ${b}`;
}

function updateModalColorPreview(color) {
    const iconPreview = document.getElementById('modalGameIconPreview');
    if (!iconPreview) return;
    const rgb = hexToRgb(color);
    iconPreview.style.background = `linear-gradient(135deg, ${color} 0%, rgba(${rgb}, 0.65) 100%)`;
    iconPreview.style.boxShadow = `0 4px 18px rgba(${rgb}, 0.45)`;
}

function updateColorPresetsActive(selectedColor) {
    const sel = (selectedColor || '').toLowerCase();
    document.querySelectorAll('#gameColorPresets .btn-color-preset').forEach(btn => {
        const btnCol = (btn.dataset.color || '').toLowerCase();
        btn.classList.toggle('active', btnCol === sel);
    });
}

