    if (colorInput) colorInput.value = color;
    if (colorHex) colorHex.textContent = color;
    updateModalColorPreview(color);
    updateColorPresetsActive(color);

    const socials = game.social_links || {};
    document.getElementById('gameProfileTikTok').value = socials.tiktok || '';
