async function testFootageFolder() {
    const footageInput = document.getElementById('gameProfileFootage');
    const resultBox = document.getElementById('footageScanResult');
    if (!footageInput || !resultBox) return;

    const folderPath = footageInput.value.trim();
    if (!folderPath) {
        resultBox.className = 'scan-result-pill warning';
        resultBox.style.display = 'block';
        resultBox.textContent = 'Ingresa una ruta de carpeta para escanear.';
        return;
    }

    resultBox.className = 'scan-result-pill';
    resultBox.style.display = 'block';
    resultBox.textContent = 'Escaneando carpeta en el sistema...';

    try {
        const res = await fetch('/api/gamedev/check-folder', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ folder_path: folderPath }),
        });
        const data = await res.json();

        if (data.exists && data.is_dir) {
            resultBox.className = 'scan-result-pill success';
            const filesSample = (data.video_files && data.video_files.length) ? ` (Ej: ${data.video_files.slice(0, 3).join(', ')})` : '';
            resultBox.innerHTML = `✓ Carpeta verificada: <strong>${data.video_count} clips de video encontrados</strong>${escapeHtml(filesSample)}<br><small style="opacity: 0.8;">Ruta: ${escapeHtml(data.resolved_path)}</small>`;
        } else {
            resultBox.className = 'scan-result-pill warning';
            resultBox.innerHTML = `⚠️ La carpeta no existe aún o no es un directorio accesible. Puedes crearla más tarde.`;
        }
    } catch (e) {
        resultBox.className = 'scan-result-pill warning';
        resultBox.textContent = 'Error al verificar carpeta: ' + e.message;
    }
}

async function openFootageFolder(folderPath, gameId = null) {
    if (!folderPath) {
        showToast('No hay ruta de carpeta configurada para este juego', 'warning');
        return;
    }

    // The server opens folders only for saved game profiles
    // (POST /api/gamedev/games/{game_id}/open-folder), never arbitrary paths.
    const games = (state.gamedev && Array.isArray(state.gamedev.games)) ? state.gamedev.games : [];
    const resolvedId = gameId || (games.find(g => g.footage_folder === folderPath) || {}).id || null;
    if (!resolvedId) {
        showToast('Guarda primero el perfil del juego para crear y abrir su carpeta de footage.', 'warning');
        return;
    }

    try {
        const res = await fetch(`/api/gamedev/games/${encodeURIComponent(resolvedId)}/open-folder`, {
            method: 'POST',
        });
        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || `HTTP ${res.status}`);
        }
        const data = await res.json();
        if (data.status === 'ok') {
            showToast(`Abriendo carpeta en el Explorador: ${folderPath}`, 'info');
        } else {
            showToast(`No se pudo abrir la carpeta: ${data.message || 'Error'}`, 'error');
        }
    } catch (e) {
        showToast('Error al abrir la carpeta: ' + e.message, 'error');
    }
}

async function saveGameProfile() {
    const id = document.getElementById('gameProfileId').value.trim();
    const name = document.getElementById('gameProfileName').value.trim();
    const icon = document.getElementById('gameProfileIcon').value.trim() || '🎮';
    let footage = document.getElementById('gameProfileFootage').value.trim();
    const tiktok = document.getElementById('gameProfileTikTok').value.trim();
    const instagram = document.getElementById('gameProfileInstagram').value.trim();
    const youtube = document.getElementById('gameProfileYouTube').value.trim();
    const steam = document.getElementById('gameProfileSteam').value.trim();
    const desc = document.getElementById('gameProfileDesc').value.trim();

    if (!name) {
        showToast('El nombre del videojuego es obligatorio', 'warning');
        document.getElementById('gameProfileName').focus();
        return;
    }

    // Si no se especificó carpeta, se asigna automáticamente a GamesFootage/<SanitizedGameName>
    if (!footage) {
        const safeName = sanitizeFolderName(name);
        footage = safeName ? `GamesFootage/${safeName}` : 'GamesFootage/Default';
    }

    const accentColor = document.getElementById('gameProfileColor')?.value || '#7c3aed';

    const payload = {
        name: name,
        icon: icon,
        accent_color: accentColor,
        footage_folder: footage,
        steam_app_id: steam,
        social_links: {
            tiktok: tiktok,
            instagram: instagram,
            youtube: youtube,
            steam: steam,
        },
        description: desc,
    };

    const isEdit = Boolean(id);
    const url = isEdit ? `/api/gamedev/games/${id}` : '/api/gamedev/games';
    const method = isEdit ? 'PUT' : 'POST';

    try {
        const res = await fetch(url, {
            method: method,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.detail || 'Error al guardar el perfil del juego');
        }

        const data = await res.json();
        closeGameModal();
        showToast(isEdit ? `Perfil "${name}" actualizado con éxito` : `Perfil "${name}" creado con éxito`, 'success');

        if (!isEdit && data.game && data.game.id) {
            state.gamedev.activeGameId = data.game.id;
            localStorage.setItem('gamedev_active_game_id', data.game.id);
        }

        await loadGameProfiles();
        if (state.gamedev.currentDashboardGameId) {
            await loadGameSteamImpact(state.gamedev.currentDashboardGameId);
        }
    } catch (e) {
        showToast('Error: ' + e.message, 'error');
    }
}

async function deleteGameProfile(gameId) {
    const game = state.gamedev.games.find(g => g.id === gameId);
    const gameName = game ? game.name : 'este juego';

    if (!confirm(`¿Estás seguro de que deseas eliminar el perfil de "${gameName}"? Esta acción no se puede deshacer.`)) {
        return;
    }

    try {
        const res = await fetch(`/api/gamedev/games/${gameId}`, {
            method: 'DELETE',
        });

        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Error al eliminar el perfil');
        }

        showToast(`Perfil de "${gameName}" eliminado`, 'info');

        if (state.gamedev.activeGameId === gameId) {
            state.gamedev.activeGameId = null;
            localStorage.removeItem('gamedev_active_game_id');
        }

        await loadGameProfiles();
    } catch (e) {
        showToast('Error al eliminar: ' + e.message, 'error');
    }
}

function startGamedevV1Pipeline(gameId) {
    const game = state.gamedev.games.find(g => g.id === gameId);
    if (!game) return;

    const ytUrl = game.social_links && game.social_links.youtube;
    if (ytUrl && ytUrl.includes('watch?v=')) {
        startV1Pipeline(ytUrl, game.name);
    } else {
        const inputUrl = prompt(`Introduce la URL de YouTube del vídeo o trailer de "${game.name}" para procesar con Short V1 IA:`);
        if (inputUrl && inputUrl.trim()) {
            startV1Pipeline(inputUrl.trim(), game.name);
        }
    }
}

