function initGamedevFootageAndGeneratorControls() {
    // Footage Dropzone and File Input
    const dropzone = document.getElementById('gamedevFootageDropzone');
    const fileInput = document.getElementById('gamedevFootageFileInput');

    if (dropzone && fileInput) {
        dropzone.addEventListener('click', () => fileInput.click());

        dropzone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropzone.classList.add('drag-over');
        });

        dropzone.addEventListener('dragleave', () => {
            dropzone.classList.remove('drag-over');
        });

        dropzone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropzone.classList.remove('drag-over');
            if (e.dataTransfer.files && e.dataTransfer.files.length) {
                handleGameFootageUpload(Array.from(e.dataTransfer.files), state.gamedev.currentDashboardGameId);
            }
        });

        fileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files.length) {
                handleGameFootageUpload(Array.from(e.target.files), state.gamedev.currentDashboardGameId);
                e.target.value = '';
            }
        });
    }

    // Footage Action Buttons
    const btnOpenFolder = document.getElementById('btnGamedevOpenFolder');
    if (btnOpenFolder) btnOpenFolder.addEventListener('click', openCurrentGameFootageFolder);

    const btnRefreshFootage = document.getElementById('btnGamedevRefreshFootage');
    if (btnRefreshFootage) btnRefreshFootage.addEventListener('click', () => {
        if (state.gamedev.currentDashboardGameId) loadGameFootage(state.gamedev.currentDashboardGameId);
    });

    const btnGoToGen = document.getElementById('btnGamedevGoToGeneratorFromFootage');
    if (btnGoToGen) btnGoToGen.addEventListener('click', () => switchDashboardTab('generator'));

    const btnManageClips = document.getElementById('btnGenManageFootage');
    if (btnManageClips) btnManageClips.addEventListener('click', () => switchDashboardTab('footage'));

    const btnSelectAll = document.getElementById('btnSelectAllFootage');
    if (btnSelectAll) btnSelectAll.addEventListener('click', selectAllFootageClips);

    const btnDeselectAll = document.getElementById('btnDeselectAllFootage');
    if (btnDeselectAll) btnDeselectAll.addEventListener('click', deselectAllFootageClips);

    // Generator: Framing Pills (9:16 vs 16:9)
    document.querySelectorAll('#gamedevFramingPills .format-pill-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('#gamedevFramingPills .format-pill-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            state.gamedev.generator.framing = btn.dataset.framing || 'vertical_split_blur';
            updateGamedevGeneratorMockup();
        });
    });

    // Generator: Resolution Pills (1080p vs 4K)
    document.querySelectorAll('#gamedevResolutionPills .res-pill-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('#gamedevResolutionPills .res-pill-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            state.gamedev.generator.resolution = btn.dataset.res || '1080p';
            updateGamedevGeneratorMockup();
        });
    });

    // Generator: Production Mode Radios
    document.querySelectorAll('input[name="gamedevGenMode"]').forEach(radio => {
        radio.addEventListener('change', (e) => {
            const mode = e.target.value;
            state.gamedev.generator.mode = mode;

            document.querySelectorAll('#dashPaneGenerator .radio-card').forEach(card => card.classList.remove('active'));
            const parentCard = e.target.closest('.radio-card');
            if (parentCard) parentCard.classList.add('active');

            const visualSec = document.getElementById('gamedevVisualSection');
            const hookSec = document.getElementById('gamedevHookSection');
            const durationGroup = document.getElementById('gamedevTargetDurationGroup');
            const stripSplashGroup = document.getElementById('gamedevStripSplashGroup');

            if (mode === 'v1_only') {
                if (visualSec) visualSec.style.opacity = '0.4';
                if (hookSec) hookSec.style.opacity = '0.4';
                if (durationGroup) durationGroup.style.display = 'block';
                if (stripSplashGroup) stripSplashGroup.style.display = 'block';
            } else if (mode === 'card_only') {
                if (visualSec) visualSec.style.opacity = '1';
                if (hookSec) hookSec.style.opacity = '1';
                if (durationGroup) durationGroup.style.display = 'none';
                if (stripSplashGroup) stripSplashGroup.style.display = 'none';
            } else {
                // v1_and_card
                if (visualSec) visualSec.style.opacity = '1';
                if (hookSec) hookSec.style.opacity = '1';
                if (durationGroup) durationGroup.style.display = 'block';
                if (stripSplashGroup) stripSplashGroup.style.display = 'block';
            }

            updateGamedevGeneratorMockup();
        });
    });

    // Generator: Target Duration Select
    const durationSelect = document.getElementById('gamedevTargetDuration');
    if (durationSelect) {
        durationSelect.addEventListener('change', (e) => {
            state.gamedev.generator.targetDuration = Number(e.target.value) || 30;
        });
    }

    // Generator: Video Count Pills
    document.querySelectorAll('#gamedevVideoCountPills .vcount-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('#gamedevVideoCountPills .vcount-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            const count = parseInt(btn.dataset.count || '1', 10);
            state.gamedev.generator.videoCount = count;

            // Toggle hook variant tabs visibility
            document.querySelectorAll('#gamedevHookTabs .hook-vtab').forEach(vtab => {
                const idx = parseInt(vtab.dataset.vidx || '0', 10);
                vtab.style.display = (idx < count) ? 'inline-block' : 'none';
            });

            // If active tab is now hidden, reset to 0
            if (state.gamedev.generator.activeHookIdx >= count) {
                setGamedevActiveHookTab(0);
            }

            updateGamedevGeneratorMockup();
        });
    });

    // Generator: Strip Splash Checkbox
    const stripSplashCheck = document.getElementById('gamedevStripSplash');
    if (stripSplashCheck) {
        stripSplashCheck.addEventListener('change', (e) => {
            state.gamedev.generator.stripSplash = e.target.checked;
        });
    }

    // Generator: AI Hook Generation Button
    const btnGenHook = document.getElementById('btnGamedevGenHook');
    if (btnGenHook) btnGenHook.addEventListener('click', generateGamedevHooks);

    // Generator: Hook Length Buttons
    const btnShorter = document.getElementById('btnGamedevHookShorter');
    if (btnShorter) btnShorter.addEventListener('click', () => modifyGamedevHookLength('shorter'));

    const btnLonger = document.getElementById('btnGamedevHookLonger');
    if (btnLonger) btnLonger.addEventListener('click', () => modifyGamedevHookLength('longer'));

    // Generator: Hook Variant Tabs Click
    document.querySelectorAll('#gamedevHookTabs .hook-vtab').forEach(btn => {
        btn.addEventListener('click', () => {
            const idx = parseInt(btn.dataset.vidx || '0', 10);
            setGamedevActiveHookTab(idx);
        });
    });

    // Generator: Hook Textareas Input Sync
    [0, 1, 2].forEach(idx => {
        const textarea = document.getElementById(`gamedevHookText${idx}`);
        if (textarea) {
            textarea.addEventListener('input', (e) => {
                state.gamedev.generator.hookTexts[idx] = e.target.value;
                updateGamedevGeneratorMockup();
            });
        }
    });

    // Generator: Overlay Style Pills (instagram_classic vs card)
    document.querySelectorAll('#gamedevOverlayPills .overlay-pill-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('#gamedevOverlayPills .overlay-pill-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            state.gamedev.generator.overlayType = btn.dataset.overlay || 'instagram_classic';
            updateGamedevGeneratorMockup();
        });
    });

    // Generator: Text Color Picker
    const textColorInput = document.getElementById('gamedevTextColor');
    if (textColorInput) {
        textColorInput.addEventListener('input', (e) => {
            state.gamedev.generator.textColor = e.target.value;
            const hexEl = document.getElementById('gamedevTextColorHex');
            if (hexEl) hexEl.textContent = e.target.value;
            updateGamedevGeneratorMockup();
        });
    }

    // Generator: Sliders
    const sliders = [
        { id: 'sliderGamedevFontSize', prop: 'fontSize', num: true },
        { id: 'sliderGamedevCardWidth', prop: 'cardWidth', num: true },
        { id: 'sliderGamedevCardHeight', prop: 'cardHeight', num: true },
        { id: 'sliderGamedevCardY', prop: 'cardY', num: true },
        { id: 'sliderGamedevVideoZoom', prop: 'videoZoom', num: true, isFloat: true },
        { id: 'sliderGamedevVideoY', prop: 'videoY', num: true },
    ];

    sliders.forEach(s => {
        const el = document.getElementById(s.id);
        if (el) {
            el.addEventListener('input', (e) => {
                const val = s.isFloat ? parseFloat(e.target.value) : parseInt(e.target.value, 10);
                state.gamedev.generator[s.prop] = val;
                updateGamedevGeneratorMockup();
            });
        }
    });

    // Generator: Launch Promo Generation Button
    const btnLaunch = document.getElementById('btnLaunchGamedevGen');
    if (btnLaunch) btnLaunch.addEventListener('click', startGamedevPromoGeneration);

    // Generator: Open Output Folder Button
    const btnOpenOut = document.getElementById('btnGamedevOpenOutputFolder');
    if (btnOpenOut) btnOpenOut.addEventListener('click', openOutputFolder);
}

async function openOutputFolder() {
    try {
        await fetch('/api/v1/open-output-folder', { method: 'POST' });
        showToast('Carpeta output abierta en el explorador', 'info');
    } catch (e) {
        showToast('Error abriendo carpeta output: ' + e, 'error');
    }
}
window.openOutputFolder = openOutputFolder;

function setGamedevActiveHookTab(idx) {
    state.gamedev.generator.activeHookIdx = idx;

    document.querySelectorAll('#gamedevHookTabs .hook-vtab').forEach(b => {
        b.classList.toggle('active', parseInt(b.dataset.vidx, 10) === idx);
    });

    [0, 1, 2].forEach(i => {
        const el = document.getElementById(`gamedevHookText${i}`);
        if (el) el.style.display = (i === idx) ? 'block' : 'none';
    });

    updateGamedevGeneratorMockup();
}

async function loadGameFootage(gameId) {
    if (!gameId) gameId = state.gamedev.currentDashboardGameId;
    if (!gameId) return;

    const iconRefresh = document.getElementById('iconRefreshFootage');
    if (iconRefresh) iconRefresh.classList.add('spinning');

    try {
        const res = await fetch(`/api/gamedev/games/${gameId}/footage`);
        if (!res.ok) throw new Error('Error al consultar clips de footage');
        const data = await res.json();

        state.gamedev.footageClips = data.footage_files || [];
        
        // Update folder path banner
        const pathEl = document.getElementById('gamedevFootageFolderPath');
        if (pathEl) pathEl.textContent = data.footage_folder || 'GamesFootage/...';

        // Update badges
        const count = state.gamedev.footageClips.length;
        const countBadge = document.getElementById('gamedevFootageTotalBadge');
        if (countBadge) countBadge.textContent = `${count} ${count === 1 ? 'clip' : 'clips'}`;
        
        const tabCountBadge = document.getElementById('dashFootageTabCount');
        if (tabCountBadge) tabCountBadge.textContent = count;

        // Auto-select clips if none selected yet
        if (!state.gamedev.selectedFootageFilenames || state.gamedev.selectedFootageFilenames.length === 0) {
            state.gamedev.selectedFootageFilenames = state.gamedev.footageClips.map(c => c.filename);
        } else {
            // Keep only existing filenames
            const validNames = state.gamedev.footageClips.map(c => c.filename);
            state.gamedev.selectedFootageFilenames = state.gamedev.selectedFootageFilenames.filter(fn => validNames.includes(fn));
            if (state.gamedev.selectedFootageFilenames.length === 0 && state.gamedev.footageClips.length > 0) {
                state.gamedev.selectedFootageFilenames = state.gamedev.footageClips.map(c => c.filename);
            }
        }

        renderGameFootageGrid();
        updateGeneratorSelectedFootage();
    } catch (e) {
        console.error('loadGameFootage error:', e);
    } finally {
        if (iconRefresh) iconRefresh.classList.remove('spinning');
    }
}

function renderGameFootageGrid() {
    const grid = document.getElementById('gamedevFootageGrid');
    if (!grid) return;

    const clips = state.gamedev.footageClips || [];
    const selected = state.gamedev.selectedFootageFilenames || [];

    // Update selected counter pill
    const selectedPill = document.getElementById('gamedevSelectedClipsPill');
    if (selectedPill) selectedPill.textContent = `${selected.length} de ${clips.length} seleccionados para el generador`;

    const btnCountPill = document.getElementById('btnFootageSelectedCount');
    if (btnCountPill) btnCountPill.textContent = selected.length;

    if (clips.length === 0) {
        grid.innerHTML = `
            <div style="grid-column: 1 / -1; text-align: center; padding: 48px 20px; background: rgba(255, 255, 255, 0.02); border: 1px dashed rgba(255, 255, 255, 0.1); border-radius: 12px;">
                <div style="font-size: 40px; margin-bottom: 10px;">📁</div>
                <h4 style="font-size: 16px; font-weight: 700; color: #fff; margin: 0 0 6px 0;">No hay clips en la carpeta de este juego todavía</h4>
                <p style="font-size: 13px; color: var(--text-muted); margin: 0 0 16px 0;">Arrastra clips de gameplay a la zona superior o copia archivos directamente a la carpeta del juego.</p>
                <button type="button" class="btn btn-secondary btn-sm" onclick="openCurrentGameFootageFolder()"><span>📂</span> Abrir Carpeta en Explorador</button>
            </div>
        `;
        return;
    }

    grid.innerHTML = clips.map(clip => {
        const isSel = selected.includes(clip.filename);
        const videoSrc = clip.url || '';
        const sizeStr = clip.size_formatted || '0 MB';
        const dateStr = clip.modified_at ? clip.modified_at.slice(0, 10) : '';

        return `
            <div class="footage-card ${isSel ? 'selected' : ''}" data-filename="${escapeHtml(clip.filename)}">
                <div class="footage-card-select-overlay">
                    <input type="checkbox" ${isSel ? 'checked' : ''} data-action="footage-toggle" data-action-event="change" data-filename="${escapeHtml(clip.filename)}" title="Seleccionar para el generador">
                </div>
                <div class="footage-thumb-wrap" data-action="footage-toggle" data-filename="${escapeHtml(clip.filename)}">
                    ${videoSrc ? `
                        <video src="${escapeHtml(videoSrc)}" preload="metadata" muted class="footage-thumb-video" onmouseover="this.play()" onmouseout="this.pause();this.currentTime=0;"></video>
                    ` : `
                        <div class="footage-thumb-placeholder">🎬</div>
                    `}
                </div>
                <div class="footage-card-meta">
                    <span class="footage-card-filename" title="${escapeHtml(clip.filename)}">${escapeHtml(clip.filename)}</span>
                    <div class="footage-card-details">
                        <span>📦 ${escapeHtml(sizeStr)}</span>
                        <span>📅 ${escapeHtml(dateStr)}</span>
                    </div>
                </div>
                <div class="footage-card-actions">
                    <span style="font-size: 11px; color: ${isSel ? '#a78bfa' : '#64748b'}; font-weight: 600;">
                        ${isSel ? '✓ Seleccionado' : '⚪ Deseleccionado'}
                    </span>
                    <button type="button" class="btn-del-footage" data-action="footage-delete" data-game-id="${escapeHtml(state.gamedev.currentDashboardGameId)}" data-filename="${escapeHtml(clip.filename)}" title="Eliminar clip">
                        🗑️
                    </button>
                </div>
            </div>
        `;
    }).join('');
    bindDataActions(grid);
}

function toggleFootageClipSelection(filename) {
    if (!filename) return;
    let selected = [...(state.gamedev.selectedFootageFilenames || [])];
    if (selected.includes(filename)) {
        selected = selected.filter(f => f !== filename);
    } else {
        selected.push(filename);
    }
    state.gamedev.selectedFootageFilenames = selected;
    renderGameFootageGrid();
    updateGeneratorSelectedFootage();
}

function selectAllFootageClips() {
    state.gamedev.selectedFootageFilenames = (state.gamedev.footageClips || []).map(c => c.filename);
    renderGameFootageGrid();
    updateGeneratorSelectedFootage();
}

function deselectAllFootageClips() {
    state.gamedev.selectedFootageFilenames = [];
    renderGameFootageGrid();
    updateGeneratorSelectedFootage();
}

async function handleGameFootageUpload(files, gameId) {
    if (!files || files.length === 0) return;
    if (!gameId) gameId = state.gamedev.currentDashboardGameId;
    if (!gameId) return;

    const progressBox = document.getElementById('gamedevUploadProgress');
    const progressBar = document.getElementById('gamedevUploadProgressBar');
    const progressText = document.getElementById('gamedevUploadProgressText');

    if (progressBox) progressBox.style.display = 'flex';
    if (progressText) progressText.textContent = `Subiendo ${files.length} archivo(s)...`;

    const formData = new FormData();
    for (const file of files) {
        formData.append('files', file);
    }

    try {
        const res = await fetch(`/api/gamedev/games/${gameId}/footage/upload`, {
            method: 'POST',
            body: formData,
        });

        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Error al subir vídeos');
        }

        const data = await res.json();
        showToast(data.message || '¡Footage subido con éxito!', 'success');

        await loadGameFootage(gameId);
        loadGameProfiles();
    } catch (e) {
        console.error('handleGameFootageUpload error:', e);
        showToast('Error al subir archivos: ' + e.message, 'error');
    } finally {
        if (progressBox) progressBox.style.display = 'none';
    }
}

async function deleteGameFootageClip(gameId, filename) {
    if (!confirm(`¿Eliminar el clip "${filename}"?`)) return;

    try {
        const res = await fetch(`/api/gamedev/games/${gameId}/footage/${encodeURIComponent(filename)}`, {
            method: 'DELETE',
        });
        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Error al eliminar clip');
        }
        showToast(`Clip "${filename}" eliminado`, 'info');
        await loadGameFootage(gameId);
        loadGameProfiles();
    } catch (e) {
        console.error('deleteGameFootageClip error:', e);
        showToast('Error: ' + e.message, 'error');
    }
}

async function openCurrentGameFootageFolder() {
    const gameId = state.gamedev.currentDashboardGameId;
    if (!gameId) return;
    try {
        const res = await fetch(`/api/gamedev/games/${encodeURIComponent(gameId)}/open-folder`, { method: 'POST' });
        const data = await res.json();
        if (data.status === 'ok') {
            showToast('Carpeta abierta en el Explorador de archivos', 'info');
        } else {
            showToast('No se pudo abrir la carpeta: ' + (data.message || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error: ' + e.message, 'error');
    }
}

function updateGeneratorSelectedFootage() {
    const clips = state.gamedev.footageClips || [];
    const selFilenames = state.gamedev.selectedFootageFilenames || [];
    const selected = clips.filter(c => selFilenames.includes(c.filename));

    state.gamedev.generator.selectedFootage = selected;

    const countEl = document.getElementById('genSelectedFootageCount');
    if (countEl) countEl.textContent = `${selected.length} ${selected.length === 1 ? 'clip seleccionado' : 'clips seleccionados'}`;

    const chipsWrap = document.getElementById('genFootageChips');
    if (chipsWrap) {
        if (selected.length === 0) {
            chipsWrap.innerHTML = `<span style="font-size: 12px; color: #ef4444;">⚠️ Ningún clip seleccionado. Se utilizarán todos los clips disponibles en la carpeta al generar.</span>`;
        } else {
            chipsWrap.innerHTML = selected.map(c => `
                <span class="gen-footage-chip" title="${escapeHtml(c.filename)}">
                    <span>🎬 ${escapeHtml(c.filename)}</span>
                    <span class="chip-remove" data-action="footage-toggle" data-filename="${escapeHtml(c.filename)}" title="Quitar clip">✕</span>
                </span>
            `).join('');
            bindDataActions(chipsWrap);
        }
    }

    updateGamedevGeneratorMockup();
}

function initGamedevGenerator(gameId) {
    if (!gameId) gameId = state.gamedev.currentDashboardGameId;
    if (!gameId) return;

    const game = state.gamedev.games.find(g => g.id === gameId);
    if (!game) return;

    // If hooks are not initialized, set defaults
    const currentHooks = state.gamedev.generator.hookTexts;
    if (!currentHooks[0] || !currentHooks[0].trim()) {
        const defaultHook = game.description ? game.description.slice(0, 120) : `¡Descubre ${game.name}! Un gameplay increíble que tienes que probar. 🎮🔥`;
        state.gamedev.generator.hookTexts[0] = defaultHook;
        state.gamedev.generator.hookTexts[1] = `¿Buscabas un nuevo juego? ${game.name} tiene mecánicas únicas que te engancharán. 🚀`;
        state.gamedev.generator.hookTexts[2] = `No te pierdas ${game.name}. ¡Añádelo a tu Wishlist de Steam ahora! ⭐`;
    }

    [0, 1, 2].forEach(i => {
        const textarea = document.getElementById(`gamedevHookText${i}`);
        if (textarea) textarea.value = state.gamedev.generator.hookTexts[i] || '';
    });

    updateGeneratorSelectedFootage();
    updateGamedevGeneratorMockup();
}

function updateGamedevGeneratorMockup() {
    const gen = state.gamedev.generator;
    const game = state.gamedev.games.find(g => g.id === state.gamedev.currentDashboardGameId);
    const gameName = game ? game.name : 'Game Title';

    // 1. Framing format (9:16 vs 16:9)
    const frame = document.getElementById('gamedevMockupFrame');
    const is169 = gen.framing === 'fit_16_9';
    if (frame) {
        frame.classList.toggle('mode-16-9', is169);
    }

    // 2. Format Tag
    const tag = document.getElementById('gamedevMockupFormatTag');
    if (tag) {
        tag.textContent = `${is169 ? '16:9 Panorámico' : '9:16 Vertical'} (${gen.resolution})`;
    }

    // 3. Slider Value Badges
    const badgeFontSize = document.getElementById('valGamedevFontSize');
    if (badgeFontSize) badgeFontSize.textContent = `${gen.fontSize} px`;

    const badgeCardWidth = document.getElementById('valGamedevCardWidth');
    if (badgeCardWidth) badgeCardWidth.textContent = `${gen.cardWidth} px`;

    const badgeCardHeight = document.getElementById('valGamedevCardHeight');
    if (badgeCardHeight) badgeCardHeight.textContent = `${gen.cardHeight} px`;

    const badgeCardY = document.getElementById('valGamedevCardY');
    if (badgeCardY) badgeCardY.textContent = `${gen.cardY} px`;

    const badgeZoom = document.getElementById('valGamedevVideoZoom');
    if (badgeZoom) badgeZoom.textContent = `${gen.videoZoom.toFixed(2)}x`;

    const badgeVideoY = document.getElementById('valGamedevVideoY');
    if (badgeVideoY) badgeVideoY.textContent = `${gen.videoY} px`;

    const colorHex = document.getElementById('gamedevTextColorHex');
    if (colorHex) colorHex.textContent = gen.textColor;

    // 4. Video Source in Mockup
    const selectedFootage = (gen.selectedFootage && gen.selectedFootage.length > 0)
        ? gen.selectedFootage
        : (state.gamedev.footageClips || []);

    const videoEl = document.getElementById('gamedevMockupVideoPlayer');
    const noVideoPlaceholder = document.getElementById('gamedevMockupNoVideo');
    const bgBlur = document.getElementById('gamedevMockupBgBlur');
    const gameplayBox = document.getElementById('gamedevMockupGameplayBox');

    if (selectedFootage.length > 0 && selectedFootage[0].url) {
        const clipUrl = selectedFootage[0].url;
        if (videoEl && (!videoEl.src || !videoEl.src.endsWith(clipUrl))) {
            videoEl.src = clipUrl;
            videoEl.play().catch(() => {});
        }
        if (videoEl) videoEl.style.display = 'block';
        if (noVideoPlaceholder) noVideoPlaceholder.style.display = 'none';

        if (bgBlur) {
            bgBlur.style.background = `radial-gradient(circle at center, ${game?.accent_color || '#7c3aed'} 0%, #09090b 70%)`;
        }
    } else {
        if (videoEl) {
            videoEl.pause();
            videoEl.removeAttribute('src');
            videoEl.style.display = 'none';
        }
        if (noVideoPlaceholder) noVideoPlaceholder.style.display = 'flex';
        if (bgBlur) {
            bgBlur.style.background = `radial-gradient(circle at center, ${game?.accent_color || '#7c3aed'} 0%, #09090b 70%)`;
        }
    }

    if (gameplayBox && !is169) {
        const scaledZoom = gen.videoZoom || 1.0;
        const scaledY = (gen.videoY || 180) * 0.25;
        gameplayBox.style.transform = `translate(-50%, calc(-50% + ${scaledY}px)) scale(${scaledZoom})`;
    } else if (gameplayBox) {
        gameplayBox.style.transform = 'none';
    }

    // 5. Text & Overlay Rendering
    const currentHook = (gen.hookTexts && gen.hookTexts[gen.activeHookIdx]) || `¡Descubre ${gameName}! Un gameplay increíble que tienes que probar. 🎮🔥`;
    const instaText = document.getElementById('gamedevMockupInstaText');
    const socialCard = document.getElementById('gamedevMockupCard');

    if (gen.overlayType === 'instagram_classic') {
        if (instaText) {
            instaText.style.display = 'block';
            instaText.textContent = currentHook;
            instaText.style.color = gen.textColor || '#ffffff';
            
            // Proportional scaling for preview frame
            const scaleRatio = is169 ? 0.18 : 0.23;
            instaText.style.fontSize = `${Math.max(10, Math.round(gen.fontSize * scaleRatio))}px`;
            
            const widthPct = Math.min(94, Math.max(40, (gen.cardWidth / 1920) * 100));
            instaText.style.width = `${widthPct}%`;
            
            const topPos = is169 ? (gen.cardY * 0.18) : (gen.cardY * 0.24);
            instaText.style.top = `${Math.max(10, Math.min(frame?.clientHeight ? frame.clientHeight - 60 : 380, topPos))}px`;
        }
        if (socialCard) socialCard.style.display = 'none';
    } else {
        // Tarjeta Social
        if (instaText) instaText.style.display = 'none';
        if (socialCard) {
            socialCard.style.display = 'flex';
            const mcardUser = document.getElementById('gamedevMcardUser');
            if (mcardUser) mcardUser.textContent = gameName;
            const mcardHandle = document.getElementById('gamedevMcardHandle');
            if (mcardHandle) mcardHandle.textContent = `@${sanitizeFolderName(gameName).toLowerCase()}`;
            const mcardBody = document.getElementById('gamedevMcardBody');
            if (mcardBody) mcardBody.textContent = currentHook;
            
            const topPos = is169 ? (gen.cardY * 0.18) : (gen.cardY * 0.24);
            socialCard.style.top = `${Math.max(10, Math.min(frame?.clientHeight ? frame.clientHeight - 90 : 360, topPos))}px`;
        }
    }
}

async function generateGamedevHooks() {
    const game = state.gamedev.games.find(g => g.id === state.gamedev.currentDashboardGameId);
    if (!game) return;

    const btn = document.getElementById('btnGamedevGenHook');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>⏳</span> Generando con IA...';
    }

    try {
        // The UI always shows three hook slots; the server caps count at 3.
        const res = await fetch('/api/hook/generate-multiple', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_name: game.name,
                count: 3,
            }),
        });

        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            const detail = typeof err.detail === 'string' ? err.detail : (err.detail ? JSON.stringify(err.detail) : '');
            throw new Error(detail || 'Error al generar hooks con IA');
        }

        const data = await res.json();
        const hooks = Array.isArray(data.hooks) ? data.hooks.filter(h => typeof h === 'string' && h.trim()) : [];

        if (hooks.length > 0) {
            hooks.forEach((h, idx) => {
                if (idx < 3) {
                    state.gamedev.generator.hookTexts[idx] = h;
                    const el = document.getElementById(`gamedevHookText${idx}`);
                    if (el) el.value = h;
                }
            });
            showToast('¡Ganchos publicitarios generados con IA de Steam!', 'success');
            updateGamedevGeneratorMockup();
        } else {
            showToast('La IA no devolvió ganchos. Prueba de nuevo.', 'warning');
        }
    } catch (e) {
        console.error('generateGamedevHooks error:', e);
        showToast('Error: ' + e.message, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<span class="sparkle-icon">✨</span> Generar Hooks con IA (Steam)';
        }
    }
}

async function modifyGamedevHookLength(action) {
    const idx = state.gamedev.generator.activeHookIdx || 0;
    const currentText = (state.gamedev.generator.hookTexts[idx] || '').trim();
    if (!currentText) {
        showToast('Escribe primero un texto de gancho para modificarlo', 'warning');
        return;
    }

    const btn = document.getElementById(action === 'shorter' ? 'btnGamedevHookShorter' : 'btnGamedevHookLonger');
    if (btn) btn.disabled = true;

    try {
        const res = await fetch('/api/hook/modify', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                current_text: currentText,
                action: action,
            }),
        });

        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Error al modificar longitud');
        }

        const data = await res.json();
        if (data.hook) {
            state.gamedev.generator.hookTexts[idx] = data.hook;
            const el = document.getElementById(`gamedevHookText${idx}`);
            if (el) el.value = data.hook;
            showToast(`Hook ${action === 'shorter' ? 'acortado' : 'alargado'} con éxito`, 'success');
            updateGamedevGeneratorMockup();
        }
    } catch (e) {
        showToast('Error al modificar hook: ' + e.message, 'error');
    } finally {
        if (btn) btn.disabled = false;
    }
}

async function startGamedevPromoGeneration() {
    const game = state.gamedev.games.find(g => g.id === state.gamedev.currentDashboardGameId);
    if (!game) {
        showToast('No se encontró el perfil de juego activo', 'error');
        return;
    }

    if (state.gamedev.generator.isGenerating) {
        showToast('Ya hay una generación de promo en curso', 'warning');
        return;
    }

    // Determine footage clips to use
    let clipsToUse = state.gamedev.generator.selectedFootage || [];
    if (clipsToUse.length === 0) {
        clipsToUse = state.gamedev.footageClips || [];
    }

    if (clipsToUse.length === 0) {
        showToast('Debes subir o seleccionar al menos un clip de gameplay en la pestaña Footage', 'warning');
        switchDashboardTab('footage');
        return;
    }

    const footagePaths = clipsToUse.map(c => c.saved_path || c.filename).filter(Boolean);

    const count = state.gamedev.generator.videoCount || 1;
    const hooksToUse = state.gamedev.generator.hookTexts.slice(0, count).map(h => h.trim()).filter(Boolean);

    const payload = {
        footage_paths: footagePaths,
        game_name: game.name,
        mode: state.gamedev.generator.mode,
        video_count: count,
        target_duration: Number(state.gamedev.generator.targetDuration) || 30.0,
        framing: state.gamedev.generator.framing || 'vertical_split_blur',
        resolution: state.gamedev.generator.resolution || '1080p',
        strip_splash: Boolean(state.gamedev.generator.stripSplash),
        overlay_type: state.gamedev.generator.overlayType || 'instagram_classic',
        card_text_color: state.gamedev.generator.textColor || '#ffffff',
        card_font_size_body: Number(state.gamedev.generator.fontSize) || 76,
        card_width: Number(state.gamedev.generator.cardWidth) || 1600,
        card_height: Number(state.gamedev.generator.cardHeight) || 600,
        card_y_position: Number(state.gamedev.generator.cardY) || 440,
        video_zoom: Number(state.gamedev.generator.videoZoom) || 1.0,
        video_y_position: Number(state.gamedev.generator.videoY) || 180,
        hook_texts: hooksToUse.length > 0 ? hooksToUse : undefined,
        hook_text: hooksToUse[0] || `¡Descubre ${game.name}! Un gameplay increíble que tienes que probar. 🎮🔥`,
    };

    const btnLaunch = document.getElementById('btnLaunchGamedevGen');
    if (btnLaunch) {
        btnLaunch.disabled = true;
        btnLaunch.innerHTML = '<span class="gen-spinner-glow" style="width:16px;height:16px;border-width:2px;display:inline-block;"></span> Produciendo Vídeo...';
    }

    const progressBox = document.getElementById('gamedevGenProgressBox');
    const resultBox = document.getElementById('gamedevGenResultBox');
    if (progressBox) progressBox.style.display = 'flex';
    if (resultBox) resultBox.style.display = 'none';

    state.gamedev.generator.isGenerating = true;

    try {
        const res = await fetch('/api/promos/process', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });

        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Error al iniciar pipeline de promo');
        }

        const data = await res.json();
        const jobId = data.job_id;

        // Open SSE Stream
        if (state.gamedev.generator.eventSource) {
            state.gamedev.generator.eventSource.close();
        }

        const es = new EventSource(`/api/jobs/${jobId}/stream`);
        state.gamedev.generator.eventSource = es;

        es.onmessage = (event) => {
            try {
                const job = JSON.parse(event.data);
                const pct = Math.round(job.progress || 0);

                const pctEl = document.getElementById('gamedevProgressPct');
                const barEl = document.getElementById('gamedevProgressBar');
                const titleEl = document.getElementById('gamedevProgressTitle');
                const descEl = document.getElementById('gamedevProgressDesc');

                if (pctEl) pctEl.textContent = `${pct}%`;
                if (barEl) barEl.style.width = `${pct}%`;
                if (titleEl && job.stage) titleEl.textContent = job.stage;
                if (descEl && job.message) descEl.textContent = job.message;

                if (job.status === 'completed') {
                    es.close();
                    state.gamedev.generator.isGenerating = false;
                    if (progressBox) progressBox.style.display = 'none';
                    if (btnLaunch) {
                        btnLaunch.disabled = false;
                        btnLaunch.innerHTML = '<span class="btn-icon">🚀</span> Iniciar Generación de Promos';
                    }
                    showToast('🎉 ¡Vídeo(s) promocionales generados con éxito!', 'success');
                    renderGamedevPromoResults(job.result);
                } else if (job.status === 'failed') {
                    es.close();
                    state.gamedev.generator.isGenerating = false;
                    if (progressBox) progressBox.style.display = 'none';
                    if (btnLaunch) {
                        btnLaunch.disabled = false;
                        btnLaunch.innerHTML = '<span class="btn-icon">🚀</span> Iniciar Generación de Promos';
                    }
                    showToast('Error en la producción: ' + (job.error || 'Error desconocido'), 'error');
                }
            } catch (err) {
                console.error('Error parsing SSE event:', err);
            }
        };

        es.onerror = (err) => {
            console.error('SSE Error:', err);
            es.close();
            state.gamedev.generator.isGenerating = false;
            if (btnLaunch) {
                btnLaunch.disabled = false;
                btnLaunch.innerHTML = '<span class="btn-icon">🚀</span> Iniciar Generación de Promos';
            }
        };

    } catch (e) {
        state.gamedev.generator.isGenerating = false;
        if (progressBox) progressBox.style.display = 'none';
        if (btnLaunch) {
            btnLaunch.disabled = false;
            btnLaunch.innerHTML = '<span class="btn-icon">🚀</span> Iniciar Generación de Promos';
        }
        showToast('Error: ' + e.message, 'error');
    }
}

function renderGamedevPromoResults(result) {
    if (!result) return;
    const resultBox = document.getElementById('gamedevGenResultBox');
    if (!resultBox) return;

    resultBox.style.display = 'flex';
    resultBox.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

    const videos = result.videos || [
        {
            variant_index: 1,
            video_url: result.video_url,
            video_filename: result.video_filename,
            hook_text: result.title || '',
        }
    ];

    state.gamedev.generator.generatedVideos = videos;
    state.gamedev.generator.activeResultIdx = 0;

    // Render variant tabs
    const tabsContainer = document.getElementById('gamedevResultTabs');
    if (tabsContainer) {
        if (videos.length > 1) {
            tabsContainer.style.display = 'flex';
            tabsContainer.innerHTML = videos.map((v, i) => `
                <button type="button" class="result-vtab ${i === 0 ? 'active' : ''}" onclick="selectGamedevResultVariant(${i})">
                    Vídeo #${escapeHtml(v.variant_index || (i + 1))}
                </button>
            `).join('');
        } else {
            tabsContainer.style.display = 'none';
        }
    }

    selectGamedevResultVariant(0);
}

function selectGamedevResultVariant(idx) {
    const videos = state.gamedev.generator.generatedVideos || [];
    const video = videos[idx];
    if (!video) return;

    state.gamedev.generator.activeResultIdx = idx;

    document.querySelectorAll('#gamedevResultTabs .result-vtab').forEach((b, i) => {
        b.classList.toggle('active', i === idx);
    });

    const player = document.getElementById('gamedevResultVideoPlayer');
    if (player && video.video_url) {
        player.src = video.video_url;
        player.load();
    }

    const downloadBtn = document.getElementById('btnGamedevDownloadVideo');
    if (downloadBtn && video.video_url) {
        downloadBtn.href = video.video_url;
        downloadBtn.download = video.video_filename || 'promo_video.mp4';
    }
}

