// =============================================================================
// TAB: PROMOS & SHORTS IA CONTROLLER (WIZARD REDESIGN)
// =============================================================================

let promosEventSource = null;

function initPromosTab() {
    // -------------------------------------------------------------------------
    // 1. STEP 0: Footage Upload, GamesFootage Library & Formats
    // -------------------------------------------------------------------------
    const dropArea = document.getElementById('promosDropArea');
    const fileInput = document.getElementById('promosFootageInput');

    if (dropArea && fileInput) {
        dropArea.addEventListener('click', () => fileInput.click());

        dropArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropArea.classList.add('drag-over');
        });

        dropArea.addEventListener('dragleave', () => {
            dropArea.classList.remove('drag-over');
        });

        dropArea.addEventListener('drop', (e) => {
            e.preventDefault();
            dropArea.classList.remove('drag-over');
            if (e.dataTransfer.files && e.dataTransfer.files.length) {
                handlePromosFootageUpload(Array.from(e.dataTransfer.files));
            }
        });

        fileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files.length) {
                handlePromosFootageUpload(Array.from(e.target.files));
            }
        });
    }

    // YouTube Video Ingestion Handler (Promos tab)
    const btnPromosYt = document.getElementById('btnPromosIngestYoutube');
    if (btnPromosYt) {
        btnPromosYt.addEventListener('click', () => ingestYoutubeVideo('promosYoutubeUrl', 'promosGameName', 'btnPromosIngestYoutube', false));
    }
    const ytInputPromos = document.getElementById('promosYoutubeUrl');
    if (ytInputPromos) {
        ytInputPromos.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                ingestYoutubeVideo('promosYoutubeUrl', 'promosGameName', 'btnPromosIngestYoutube', false);
            }
        });
    }

    // Toggle: 9:16 Native Footage
    const toggle916 = document.getElementById('promosFootageIs916');
    if (toggle916) {
        toggle916.addEventListener('change', (e) => {
            const badge = document.getElementById('promosFootage916Badge');
            if (badge) badge.style.display = e.target.checked ? 'inline-block' : 'none';
            if (e.target.checked) {
                showToast('📱 Modo 9:16 Nativo activado: se omitirán recortes y ajustes de bordes.', 'info');
            }
        });
    }

    // Toggle: Pre-cut background video
    const precutInput = document.getElementById('promosV2PrecutVideo');
    if (precutInput) {
        precutInput.addEventListener('change', (e) => {
            state.promos.precutVideo = e.target.checked;
            const badge = document.getElementById('promosPrecutBadge');
            if (badge) badge.style.display = e.target.checked ? 'inline-block' : 'none';
            if (e.target.checked) {
                showToast('✂️ Vídeo precortado: ajustará directamente el vídeo al audio sin reanalizar planos.', 'info');
            }
        });
    }

    // PromosFootage Library Dropdown & Save Button
    const savedGamesSelect = document.getElementById('promosSavedGamesSelect');
    if (savedGamesSelect) {
        savedGamesSelect.addEventListener('change', (e) => {
            const folderName = e.target.value;
            if (!folderName) {
                resetPromosForNewGame();
                return;
            }
            const game = state.promos.savedGames.find(g => g.folder_name === folderName || g.game_name === folderName);
            if (game) {
                const gameNameInput = document.getElementById('promosGameName');
                if (gameNameInput) gameNameInput.value = game.game_name;

                const badge = document.getElementById('promosGameFolderBadge');
                if (badge) {
                    badge.style.display = 'inline-block';
                    badge.innerText = `📁 PromosFootage/${game.folder_name}`;
                }

                state.promos.uploadedFootage = (game.videos || []).map(v => ({
                    filename: v.filename,
                    saved_path: v.saved_path,
                    url: v.url,
                    size: v.size || (v.size_mb ? v.size_mb * 1024 * 1024 : 0),
                    has_breakdown: v.has_breakdown || false,
                }));

                renderPromosFootageList();
                updatePromosMockupDisplay();
                const bdNotice = game.has_breakdowns ? ' (¡con análisis IA listo!)' : '';
                showToast(`Cargados ${game.videos.length} clips de "${game.game_name}" de PromosFootage${bdNotice}`, 'success');
            }
        });
    }

    const btnNewGame = document.getElementById('btnPromosNewGame');
    if (btnNewGame) {
        btnNewGame.addEventListener('click', () => resetPromosForNewGame());
    }

    const btnRefreshLibrary = document.getElementById('btnPromosRefreshLibrary');
    if (btnRefreshLibrary) {
        btnRefreshLibrary.addEventListener('click', async () => {
            await loadPromosSavedGames();
            showToast('Lista de juegos de PromosFootage actualizada', 'info');
        });
    }

    const btnSaveFootage = document.getElementById('btnPromosSaveFootage');
    if (btnSaveFootage) {
        btnSaveFootage.addEventListener('click', async () => {
            const gameName = (document.getElementById('promosGameName')?.value || '').trim();
            if (!gameName) {
                showToast('Escribe primero el nombre del juego para crear su carpeta en PromosFootage', 'warning');
                return;
            }
            if (!state.promos.uploadedFootage || state.promos.uploadedFootage.length === 0) {
                showToast('Sube o añade al menos un clip de gameplay antes de guardar', 'warning');
                return;
            }

            btnSaveFootage.disabled = true;
            btnSaveFootage.innerHTML = '<span>⏳</span> Guardando...';

            try {
                const res = await fetch('/api/promos/library/save', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        game_name: gameName,
                        footage_paths: state.promos.uploadedFootage.map(c => c.saved_path),
                    }),
                });

                if (!res.ok) {
                    const err = await res.json().catch(() => ({}));
                    throw new Error(err.detail || `Error HTTP ${res.status}`);
                }

                const data = await res.json();
                state.promos.uploadedFootage = (data.videos || []).map(v => ({
                    filename: v.filename,
                    saved_path: v.saved_path,
                    url: v.url,
                    size: v.size || (v.size_mb ? v.size_mb * 1024 * 1024 : 0),
                    has_breakdown: v.has_breakdown || false,
                }));

                renderPromosFootageList();
                await loadPromosSavedGames(data.folder_name);

                const badge = document.getElementById('promosGameFolderBadge');
                if (badge) {
                    badge.style.display = 'inline-block';
                    badge.innerText = `📁 PromosFootage/${data.folder_name}`;
                }

                showToast(`✅ ${data.message || 'Footage guardado correctamente'}`, 'success');
            } catch (err) {
                showToast(`Error al guardar footage: ${err.message}`, 'error');
            } finally {
                btnSaveFootage.disabled = false;
                btnSaveFootage.innerHTML = '<span>💾</span> Guardar Footage';
            }
        });
    }

    const gameNameInput = document.getElementById('promosGameName');
    if (gameNameInput) {
        gameNameInput.addEventListener('input', (e) => {
            const val = e.target.value.trim();
            const badge = document.getElementById('promosGameFolderBadge');
            if (badge) {
                if (val) {
                    badge.style.display = 'inline-block';
                    badge.innerText = `📁 PromosFootage/${val}`;
                } else {
                    badge.style.display = 'none';
                }
            }
        });
    }

    // Step 0 Button: "Siguiente ➔" (Go to Step 1 Modal)
    const btnGoStep1 = document.getElementById('btnPromosGoStep1');
    if (btnGoStep1) {
        btnGoStep1.addEventListener('click', handlePromoStep0Next);
    }

    // -------------------------------------------------------------------------
    // 2. MODAL 1: Hook, Guión & Locución
    // -------------------------------------------------------------------------
    // Hook Cards Selection (Steam / So in this / Directo / Entrada propia)
    Object.entries(PROMO_HOOK_CARD_IDS).forEach(([hookValue, cardId]) => {
        const card = document.getElementById(cardId);
        if (card) card.addEventListener('click', () => setPromosHookType(hookValue));
    });
    const promosOpeningInput = document.getElementById('promosOpeningText');
    if (promosOpeningInput) {
        promosOpeningInput.addEventListener('input', () => { state.promos.openingText = promosOpeningInput.value; });
    }

    // Briefing and Tone
    const briefingInput = document.getElementById('promosV2Briefing');
    if (briefingInput) {
        briefingInput.addEventListener('input', (e) => {
            state.promos.v2BriefingText = e.target.value;
        });
    }

    const toneSelect = document.getElementById('promosV2ToneSelect');
    if (toneSelect) {
        toneSelect.addEventListener('change', (e) => {
            state.promos.v2Tone = e.target.value;
        });
    }

    // Script Toolbar Actions
    const btnGenScript = document.getElementById('btnPromosV2GenScript');
    if (btnGenScript) btnGenScript.addEventListener('click', generatePromosV2Script);

    const btnRegenScript = document.getElementById('btnPromosV2RegenScript');
    if (btnRegenScript) btnRegenScript.addEventListener('click', generatePromosV2Script);

    const btnV2Hook = document.getElementById('btnPromosV2ScriptHook');
    if (btnV2Hook) btnV2Hook.addEventListener('click', () => modifyPromosV2ScriptLength('change_hook'));

    const btnV2Shorter = document.getElementById('btnPromosV2ScriptShorter');
    if (btnV2Shorter) btnV2Shorter.addEventListener('click', () => modifyPromosV2ScriptLength('shorter'));

    const btnV2Longer = document.getElementById('btnPromosV2ScriptLonger');
    if (btnV2Longer) btnV2Longer.addEventListener('click', () => modifyPromosV2ScriptLength('longer'));

    const btnV2Viral = document.getElementById('btnPromosV2ScriptViral');
    if (btnV2Viral) btnV2Viral.addEventListener('click', () => modifyPromosV2ScriptLength('more_viral'));

    const btnV2CustomToggle = document.getElementById('btnPromosV2ScriptCustomToggle');
    const customBar = document.getElementById('promosV2CustomInstructionBar');
    const customInput = document.getElementById('promosV2CustomInstructionInput');
    const btnV2CancelCustom = document.getElementById('btnPromosV2CancelCustomInstruction');
    const btnV2ApplyCustom = document.getElementById('btnPromosV2ApplyCustomInstruction');

    if (btnV2CustomToggle && customBar) {
        btnV2CustomToggle.addEventListener('click', () => {
            const isHidden = customBar.style.display === 'none' || !customBar.style.display;
            customBar.style.display = isHidden ? 'block' : 'none';
            if (isHidden && customInput) {
                setTimeout(() => customInput.focus(), 50);
            }
        });
    }

    if (btnV2CancelCustom && customBar) {
        btnV2CancelCustom.addEventListener('click', () => {
            customBar.style.display = 'none';
        });
    }

    if (btnV2ApplyCustom) {
        btnV2ApplyCustom.addEventListener('click', () => {
            const instr = customInput ? customInput.value.trim() : '';
            if (!instr) {
                showToast('Escribe alguna indicación o petición para modificar el guión', 'info');
                return;
            }
            modifyPromosV2ScriptLength('custom_instruction', instr);
        });
    }

    if (customInput) {
        customInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                if (btnV2ApplyCustom) btnV2ApplyCustom.click();
            }
        });
    }

    const scriptInput = document.getElementById('promosV2ScriptText');
    if (scriptInput) {
        scriptInput.addEventListener('input', (e) => {
            state.promos.v2ScriptText = e.target.value;
            updatePromosV2Stats();
        });
    }

    // Voice Upload Dropzone in Modal 1
    const voiceDropArea = document.getElementById('promosVoiceDropArea');
    const voiceFileInput = document.getElementById('promosVoiceFileInput');
    if (voiceDropArea && voiceFileInput) {
        voiceDropArea.addEventListener('click', () => voiceFileInput.click());
        voiceDropArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            voiceDropArea.classList.add('dragover');
        });
        voiceDropArea.addEventListener('dragleave', () => {
            voiceDropArea.classList.remove('dragover');
        });
        voiceDropArea.addEventListener('drop', (e) => {
            e.preventDefault();
            voiceDropArea.classList.remove('dragover');
            if (e.dataTransfer.files && e.dataTransfer.files.length) {
                handlePromosVoiceUpload(e.dataTransfer.files[0]);
            }
        });
        voiceFileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files.length) {
                handlePromosVoiceUpload(e.target.files[0]);
            }
        });
    }

    const btnClearVoice = document.getElementById('btnPromosClearVoice');
    if (btnClearVoice) {
        btnClearVoice.addEventListener('click', () => {
            state.promos.v2VoicePath = '';
            state.promos.v2VoiceUrl = '';
            state.promos.v2VoiceDuration = 0;
            state.promos.v2VoiceFilename = '';
            const hidden = document.getElementById('promosVoicePath');
            if (hidden) hidden.value = '';
            const playerContainer = document.getElementById('promosVoicePlayerContainer');
            if (playerContainer) playerContainer.style.display = 'none';
            const audioElem = document.getElementById('promosVoiceAudioElem');
            if (audioElem) { audioElem.pause(); audioElem.src = ''; }
            const badgeEl = document.getElementById('promosVoiceStatusBadge');
            if (badgeEl) {
                badgeEl.innerText = 'ElevenLabs Activo';
                badgeEl.style.background = 'rgba(59, 130, 246, 0.15)';
                badgeEl.style.color = '#60a5fa';
            }
            showToast('Archivo de voz quitado: se sintetizará el guión con ElevenLabs', 'info');
        });
    }

    // Modal 1 Navigation Buttons
    const btnCloseModal1 = document.getElementById('btnClosePromoModal1');
    const btnCancelModal1 = document.getElementById('btnPromoModal1Cancel');
    const btnNextModal1 = document.getElementById('btnPromoModal1Next');

    if (btnCloseModal1) btnCloseModal1.addEventListener('click', closePromoModal1);
    if (btnCancelModal1) btnCancelModal1.addEventListener('click', closePromoModal1);
    if (btnNextModal1) {
        btnNextModal1.addEventListener('click', handlePromoModal1Next);
    }

    // -------------------------------------------------------------------------
    // 3. MODAL 2: Visuales & Live Mockup 1:1 Preview
    // -------------------------------------------------------------------------
    // Subtitle Size & Y Position
    const captionsSizeInput = document.getElementById('promosCaptionsSize');
    if (captionsSizeInput) {
        captionsSizeInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 86;
            state.promos.captionsSize = val;
            const label = document.getElementById('promosCaptionsSizeVal');
            if (label) label.innerText = `${val} px`;
            setPromosV2PreviewMode('captions');
        });
    }

    const captionsYInput = document.getElementById('promosCaptionsY');
    if (captionsYInput) {
        captionsYInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 450;
            state.promos.captionsY = val;
            const label = document.getElementById('promosCaptionsYVal');
            if (label) label.innerText = `${val} px`;
            setPromosV2PreviewMode('captions');
        });
    }

    // Subtitle Highlight Color Picker & Chips (Pastel + Vibrant)
    const captionsColorInput = document.getElementById('promosCaptionsHighlightColor');
    if (captionsColorInput) {
        captionsColorInput.addEventListener('input', (e) => {
            const val = e.target.value;
            state.promos.captionsHighlightColor = val;
            const hexVal = document.getElementById('promosCaptionsHighlightColorHex');
            const hexPreview = document.getElementById('promosCaptionsHighlightColorHexPreview');
            if (hexVal) { hexVal.innerText = val; hexVal.style.color = val; }
            if (hexPreview) hexPreview.innerText = val;
            document.querySelectorAll('.caption-color-chip').forEach(c => {
                c.classList.toggle('active', c.dataset.color.toLowerCase() === val.toLowerCase());
            });
            setPromosV2PreviewMode('captions');
        });
    }

    // Dual Palette Chips Listeners (Pastel & Vibrant)
    document.querySelectorAll('.caption-color-chip').forEach(chip => {
        chip.addEventListener('click', () => {
            const col = chip.dataset.color;
            if (!col) return;
            state.promos.captionsHighlightColor = col;
            if (captionsColorInput) captionsColorInput.value = col;
            const hexVal = document.getElementById('promosCaptionsHighlightColorHex');
            const hexPreview = document.getElementById('promosCaptionsHighlightColorHexPreview');
            if (hexVal) { hexVal.innerText = col; hexVal.style.color = col; }
            if (hexPreview) hexPreview.innerText = col;

            document.querySelectorAll('.caption-color-chip').forEach(c => c.classList.remove('active'));
            chip.classList.add('active');

            setPromosV2PreviewMode('captions');
        });
    });

    // Reset Captions Sliders
    const btnResetCaptions = document.getElementById('btnResetCaptionsSliders');
    if (btnResetCaptions) {
        btnResetCaptions.addEventListener('click', () => {
            state.promos.captionsSize = 84;
            state.promos.captionsY = 600;
            state.promos.captionsHighlightColor = '#FFF380';

            if (captionsSizeInput) captionsSizeInput.value = 84;
            const szLabel = document.getElementById('promosCaptionsSizeVal');
            if (szLabel) szLabel.innerText = '84 px';

            if (captionsYInput) captionsYInput.value = 600;
            const yLabel = document.getElementById('promosCaptionsYVal');
            if (yLabel) yLabel.innerText = '600 px';

            if (captionsColorInput) captionsColorInput.value = '#FFF380';
            const hexVal = document.getElementById('promosCaptionsHighlightColorHex');
            const hexPreview = document.getElementById('promosCaptionsHighlightColorHexPreview');
            if (hexVal) { hexVal.innerText = '#FFF380'; hexVal.style.color = '#FFF380'; }
            if (hexPreview) hexPreview.innerText = '#FFF380';

            document.querySelectorAll('.caption-color-chip').forEach(chip => {
                chip.classList.toggle('active', chip.dataset.color.toLowerCase() === '#fff380');
            });

            setPromosV2PreviewMode('captions');
        });
    }

    // Steam Hook Sliders
    const steamLogoSizeInput = document.getElementById('promosSteamLogoSize');
    if (steamLogoSizeInput) {
        steamLogoSizeInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 130;
            state.promos.steamLogoScale = val / 100.0;
            const valLabel = document.getElementById('promosSteamLogoSizeVal');
            if (valLabel) valLabel.innerText = `${val}%`;
            setPromosV2PreviewMode('steam_hook');
        });
    }

    const steamLogoYInput = document.getElementById('promosSteamLogoY');
    if (steamLogoYInput) {
        steamLogoYInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 540;
            state.promos.steamLogoY = val;
            const valLabel = document.getElementById('promosSteamLogoYVal');
            if (valLabel) valLabel.innerText = `${val} px`;
            setPromosV2PreviewMode('steam_hook');
        });
    }

    const steamTextSizeInput = document.getElementById('promosSteamTextSize');
    if (steamTextSizeInput) {
        steamTextSizeInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 160;
            state.promos.steamTextScale = val / 100.0;
            const valLabel = document.getElementById('promosSteamTextSizeVal');
            if (valLabel) valLabel.innerText = `${val}%`;
            setPromosV2PreviewMode('steam_hook');
        });
    }

    const steamTextYInput = document.getElementById('promosSteamTextY');
    if (steamTextYInput) {
        steamTextYInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 1160;
            state.promos.steamTextY = val;
            const valLabel = document.getElementById('promosSteamTextYVal');
            if (valLabel) valLabel.innerText = `${val} px`;
            setPromosV2PreviewMode('steam_hook');
        });
    }

    const btnResetSteamSliders = document.getElementById('btnResetSteamHookSliders');
    if (btnResetSteamSliders) {
        btnResetSteamSliders.addEventListener('click', () => {
            state.promos.steamLogoScale = 1.3;
            state.promos.steamLogoY = 540;
            state.promos.steamTextScale = 1.6;
            state.promos.steamTextY = 1160;

            if (steamLogoSizeInput) steamLogoSizeInput.value = 130;
            if (steamLogoYInput) steamLogoYInput.value = 540;
            if (steamTextSizeInput) steamTextSizeInput.value = 160;
            if (steamTextYInput) steamTextYInput.value = 1160;

            const lSizeVal = document.getElementById('promosSteamLogoSizeVal');
            if (lSizeVal) lSizeVal.innerText = '130%';
            const lYVal = document.getElementById('promosSteamLogoYVal');
            if (lYVal) lYVal.innerText = '540 px';
            const tSizeVal = document.getElementById('promosSteamTextSizeVal');
            if (tSizeVal) tSizeVal.innerText = '160%';
            const tYVal = document.getElementById('promosSteamTextYVal');
            if (tYVal) tYVal.innerText = '1160 px';

            setPromosV2PreviewMode('steam_hook');
            showToast('Ajustes del gancho de Steam restablecidos a valores por defecto', 'info');
        });
    }

    // Gameplay Ducking Volume Slider
    const gameplayVolInput = document.getElementById('promosGameplayVolume');
    if (gameplayVolInput) {
        gameplayVolInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value) || 0;
            state.promos.v2GameplayVolume = val;
            const label = document.getElementById('promosGameplayVolumeVal');
            if (label) {
                if (val === 0) label.innerText = '0% (Silenciado)';
                else if (val === 15) label.innerText = '15% (Recomendado / Ducking)';
                else if (val === 100) label.innerText = '100% (Mismo volumen)';
                else label.innerText = `${val}%`;
            }
        });
    }

    // Modal 2 Resolution Pills (1080p vs 4K)
    const promoResPills = document.querySelectorAll('#promosResolutionPills .pill');
    promoResPills.forEach(pill => {
        pill.addEventListener('click', () => {
            const res = pill.dataset.res || '1080p';
            state.promos.resolution = res;
            updatePromosResolutionUI();
            showToast(`Resolución seleccionada: ${res === '4K' ? '4K Ultra (2160×3840)' : '1080p Full HD (1080×1920)'}`, 'info');
        });
    });

    // Preview Switcher (Hook Inicial vs Subtítulos)
    const btnPrevSteam = document.getElementById('btnPreviewSteamHook');
    const btnPrevCaptions = document.getElementById('btnPreviewCaptions');
    if (btnPrevSteam) {
        btnPrevSteam.addEventListener('click', () => setPromosV2PreviewMode('steam_hook'));
    }
    if (btnPrevCaptions) {
        btnPrevCaptions.addEventListener('click', () => setPromosV2PreviewMode('captions'));
    }

    // Modal 2 Navigation Buttons
    const btnCloseModal2 = document.getElementById('btnClosePromoModal2');
    const btnBackModal2 = document.getElementById('btnPromoModal2Back');
    const btnRenderModal2 = document.getElementById('btnPromoModal2Render');

    if (btnCloseModal2) btnCloseModal2.addEventListener('click', closePromoModal2);
    if (btnBackModal2) {
        btnBackModal2.addEventListener('click', () => {
            closePromoModal2();
            openPromoModal1();
        });
    }
    if (btnRenderModal2) {
        btnRenderModal2.addEventListener('click', handlePromoModal2Render);
    }

    // -------------------------------------------------------------------------
    // 4. MODAL 3: Progreso, Resultado, Descripción & Calendario
    // -------------------------------------------------------------------------
    const btnCloseModal3 = document.getElementById('btnClosePromoModal3');
    const btnCloseFooter3 = document.getElementById('btnPromoModal3Close');
    const btnBackModal3 = document.getElementById('btnPromoModal3Back');

    if (btnCloseModal3) btnCloseModal3.addEventListener('click', closePromoModal3);
    if (btnCloseFooter3) btnCloseFooter3.addEventListener('click', closePromoModal3);
    if (btnBackModal3) {
        btnBackModal3.addEventListener('click', () => {
            closePromoModal3();
            openPromoModal2();
        });
    }

    // Re-generate Render Button
    const btnRegenRender = document.getElementById('btnPromosRegenRender');
    if (btnRegenRender) {
        btnRegenRender.addEventListener('click', () => {
            openPromoModal3(true);
            startPromoWizardRender();
        });
    }

    initYoutubeShortsMetadata();

    // Social Description Generator & Copy
    const btnGenDesc = document.getElementById('btnPromosGenSocialDesc');
    if (btnGenDesc) {
        btnGenDesc.addEventListener('click', () => generatePromoSocialDescription());
    }

    const btnCopyDesc = document.getElementById('btnPromosCopySocialDesc');
    if (btnCopyDesc) {
        btnCopyDesc.addEventListener('click', () => copyPromoSocialDescription());
    }

    // Calendar Date Picker & Approval Download
    const calDateInput = document.getElementById('promosApprovalDateInput');
    const calDateBadge = document.getElementById('promosApprovalDateBadge');
    const btnApproveDownload = document.getElementById('btnPromosApproveDownload');

    if (calDateInput) {
        calDateInput.addEventListener('input', (e) => {
            const rawVal = e.target.value;
            if (rawVal) {
                const formatted = formatDateToDMY(rawVal);
                state.promos.selectedUploadDate = formatted;
                if (calDateBadge) calDateBadge.innerText = formatted;
                if (btnApproveDownload) {
                    btnApproveDownload.disabled = false;
                    btnApproveDownload.classList.add('btn-gradient-large');
                }
            } else {
                state.promos.selectedUploadDate = '';
                if (calDateBadge) calDateBadge.innerText = 'DD-MM-YY';
                if (btnApproveDownload) {
                    btnApproveDownload.disabled = true;
                    btnApproveDownload.classList.remove('btn-gradient-large');
                }
            }
        });
    }

    if (btnApproveDownload) {
        btnApproveDownload.addEventListener('click', () => handlePromoApprovalAndDownload());
    }

    // Initial Load
    loadPromosSavedGames();
}

// -----------------------------------------------------------------------------
// STEP NAVIGATION HANDLERS (Step 0 -> Modal 1 -> Modal 2 -> Modal 3)
// -----------------------------------------------------------------------------

function handlePromoStep0Next(e) {
    if (e && e.preventDefault) e.preventDefault();
    const gameNameInput = document.getElementById('promosGameName');
    let gameName = (gameNameInput?.value || '').trim();
    if (!gameName) {
        if (gameNameInput) gameNameInput.value = 'Mi Video Promo';
    }
    const footage = state.promos.uploadedFootage || [];
    if (footage.length === 0) {
        showToast('💡 Consejo: Puedes redactar tu guión ahora; recuerda cargar clips antes de renderizar.', 'info');
    }
    openPromoModal1();
}

function handlePromoModal1Next(e) {
    if (e && e.preventDefault) e.preventDefault();
    let script = (state.promos.v2ScriptText || document.getElementById('promosV2ScriptText')?.value || '').trim();
    if (!script && !state.promos.v2VoicePath) {
        const gameName = (document.getElementById('promosGameName')?.value || 'este videojuego').trim();
        const defaultScript = defaultPromoScriptForHook(state.promos.hookType, gameName, promosOpeningText());
        state.promos.v2ScriptText = defaultScript;
        const scriptInput = document.getElementById('promosV2ScriptText');
        if (scriptInput) scriptInput.value = defaultScript;
        updatePromosV2Stats();
        showToast('Guión base asignado automáticamente. ¡Puedes modificarlo en cualquier momento!', 'info');
    }
    closePromoModal1();
    openPromoModal2();
}

function handlePromoModal2Render(e) {
    if (e && e.preventDefault) e.preventDefault();
    closePromoModal2();
    openPromoModal3();
    startPromoWizardRender();
}

// -----------------------------------------------------------------------------
// MODAL CONTROLLERS: OPEN & CLOSE
// -----------------------------------------------------------------------------

function openPromoModal1() {
    try {
        const modal = document.getElementById('modalPromoStep1Script');
        if (!modal) {
            console.error('modalPromoStep1Script element not found in DOM');
            return;
        }

        // Sync active hook type (4 options) and the custom opening phrase
        setPromosHookType(state.promos.hookType);
        const promosOpeningEl = document.getElementById('promosOpeningText');
        if (promosOpeningEl && state.promos.openingText && !promosOpeningEl.value) promosOpeningEl.value = state.promos.openingText;

        // Sync briefing & tone
        const briefingInput = document.getElementById('promosV2Briefing');
        if (briefingInput && state.promos.v2BriefingText) briefingInput.value = state.promos.v2BriefingText;

        const toneSelect = document.getElementById('promosV2ToneSelect');
        if (toneSelect && state.promos.v2Tone) toneSelect.value = state.promos.v2Tone;

        const scriptInput = document.getElementById('promosV2ScriptText');
        if (scriptInput && state.promos.v2ScriptText) scriptInput.value = state.promos.v2ScriptText;

        updatePromosV2Stats();

        // Voice display name from Settings
        const activeVoiceEl = document.getElementById('promosActiveVoiceName');
        const voiceSelectEl = document.getElementById('cfgVoiceId');
        if (activeVoiceEl) {
            const voiceVal = (voiceSelectEl?.value || 'JBFqnCBsd6RMkjVDRZzb').trim();
            activeVoiceEl.innerText = `ElevenLabs (${voiceVal.substring(0, 8)}...)`;
        }

        modal.style.display = 'flex';
        if (modal.style && modal.style.setProperty) {
            modal.style.setProperty('display', 'flex', 'important');
        }
        void modal.offsetWidth;
        modal.classList.add('active');
    } catch (err) {
        console.error('Error opening Modal 1:', err);
        const modal = document.getElementById('modalPromoStep1Script');
        if (modal) {
            modal.style.display = 'flex';
            if (modal.style && modal.style.setProperty) {
                modal.style.setProperty('display', 'flex', 'important');
            }
            modal.classList.add('active');
        }
    }
}

function closePromoModal1() {
    const modal = document.getElementById('modalPromoStep1Script');
    if (!modal) return;
    modal.classList.remove('active');
    modal.style.display = 'none';
}

function openPromoModal2() {
    try {
        const modal = document.getElementById('modalPromoStep2Visuals');
        if (!modal) {
            console.error('modalPromoStep2Visuals element not found in DOM');
            return;
        }

        const isSteamHook = (state.promos.hookType === 'steam_new_game');
        const steamHookGroup = document.getElementById('promosSteamHookGroup');
        const btnPrevSteam = document.getElementById('btnPreviewSteamHook');

        if (steamHookGroup) steamHookGroup.style.display = isSteamHook ? 'block' : 'none';
        if (btnPrevSteam) btnPrevSteam.style.display = isSteamHook ? 'inline-block' : 'none';

        // Sync subtitle sliders
        const sizeInput = document.getElementById('promosCaptionsSize');
        if (sizeInput && state.promos.captionsSize) sizeInput.value = state.promos.captionsSize;
        const sizeVal = document.getElementById('promosCaptionsSizeVal');
        if (sizeVal && state.promos.captionsSize) sizeVal.innerText = `${state.promos.captionsSize} px`;

        const yInput = document.getElementById('promosCaptionsY');
        if (yInput && state.promos.captionsY) yInput.value = state.promos.captionsY;
        const yVal = document.getElementById('promosCaptionsYVal');
        if (yVal && state.promos.captionsY) yVal.innerText = `${state.promos.captionsY} px`;

        // Sync Steam Hook sliders
        const steamLogoSizeInput = document.getElementById('promosSteamLogoSize');
        const curLogoScale = state.promos.steamLogoScale !== undefined ? state.promos.steamLogoScale : 1.3;
        const curLogoScalePct = Math.round(curLogoScale * 100);
        if (steamLogoSizeInput) steamLogoSizeInput.value = curLogoScalePct;
        const steamLogoSizeVal = document.getElementById('promosSteamLogoSizeVal');
        if (steamLogoSizeVal) steamLogoSizeVal.innerText = `${curLogoScalePct}%`;

        const steamLogoYInput = document.getElementById('promosSteamLogoY');
        const curLogoY = state.promos.steamLogoY !== undefined ? state.promos.steamLogoY : 540;
        if (steamLogoYInput) steamLogoYInput.value = curLogoY;
        const steamLogoYVal = document.getElementById('promosSteamLogoYVal');
        if (steamLogoYVal) steamLogoYVal.innerText = `${curLogoY} px`;

        const steamTextSizeInput = document.getElementById('promosSteamTextSize');
        const curTextScale = state.promos.steamTextScale !== undefined ? state.promos.steamTextScale : 1.6;
        const curTextScalePct = Math.round(curTextScale * 100);
        if (steamTextSizeInput) steamTextSizeInput.value = curTextScalePct;
        const steamTextSizeVal = document.getElementById('promosSteamTextSizeVal');
        if (steamTextSizeVal) steamTextSizeVal.innerText = `${curTextScalePct}%`;

        const steamTextYInput = document.getElementById('promosSteamTextY');
        const curTextY = state.promos.steamTextY !== undefined ? state.promos.steamTextY : 1160;
        if (steamTextYInput) steamTextYInput.value = curTextY;
        const steamTextYVal = document.getElementById('promosSteamTextYVal');
        if (steamTextYVal) steamTextYVal.innerText = `${curTextY} px`;

        // Set default preview mode: steam_hook if steam hook selected, else captions
        setPromosV2PreviewMode(isSteamHook ? 'steam_hook' : 'captions');

        // Sync highlight color chips
        const activeCol = (state.promos.captionsHighlightColor || '#FFF380').toLowerCase();
        document.querySelectorAll('.caption-color-chip').forEach(chip => {
            chip.classList.toggle('active', chip.dataset.color.toLowerCase() === activeCol);
        });

        updatePromosMockupDisplay();
        updatePromosResolutionUI();

        // Autoplay video preview when modal opens
        const previewVideo = document.getElementById('promosPreviewVideo');
        if (previewVideo) {
            previewVideo.muted = true;
            previewVideo.play().catch(() => {});
        }

        modal.style.display = 'flex';
        if (modal.style && modal.style.setProperty) {
            modal.style.setProperty('display', 'flex', 'important');
        }
        void modal.offsetWidth;
        modal.classList.add('active');
    } catch (err) {
        console.error('Error opening Modal 2:', err);
        const modal = document.getElementById('modalPromoStep2Visuals');
        if (modal) {
            modal.style.display = 'flex';
            if (modal.style && modal.style.setProperty) {
                modal.style.setProperty('display', 'flex', 'important');
            }
            modal.classList.add('active');
        }
    }
}

function closePromoModal2() {
    const modal = document.getElementById('modalPromoStep2Visuals');
    if (!modal) return;
    const previewVideo = document.getElementById('promosPreviewVideo');
    if (previewVideo) {
        previewVideo.pause();
    }
    modal.classList.remove('active');
    modal.style.display = 'none';
}

function openPromoModal3(isReRender = false) {
    try {
        const modal = document.getElementById('modalPromoStep3Output');
        if (!modal) return;

        const progContainer = document.getElementById('promosModalProgressContainer');
        const resContainer = document.getElementById('promosModalResultContainer');
        const titleEl = document.getElementById('promoStep3Title');
        const subEl = document.getElementById('promoStep3Sub');
        const iconEl = document.getElementById('promoStep3BadgeIcon');

        if (progContainer) progContainer.style.display = 'block';
        if (resContainer) resContainer.style.display = 'none';
        if (titleEl) titleEl.innerText = isReRender ? 'Regenerando Promo...' : 'Producción de Promo en Curso...';
        if (subEl) subEl.innerText = 'Director IA semántico, locución con ElevenLabs y subtítulos dynamic kinetic';
        if (iconEl) iconEl.innerText = '⚡';

        // Reset 4 phase steps
        for (let i = 1; i <= 4; i++) {
            const step = document.getElementById(`phaseStep${i}`);
            const bar = document.getElementById(`phaseStep${i}Bar`);
            const status = document.getElementById(`phaseStep${i}Status`);
            if (step) { step.classList.remove('active', 'completed'); }
            if (bar) { bar.style.width = '0%'; }
            if (status) { status.innerText = (i === 1) ? 'Iniciando...' : 'En espera'; }
        }

        const globalPct = document.getElementById('promosPhaseGlobalPct');
        if (globalPct) globalPct.innerText = '0%';

        modal.style.display = 'flex';
        if (modal.style && modal.style.setProperty) {
            modal.style.setProperty('display', 'flex', 'important');
        }
        void modal.offsetWidth;
        modal.classList.add('active');
    } catch (err) {
        console.error('Error opening Modal 3:', err);
        const modal = document.getElementById('modalPromoStep3Output');
        if (modal) {
            modal.style.display = 'flex';
            if (modal.style && modal.style.setProperty) {
                modal.style.setProperty('display', 'flex', 'important');
            }
            modal.classList.add('active');
        }
    }
}

function closePromoModal3() {
    if (promosEventSource) {
        promosEventSource.close();
        promosEventSource = null;
    }
    const modal = document.getElementById('modalPromoStep3Output');
    if (!modal) return;
    modal.classList.remove('active');
    modal.style.display = 'none';
}

// -----------------------------------------------------------------------------
// FOOTAGE & VOICE DATA HANDLERS
