async function loadPromosSavedGames(selectedFolder = null) {
    const selectEl = document.getElementById('promosSavedGamesSelect');
    if (!selectEl) return;
    try {
        const res = await fetch('/api/promos/library/games');
        const data = await res.json();
        if (data.status === 'ok') {
            state.promos.savedGames = data.games || [];
            let html = '<option value="">📁 Cargar juego guardado (PromosFootage)...</option>';
            state.promos.savedGames.forEach(g => {
                const isSelected = selectedFolder && (g.folder_name === selectedFolder || g.game_name === selectedFolder);
                const breakdownTag = g.has_breakdowns ? ' · ⚡ IA Listo' : '';
                html += `<option value="${escapeHtml(g.folder_name)}" ${isSelected ? 'selected' : ''}>${escapeHtml(g.game_name)} (${escapeHtml(g.video_count)} clip${g.video_count === 1 ? '' : 's'}${breakdownTag})</option>`;
            });
            selectEl.innerHTML = html;
        }
    } catch (e) {
        console.warn('Error loading saved games in PromosFootage:', e);
    }
}

async function handlePromosFootageUpload(files) {
    if (!files || !files.length) return;
    showToast(`Subiendo ${files.length} archivo(s) de gameplay...`, 'info');

    for (const file of files) {
        const formData = new FormData();
        formData.append('file', file);
        try {
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData
            });
            const data = await res.json();
            if (data.status === 'ok') {
                state.promos.uploadedFootage.push({
                    filename: file.name,
                    saved_path: data.saved_path,
                    url: data.url,
                    size: file.size,
                    has_breakdown: false,
                });
            }
        } catch (e) {
            showToast(`Error al subir "${file.name}": ${e}`, 'error');
        }
    }

    renderPromosFootageList();
    showToast(`${state.promos.uploadedFootage.length} clip(s) listos para la promo`, 'success');

    // Auto-detect vertical format
    if (files && files.length > 0) {
        try {
            const probeVideo = document.createElement('video');
            probeVideo.preload = 'metadata';
            probeVideo.src = URL.createObjectURL(files[0]);
            probeVideo.onloadedmetadata = () => {
                URL.revokeObjectURL(probeVideo.src);
                if (probeVideo.videoHeight > probeVideo.videoWidth) {
                    const toggle = document.getElementById('promosFootageIs916');
                    const badge = document.getElementById('promosFootage916Badge');
                    if (toggle && !toggle.checked) {
                        toggle.checked = true;
                        if (badge) badge.style.display = 'inline-block';
                        showToast(`📱 Vídeo vertical detectado (${probeVideo.videoWidth}x${probeVideo.videoHeight}): activado 9:16 nativo automáticamente.`, 'info');
                    }
                }
            };
        } catch (e) {
            console.warn('Could not probe video dimensions:', e);
        }
    }

    // Auto-fill game name from first file if empty
    const gameNameInput = document.getElementById('promosGameName');
    if (gameNameInput && !gameNameInput.value.trim() && state.promos.uploadedFootage.length) {
        const rawName = state.promos.uploadedFootage[0].filename
            .replace(/\.[^/.]+$/, '')
            .replace(/[-_]/g, ' ')
            .replace(/\b(gameplay|footage|clip|1080p|4k|short|v1|trailer)\b/gi, '')
            .trim();
        if (rawName) {
            gameNameInput.value = rawName;
            const badge = document.getElementById('promosGameFolderBadge');
            if (badge) {
                badge.style.display = 'inline-block';
                badge.innerText = `📁 PromosFootage/${rawName}`;
            }
        }
    }
}

function resetPromosForNewGame() {
    state.promos.uploadedFootage = [];
    const gameNameInput = document.getElementById('promosGameName');
    if (gameNameInput) gameNameInput.value = '';
    const badge = document.getElementById('promosGameFolderBadge');
    if (badge) {
        badge.style.display = 'none';
        badge.innerText = 'PromosFootage/...';
    }
    const selectEl = document.getElementById('promosSavedGamesSelect');
    if (selectEl) selectEl.value = '';
    const toggle = document.getElementById('promosFootageIs916');
    if (toggle) toggle.checked = false;
    const badge916 = document.getElementById('promosFootage916Badge');
    if (badge916) badge916.style.display = 'none';
    renderPromosFootageList();
    showToast('Formulario limpio listo para un nuevo juego', 'info');
}

function clearAllPromosFootage() {
    if (!state.promos.uploadedFootage || state.promos.uploadedFootage.length === 0) return;
    state.promos.uploadedFootage = [];
    renderPromosFootageList();
    showToast('Clips de gameplay eliminados de la lista actual', 'info');
}

function renderPromosFootageList() {
    const listEl = document.getElementById('promosFootageList');
    if (!listEl) return;

    if (!state.promos.uploadedFootage || state.promos.uploadedFootage.length === 0) {
        listEl.style.display = 'none';
        listEl.innerHTML = '';
        return;
    }

    listEl.style.display = 'flex';
    let html = `
        <div style="display: flex; justify-content: space-between; align-items: center; width: 100%; padding: 0 4px 6px 4px; margin-bottom: 6px; border-bottom: 1px solid rgba(255, 255, 255, 0.08);">
            <span style="font-size: 11.5px; font-weight: 600; color: var(--text-muted);">Clips cargados (${state.promos.uploadedFootage.length})</span>
            <button type="button" id="btnPromosClearAllFootage" class="btn btn-tag" style="font-size: 11px; padding: 2px 8px; color: #ef4444; border-color: rgba(239, 68, 68, 0.35); background: rgba(239, 68, 68, 0.08);" title="Quitar todos los clips">🗑️ Limpiar todo</button>
        </div>
    `;
    state.promos.uploadedFootage.forEach((clip, idx) => {
        const sizeMb = ((clip.size || 0) / (1024 * 1024)).toFixed(1);
        const bdBadge = clip.has_breakdown ? `<span class="badge-breakdown-ready" title="Breakdown analizado previamente y listo en PromosFootage">⚡ IA Listo</span>` : '';
        html += `
            <div class="promos-footage-item">
                <div class="promos-footage-item-left">
                    <span class="promos-footage-item-icon">📹</span>
                    <span class="promos-footage-item-name" title="${escapeHtml(clip.filename)}">${escapeHtml(clip.filename)}</span>
                    ${bdBadge}
                </div>
                <div style="display: flex; align-items: center; gap: 8px;">
                    <span class="promos-footage-item-size">${sizeMb} MB</span>
                    <button type="button" class="promos-footage-item-remove" data-idx="${idx}" title="Quitar clip">×</button>
                </div>
            </div>
        `;
    });
    listEl.innerHTML = html;

    const btnClearAll = listEl.querySelector('#btnPromosClearAllFootage');
    if (btnClearAll) {
        btnClearAll.addEventListener('click', clearAllPromosFootage);
    }

    listEl.querySelectorAll('.promos-footage-item-remove').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const idx = parseInt(e.target.dataset.idx);
            state.promos.uploadedFootage.splice(idx, 1);
            renderPromosFootageList();
        });
    });
}

async function handlePromosVoiceUpload(file) {
    if (!file) return;
    showToast(`Subiendo archivo de voz "${file.name}"...`, 'info');

    const formData = new FormData();
    formData.append('file', file);

    try {
        const res = await fetch('/api/v2/voiceover/upload', {
            method: 'POST',
            body: formData
        });
        const data = await res.json();
        if (data.status === 'ok') {
            state.promos.v2VoicePath = data.saved_path;
            state.promos.v2VoiceUrl = data.url;
            state.promos.v2VoiceDuration = data.duration;
            state.promos.v2VoiceFilename = data.filename;

            const hidden = document.getElementById('promosVoicePath');
            if (hidden) hidden.value = data.saved_path;

            const container = document.getElementById('promosVoicePlayerContainer');
            const nameEl = document.getElementById('promosVoiceFileName');
            const durEl = document.getElementById('promosVoiceDurationDisplay');
            const audioElem = document.getElementById('promosVoiceAudioElem');
            const badgeEl = document.getElementById('promosVoiceStatusBadge');

            if (container) container.style.display = 'block';
            if (nameEl) nameEl.innerText = data.filename;
            if (durEl) durEl.innerText = `${data.duration.toFixed(1)}s`;
            if (audioElem) {
                audioElem.src = data.url;
                audioElem.load();
            }
            if (badgeEl) {
                badgeEl.innerText = `Voz cargada (${data.duration.toFixed(1)}s)`;
                badgeEl.style.background = 'rgba(34, 197, 94, 0.15)';
                badgeEl.style.color = '#4ade80';
            }

            showToast(`¡Voz cargada con éxito! Duración: ${data.duration.toFixed(1)}s`, 'success');
        } else {
            showToast('Error al procesar archivo de voz: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al subir archivo de voz: ' + e.message, 'error');
    }
}

function updatePromosV2Stats() {
    const scriptText = (state.promos.v2ScriptText || document.getElementById('promosV2ScriptText')?.value || '').trim();
    const words = scriptText ? scriptText.split(/\s+/).filter(Boolean).length : 0;
    const estDur = words > 0 ? (words / 2.3).toFixed(1) : 0;

    const countEl = document.getElementById('promosV2WordCount');
    const durEl = document.getElementById('promosV2EstDuration');
    if (countEl) countEl.innerText = words;
    if (durEl) durEl.innerText = `${estDur}s`;
}

async function generatePromosV2Script() {
    const gameName = document.getElementById('promosGameName')?.value.trim() || '';
    if (!gameName) {
        showToast('Escribe el nombre del juego primero en el paso anterior', 'info');
        return;
    }
    const targetDur = 30.0;
    const tone = document.getElementById('promosV2ToneSelect')?.value || 'viral_hype';
    const briefing = document.getElementById('promosV2Briefing')?.value.trim() || '';

    const btn = document.getElementById('btnPromosV2GenScript');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>⏳</span> Redactando...';
    }

    try {
        const res = await fetch('/api/v2/script/generate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_name: gameName,
                target_duration: targetDur,
                tone: tone,
                briefing_text: briefing,
                ...promosHookFields(),
            })
        });
        const data = await res.json();
        if (data.status === 'ok') {
            state.promos.v2ScriptText = data.script;
            const scriptEl = document.getElementById('promosV2ScriptText');
            if (scriptEl) scriptEl.value = data.script;
            updatePromosV2Stats();
            showToast('¡Guión viral generado con éxito!', 'success');
        } else {
            showToast('Error generando guión: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al conectar con la IA: ' + e.message, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<span>✨</span> Generar';
        }
    }
}

async function modifyPromosV2ScriptLength(action, customInstruction = '') {
    const scriptEl = document.getElementById('promosV2ScriptText');
    const currentScript = scriptEl ? scriptEl.value.trim() : (state.promos.v2ScriptText || '');
    if (!currentScript) {
        showToast('Escribe o genera un guión primero para modificarlo', 'info');
        return;
    }
    const gameName = document.getElementById('promosGameName')?.value.trim() || 'Gameplay';

    let toastMsg = 'Modificando guión...';
    if (action === 'shorter') toastMsg = 'Acortando guión...';
    else if (action === 'longer') toastMsg = 'Alargando guión...';
    else if (action === 'change_hook') toastMsg = 'Generando nuevo Hook inicial...';
    else if (action === 'more_viral') toastMsg = 'Aumentando impacto y energía viral...';
    else if (action === 'custom_instruction') toastMsg = 'Aplicando tus indicaciones al guión...';

    showToast(toastMsg, 'info');

    try {
        const res = await fetch('/api/v2/script/modify', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                script_text: currentScript,
                action: action,
                game_name: gameName,
                target_duration: 30.0,
                custom_instruction: customInstruction,
                // Keep the chosen opening (custom phrase / direct) when modifying.
                ...promosHookFields(),
            })
        });
        const data = await res.json();
        if (data.status === 'ok') {
            state.promos.v2ScriptText = data.script;
            if (scriptEl) scriptEl.value = data.script;
            updatePromosV2Stats();

            if (action === 'custom_instruction') {
                const inputEl = document.getElementById('promosV2CustomInstructionInput');
                if (inputEl) inputEl.value = '';
                const barEl = document.getElementById('promosV2CustomInstructionBar');
                if (barEl) barEl.style.display = 'none';
            }

            showToast('Guión modificado con éxito', 'success');
        } else {
            showToast('Error modificando guión: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al conectar con la IA: ' + e.message, 'error');
    }
}

