function updatePromosResolutionUI() {
    const res = state.promos.resolution || '1080p';
    const resBadge = document.getElementById('promosMockupResBadge');
    if (resBadge) {
        if (res === '4K') {
            resBadge.innerText = '9:16 (4K Ultra)';
            resBadge.style.background = 'rgba(217, 119, 87, 0.2)';
            resBadge.style.color = 'var(--claude-accent, #d97757)';
            resBadge.style.borderColor = 'rgba(217, 119, 87, 0.4)';
        } else {
            resBadge.innerText = '9:16 (1080p)';
            resBadge.style.background = 'rgba(34, 197, 94, 0.15)';
            resBadge.style.color = '#4ade80';
            resBadge.style.borderColor = 'rgba(34, 197, 94, 0.3)';
        }
    }
    const pills = document.querySelectorAll('#promosResolutionPills .pill');
    pills.forEach(p => {
        p.classList.toggle('active', p.dataset.res === res);
    });
}

function updatePromosMockupDisplay() {
    const gameName = document.getElementById('promosGameName')?.value.trim() || 'Gameplay';
    const scriptText = (state.promos.v2ScriptText || document.getElementById('promosV2ScriptText')?.value || '').trim();

    const gameBadge = document.getElementById('promosMockupGameBadge');
    if (gameBadge) gameBadge.innerText = gameName;

    const previewVideo = document.getElementById('promosPreviewVideo');
    const placeholder = document.getElementById('promosGameplayPlaceholder');
    const gameplayContainer = document.getElementById('promosMockupGameplay');

    if (gameplayContainer) {
        gameplayContainer.style.top = '0';
        gameplayContainer.style.left = '0';
        gameplayContainer.style.width = '100%';
        gameplayContainer.style.height = '100%';
        gameplayContainer.style.borderTop = 'none';
        gameplayContainer.style.borderBottom = 'none';
    }

    let clipUrl = null;
    if (state.promos.uploadedFootage && state.promos.uploadedFootage.length > 0 && state.promos.uploadedFootage[0].url) {
        clipUrl = state.promos.uploadedFootage[0].url;
    } else if (state.gamedev && state.gamedev.footageClips && state.gamedev.footageClips.length > 0 && state.gamedev.footageClips[0].url) {
        clipUrl = state.gamedev.footageClips[0].url;
    } else if (state.promos.savedGames && state.promos.savedGames.length > 0) {
        const gameWithVid = state.promos.savedGames.find(g => g.videos && g.videos.length > 0);
        if (gameWithVid) clipUrl = gameWithVid.videos[0].url;
    }

    if (clipUrl && previewVideo) {
        if (!previewVideo.src || !previewVideo.src.endsWith(clipUrl)) {
            previewVideo.src = clipUrl;
        }
        previewVideo.muted = true;
        previewVideo.loop = true;
        previewVideo.playsInline = true;
        previewVideo.style.display = 'block';
        previewVideo.style.width = '100%';
        previewVideo.style.height = '100%';
        previewVideo.style.objectFit = 'cover';
        if (placeholder) {
            placeholder.style.display = 'none';
            if (placeholder.style.setProperty) {
                placeholder.style.setProperty('display', 'none', 'important');
            }
        }
        if (gameplayContainer) {
            gameplayContainer.classList.add('has-video');
        }
        const playPromise = previewVideo.play();
        if (playPromise !== undefined) {
            playPromise.catch(() => {});
        }
    } else if (previewVideo) {
        if (placeholder) {
            placeholder.style.display = 'flex';
        }
        if (gameplayContainer) {
            gameplayContainer.classList.remove('has-video');
        }
    }

    updatePromosResolutionUI();

    const steamHookEl = document.getElementById('promosMockupSteamHook');
    const captionsEl = document.getElementById('promosMockupCaptions');
    const prevMode = state.promos.v2PreviewMode || 'steam_hook';
    const isSteamHook = (state.promos.hookType === 'steam_new_game');

    if (isSteamHook && prevMode === 'steam_hook') {
        if (steamHookEl) {
            steamHookEl.style.display = 'flex';
            const logoScale = state.promos.steamLogoScale !== undefined ? state.promos.steamLogoScale : 1.3;
            const logoY = state.promos.steamLogoY !== undefined ? state.promos.steamLogoY : 540;
            const textScale = state.promos.steamTextScale !== undefined ? state.promos.steamTextScale : 1.6;
            const textY = state.promos.steamTextY !== undefined ? state.promos.steamTextY : 1160;

            const badgeWrap = steamHookEl.querySelector('.steam-hook-badge-wrap');
            const textStack = steamHookEl.querySelector('.steam-hook-text-stack');

            const logoTopPct = (logoY / 1920.0) * 100.0;
            const textTopPct = (textY / 1920.0) * 100.0;

            if (badgeWrap) {
                badgeWrap.style.top = `${logoTopPct.toFixed(1)}%`;
                badgeWrap.style.left = '50%';
                badgeWrap.style.transform = `translate(-50%, -50%) scale(${logoScale.toFixed(2)})`;
                badgeWrap.style.transformOrigin = 'center center';
            }
            if (textStack) {
                textStack.style.top = `${textTopPct.toFixed(1)}%`;
                textStack.style.left = '50%';
                textStack.style.transform = `translate(-50%, -50%) scale(${textScale.toFixed(2)})`;
                textStack.style.transformOrigin = 'center center';
            }
        }
        if (captionsEl) captionsEl.style.display = 'none';
    } else {
        if (steamHookEl) steamHookEl.style.display = 'none';
        if (captionsEl) {
            captionsEl.style.display = 'flex';
            const rawCaptionsY = state.promos.captionsY !== undefined ? state.promos.captionsY : 600;
            const bottomPct = (rawCaptionsY / 1920.0) * 100.0;
            captionsEl.style.bottom = `${bottomPct.toFixed(1)}%`;

            const rawCaptionsSize = state.promos.captionsSize !== undefined ? state.promos.captionsSize : 84;
            const mockupFontSize = Math.max(14, Math.round(27.0 * (rawCaptionsSize / 84.0)));
            const highlightColor = (state.promos.captionsHighlightColor || '#FFF380').trim();

            const words = (scriptText ? scriptText.split(/\s+/) : ['THIS', 'GAME', 'WILL', 'BLOW', 'YOUR', 'MIND'])
                .map(w => w.replace(/[^\w]/g, '').trim())
                .filter(Boolean);

            const hookWordsSet = new Set(['HERES', 'HERE', 'IS', 'A', 'NEW', 'STEAM', 'GAME', 'SO', 'IN', 'THIS']);
            const nonHookWords = words.filter(w => !hookWordsSet.has(w.toUpperCase()));
            const sampleWord = (nonHookWords[0] || words[0] || 'VIRAL').toUpperCase();

            captionsEl.innerHTML = `
                <div class="mockup-caption-word-single">
                    <span class="caption-word active-word-single" style="font-size: ${mockupFontSize}px; color: ${highlightColor}; text-shadow: -2.5px -2.5px 0 #000, 2.5px -2.5px 0 #000, -2.5px 2.5px 0 #000, 2.5px 2.5px 0 #000, 0px 0px 16px ${highlightColor}b0, 0px 4px 10px rgba(0, 0, 0, 0.95);">${sampleWord}</span>
                </div>
            `;
        }
    }
}

// -----------------------------------------------------------------------------
// PIPELINE EXECUTION & 4-PHASE PROGRESS TRACKER
// -----------------------------------------------------------------------------

function updatePromoPhaseBars(progressPct, message, log) {
    const p = Math.max(0, Math.min(100, Math.round(progressPct || 0)));

    const globalPct = document.getElementById('promosPhaseGlobalPct');
    if (globalPct) globalPct.innerText = `${p}%`;

    const statusText = document.getElementById('promosPhaseStatusText');
    if (statusText && message) statusText.innerText = message;

    const logText = document.getElementById('promosModalLogText');
    if (logText) logText.innerText = log || message || 'Procesando...';

    // 4 Phases calculation:
    // Phase 1: 0 - 25% (Ingestion)
    // Phase 2: 25 - 50% (Locución & Subtitles)
    // Phase 3: 50 - 75% (Análisis Visual & Sequencing)
    // Phase 4: 75 - 100% (Final Mix & Overlays)

    const step1 = document.getElementById('phaseStep1');
    const step1Bar = document.getElementById('phaseStep1Bar');
    const step1Status = document.getElementById('phaseStep1Status');

    const step2 = document.getElementById('phaseStep2');
    const step2Bar = document.getElementById('phaseStep2Bar');
    const step2Status = document.getElementById('phaseStep2Status');

    const step3 = document.getElementById('phaseStep3');
    const step3Bar = document.getElementById('phaseStep3Bar');
    const step3Status = document.getElementById('phaseStep3Status');

    const step4 = document.getElementById('phaseStep4');
    const step4Bar = document.getElementById('phaseStep4Bar');
    const step4Status = document.getElementById('phaseStep4Status');

    // Phase 1
    if (p <= 25) {
        const subP = Math.round((p / 25) * 100);
        if (step1) { step1.classList.add('active'); step1.classList.remove('completed'); }
        if (step1Bar) step1Bar.style.width = `${subP}%`;
        if (step1Status) step1Status.innerText = 'Procesando clips...';

        if (step2) { step2.classList.remove('active', 'completed'); }
        if (step2Bar) step2Bar.style.width = '0%';
        if (step2Status) step2Status.innerText = 'En espera';

        if (step3) { step3.classList.remove('active', 'completed'); }
        if (step3Bar) step3Bar.style.width = '0%';
        if (step3Status) step3Status.innerText = 'En espera';

        if (step4) { step4.classList.remove('active', 'completed'); }
        if (step4Bar) step4Bar.style.width = '0%';
        if (step4Status) step4Status.innerText = 'En espera';
    }
    // Phase 2
    else if (p <= 50) {
        const subP = Math.round(((p - 25) / 25) * 100);
        if (step1) { step1.classList.remove('active'); step1.classList.add('completed'); }
        if (step1Bar) step1Bar.style.width = '100%';
        if (step1Status) step1Status.innerText = 'Completado ✓';

        if (step2) { step2.classList.add('active'); step2.classList.remove('completed'); }
        if (step2Bar) step2Bar.style.width = `${subP}%`;
        if (step2Status) step2Status.innerText = 'Sintetizando voz & subtítulos...';

        if (step3) { step3.classList.remove('active', 'completed'); }
        if (step3Bar) step3Bar.style.width = '0%';
        if (step3Status) step3Status.innerText = 'En espera';

        if (step4) { step4.classList.remove('active', 'completed'); }
        if (step4Bar) step4Bar.style.width = '0%';
        if (step4Status) step4Status.innerText = 'En espera';
    }
    // Phase 3
    else if (p <= 75) {
        const subP = Math.round(((p - 50) / 25) * 100);
        if (step1) { step1.classList.remove('active'); step1.classList.add('completed'); }
        if (step1Bar) step1Bar.style.width = '100%';
        if (step1Status) step1Status.innerText = 'Completado ✓';

        if (step2) { step2.classList.remove('active'); step2.classList.add('completed'); }
        if (step2Bar) step2Bar.style.width = '100%';
        if (step2Status) step2Status.innerText = 'Completado ✓';

        if (step3) { step3.classList.add('active'); step3.classList.remove('completed'); }
        if (step3Bar) step3Bar.style.width = `${subP}%`;
        if (step3Status) step3Status.innerText = 'Montaje semántico IA...';

        if (step4) { step4.classList.remove('active', 'completed'); }
        if (step4Bar) step4Bar.style.width = '0%';
        if (step4Status) step4Status.innerText = 'En espera';
    }
    // Phase 4
    else {
        const subP = Math.round(((p - 75) / 25) * 100);
        if (step1) { step1.classList.remove('active'); step1.classList.add('completed'); }
        if (step1Bar) step1Bar.style.width = '100%';
        if (step1Status) step1Status.innerText = 'Completado ✓';

        if (step2) { step2.classList.remove('active'); step2.classList.add('completed'); }
        if (step2Bar) step2Bar.style.width = '100%';
        if (step2Status) step2Status.innerText = 'Completado ✓';

        if (step3) { step3.classList.remove('active'); step3.classList.add('completed'); }
        if (step3Bar) step3Bar.style.width = '100%';
        if (step3Status) step3Status.innerText = 'Completado ✓';

        if (step4) {
            if (p >= 100) {
                step4.classList.remove('active');
                step4.classList.add('completed');
                if (step4Status) step4Status.innerText = 'Completado ✓';
            } else {
                step4.classList.add('active');
                step4.classList.remove('completed');
                if (step4Status) step4Status.innerText = 'Ensamblando y renderizando...';
            }
        }
        if (step4Bar) step4Bar.style.width = `${subP}%`;
    }
}

async function startPromoWizardRender() {
    const scriptText = (state.promos.v2ScriptText || document.getElementById('promosV2ScriptText')?.value || '').trim();
    const gameName = document.getElementById('promosGameName')?.value.trim() || 'Gameplay';

    const payload = {
        footage_paths: state.promos.uploadedFootage.map(f => f.saved_path),
        game_name: gameName,
        mode: 'v2_voice_script',
        pipeline_version: 'v2',
        video_count: 1,
        ...promosHookFields(),
        target_duration: 30.0,
        framing: 'vertical_split_blur',
        resolution: state.promos.resolution || '1080p',
        strip_splash: true,
        footage_is_9_16: document.getElementById('promosFootageIs916')?.checked || false,
        voiceover_path: state.promos.v2VoicePath || null,
        script_text: scriptText,
        briefing_text: state.promos.v2BriefingText || document.getElementById('promosV2Briefing')?.value || '',
        captions_style: 'kinetic_highlight',
        captions_font_size: parseInt(document.getElementById('promosCaptionsSize')?.value ?? state.promos.captionsSize ?? 86),
        captions_highlight_color: (document.getElementById('promosCaptionsHighlightColor')?.value || state.promos.captionsHighlightColor || '#FFF380').trim(),
        captions_y_position: parseInt(document.getElementById('promosCaptionsY')?.value ?? state.promos.captionsY ?? 450),
        gameplay_volume: (parseFloat(document.getElementById('promosGameplayVolume')?.value ?? state.promos.v2GameplayVolume ?? 15) / 100.0),
        elevenlabs_voice_id: (document.getElementById('cfgVoiceId')?.value || '').trim() || undefined,
        elevenlabs_api_key: typedApiKeyValue('cfgElevenKey') || undefined,
        steam_logo_scale: state.promos.steamLogoScale !== undefined ? state.promos.steamLogoScale : 1.0,
        steam_logo_y: state.promos.steamLogoY !== undefined ? state.promos.steamLogoY : 540,
        steam_text_scale: state.promos.steamTextScale !== undefined ? state.promos.steamTextScale : 1.0,
        steam_text_y: state.promos.steamTextY !== undefined ? state.promos.steamTextY : 1090,
        precut_video: document.getElementById('promosV2PrecutVideo') ? document.getElementById('promosV2PrecutVideo').checked : Boolean(state.promos.precutVideo),
        hashtags: (document.getElementById('promosSocialHashtagInput')?.value || state.promos.hashtags || '').trim(),
    };

    state.promos.isCompleted = false;

    if (promosEventSource) {
        promosEventSource.close();
        promosEventSource = null;
    }

    try {
        const res = await fetch('/api/promos/process', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.detail || `Error HTTP ${res.status}`);
        }

        const data = await res.json();
        const jobId = data.job_id;

        updatePromoPhaseBars(5, 'Iniciando pipeline de producción...', 'Conectando con el servidor...');

        promosEventSource = new EventSource(`/api/jobs/${jobId}/stream`);

        promosEventSource.onmessage = (event) => {
            try {
                const msg = JSON.parse(event.data);

                if (msg.type === 'error' || msg.status === 'error') {
                    if (promosEventSource) {
                        promosEventSource.close();
                        promosEventSource = null;
                    }
                    const statusText = document.getElementById('promosPhaseStatusText');
                    if (statusText) statusText.innerText = '❌ Error en procesamiento';
                    const logText = document.getElementById('promosModalLogText');
                    if (logText) logText.innerText = msg.error || msg.message || 'Error en el renderizado.';
                    showToast('Error procesando promo: ' + (msg.error || msg.message), 'error');
                    return;
                }

                if (msg.type === 'completed' || msg.status === 'completed') {
                    if (promosEventSource) {
                        promosEventSource.close();
                        promosEventSource = null;
                    }
                    updatePromoPhaseBars(100, '¡Vídeo Renderizado con Éxito!', 'Generando previsualización final...');
                    handlePromoCompleted(msg);
                    showRenderWarnings(msg.result);
                    return;
                }

                const p = Math.max(5, Math.min(99, Math.round(msg.progress || 0)));
                updatePromoPhaseBars(p, msg.message || 'Procesando...', msg.log || msg.message);
            } catch (err) {
                console.error('Error procesando evento SSE:', err);
            }
        };

        promosEventSource.onerror = (err) => {
            console.warn('Conexión SSE cerrada o finalizada:', err);
            if (promosEventSource) {
                promosEventSource.close();
                promosEventSource = null;
            }
        };

    } catch (e) {
        showToast('Error al iniciar producción: ' + (e.message || e), 'error');
        const statusText = document.getElementById('promosPhaseStatusText');
        if (statusText) statusText.innerText = '❌ Error al iniciar';
        const logText = document.getElementById('promosModalLogText');
        if (logText) logText.innerText = e.message || String(e);
    }
}

function handlePromoCompleted(msg) {
    if (state.promos.isCompleted) return;
    state.promos.isCompleted = true;

    if (promosEventSource) {
        promosEventSource.close();
        promosEventSource = null;
    }

    const videoUrl = msg.result?.video_url || msg.result?.output_video || '';
    const videoFilename = msg.result?.video_filename || 'promo.mp4';
    const runId = msg.result?.run_id || '';

    state.promos.generatedVideos = [{
        variant_index: 1,
        video_url: videoUrl,
        video_filename: videoFilename,
        run_id: runId,
    }];

    showToast('🎉 ¡Promo generada con éxito!', 'success');

    setTimeout(() => {
        const progContainer = document.getElementById('promosModalProgressContainer');
        const resContainer = document.getElementById('promosModalResultContainer');
        const titleEl = document.getElementById('promoStep3Title');
        const subEl = document.getElementById('promoStep3Sub');
        const iconEl = document.getElementById('promoStep3BadgeIcon');

        if (progContainer) progContainer.style.display = 'none';
        if (resContainer) resContainer.style.display = 'block';
        if (titleEl) titleEl.innerText = '🎉 ¡Promo Lista para Publicación!';
        if (subEl) subEl.innerText = 'Genera la descripción, programa la subida en el calendario y descarga tu vídeo';
        if (iconEl) iconEl.innerText = '✅';

        const player = document.getElementById('promosRenderedPlayerModal');
        if (player && videoUrl) {
            if (!player.src || !player.src.endsWith(videoUrl)) {
                player.src = videoUrl;
                player.load();
            }
        }

        const resBadge = document.getElementById('promosRenderedResBadge');
        if (resBadge) {
            const is4K = (state.promos.resolution === '4K');
            resBadge.innerText = is4K ? '2160×3840 4K MP4' : '1080×1920 MP4';
            resBadge.style.background = is4K ? 'rgba(217, 119, 87, 0.18)' : 'rgba(34, 197, 94, 0.15)';
            resBadge.style.color = is4K ? 'var(--claude-accent, #d97757)' : '#4ade80';
            resBadge.style.borderColor = is4K ? 'rgba(217, 119, 87, 0.35)' : 'rgba(34, 197, 94, 0.3)';
        }

        // Auto-generate social description if not already generated
        generatePromoSocialDescription();
    }, 600);
}

