// ---- YouTube Shorts metadata editor ----
function youtubeMetadataContext() {
    const kind = document.getElementById('ytMetadataKind')?.value;
    if (!kind) throw new Error('Selecciona si el vídeo es orgánico o una campaña.');
    return {
        game_name: document.getElementById('promosGameName')?.value.trim() || '',
        briefing: state.promos.v2BriefingText || document.getElementById('promosV2Briefing')?.value || '',
        script_text: state.promos.v2ScriptText || document.getElementById('promosV2ScriptText')?.value || '',
        requested_hashtags: (document.getElementById('promosSocialHashtagInput')?.value || '').split(/[\s,]+/).filter(Boolean),
        required_hashtags: (document.getElementById('ytMetadataRequiredTags')?.value || '').split(/[\s,]+/).filter(Boolean),
        required_cta: document.getElementById('ytMetadataRequiredCta')?.value.trim() || '',
        sponsored: kind === 'campaign'
    };
}
async function generateYoutubeShortsMetadata() {
    const button = document.getElementById('btnYoutubeShortsMetadata');
    const status = document.getElementById('ytMetadataStatus');
    try {
        const context = youtubeMetadataContext();
        if (!context.game_name || (!context.script_text.trim() && !context.briefing.trim())) throw new Error('Añade el nombre del juego y el guion o briefing.');
        button.disabled = true;
        status.textContent = 'Preparando propuestas…';
        const response = await fetch('/api/youtube-shorts/metadata', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...context,use_ai:true})});
        const data = await response.json();
        if (!response.ok) throw new Error(data.detail || 'No se pudieron preparar los textos.');
        state.promos.youtubeMetadata = {...data,context};
        const select = document.getElementById('ytMetadataCandidates');
        select.replaceChildren();
        for (const item of data.title_candidates) {
            const option = document.createElement('option');
            option.value = item.title; option.textContent = item.title; select.appendChild(option);
        }
        document.getElementById('ytMetadataTitle').value = data.title;
        document.getElementById('ytMetadataDescription').value = data.description;
        status.textContent = 'Revisa que todos los datos coincidan con el vídeo. ' + (data.warnings || []).join(' ');
    } catch (error) { status.textContent = error.message; }
    finally { if (button) button.disabled = false; }
}
async function saveYoutubeShortsMetadata() {
    const status = document.getElementById('ytMetadataStatus');
    try {
        const context = youtubeMetadataContext();
        const response = await fetch('/api/youtube-shorts/save-metadata', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...context,title:document.getElementById('ytMetadataTitle').value,description:document.getElementById('ytMetadataDescription').value})});
        const data = await response.json();
        if (!response.ok) throw new Error(data.detail || 'No se pudieron guardar los textos.');
        status.textContent = 'Textos guardados en ' + data.folder + '. Pendientes de subir o programar en YouTube.';
    } catch (error) { status.textContent = error.message; }
}
async function copyYoutubeMetadataField(id) {
    try {
        const text = document.getElementById(id)?.value.trim();
        if (!text) throw new Error('No hay texto para copiar.');
        await navigator.clipboard.writeText(text); showToast('Texto copiado', 'success');
    } catch (error) { showToast(error.message, 'warning'); }
}
function initYoutubeShortsMetadata() {
    const on = (id,event,fn) => document.getElementById(id)?.addEventListener(event,fn);
    on('btnYoutubeShortsMetadata','click',generateYoutubeShortsMetadata);
    on('btnYoutubeSaveMetadata','click',saveYoutubeShortsMetadata);
    on('btnYoutubeCopyTitle','click',() => copyYoutubeMetadataField('ytMetadataTitle'));
    on('btnYoutubeCopyDescription','click',() => copyYoutubeMetadataField('ytMetadataDescription'));
    on('ytMetadataCandidates','change',event => { document.getElementById('ytMetadataTitle').value = event.target.value; });
}
// ---- End YouTube Shorts metadata editor ----

async function generatePromoSocialDescription() {
    if (state.promos.isGeneratingDesc) return;
    state.promos.isGeneratingDesc = true;

    const gameName = document.getElementById('promosGameName')?.value.trim() || 'Gameplay';
    const briefing = state.promos.v2BriefingText || document.getElementById('promosV2Briefing')?.value || '';
    const script = state.promos.v2ScriptText || document.getElementById('promosV2ScriptText')?.value || '';
    const hashtags = document.getElementById('promosSocialHashtagInput')?.value.trim() || '';
    const hookFields = promosHookFields();
    const runId = state.promos.generatedVideos[0]?.run_id || 'latest';

    const btn = document.getElementById('btnPromosGenSocialDesc');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>⏳</span> Generando...';
    }

    try {
        const res = await fetch('/api/promos/generate-description', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_name: gameName,
                briefing: briefing,
                script_text: script,
                ...hookFields,
                hashtags: hashtags,
                run_id: runId
            })
        });

        const data = await res.json();
        if (data.status === 'ok') {
            state.promos.socialDescription = data.description;
            const descArea = document.getElementById('promosSocialDescriptionText');
            if (descArea) descArea.value = data.description;

            // Auto-save description.txt in promo folder
            await fetch('/api/promos/save-description', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    game_name: gameName,
                    run_id: runId,
                    description_text: data.description
                })
            });

            const savedBadge = document.getElementById('promosDescSavedIndicator');
            if (savedBadge) {
                savedBadge.style.display = 'inline-block';
                setTimeout(() => { savedBadge.style.display = 'none'; }, 4000);
            }

            showToast('Descripción para redes generada y guardada en description.txt', 'success');
        } else {
            showToast('Error generando descripción: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error conectando con generador de descripción: ' + e.message, 'error');
    } finally {
        state.promos.isGeneratingDesc = false;
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<span>✨</span> Generar';
        }
    }
}

function copyPromoSocialDescription() {
    const descArea = document.getElementById('promosSocialDescriptionText');
    const text = descArea ? descArea.value.trim() : (state.promos.socialDescription || '');
    if (!text) {
        showToast('No hay descripción para copiar', 'warning');
        return;
    }
    navigator.clipboard.writeText(text).then(() => {
        showToast('📋 ¡Descripción copiada al portapapeles!', 'success');
    }).catch(err => {
        showToast('Error al copiar al portapapeles: ' + err, 'error');
    });
}

async function handlePromoApprovalAndDownload() {
    const dateStr = state.promos.selectedUploadDate;
    if (!dateStr) {
        showToast('Por favor selecciona una fecha de subida (DD-MM-YY) para poder descargar y programar', 'warning');
        return;
    }

    const gameName = document.getElementById('promosGameName')?.value.trim() || 'Promo Game';
    const vid = state.promos.generatedVideos[0];
    if (!vid || !vid.video_url) {
        showToast('No hay ningún vídeo renderizado para descargar', 'error');
        return;
    }

    const btn = document.getElementById('btnPromosApproveDownload');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>⏳</span> Programando y descargando...';
    }

    try {
        // 1. Register event in Calendar (Account: IGD, is_promo: true, date: DD-MM-YY)
        const calRes = await fetch('/api/calendar/events', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_name: gameName,
                date: dateStr,
                account: 'IGD',
                is_promo: true,
                notes: `Promo Short V2 (${hookTypeLabel(state.promos.hookType)})`
            })
        });

        if (!calRes.ok) {
            const errData = await calRes.json().catch(() => ({}));
            throw new Error(errData.detail || 'Error registrando evento en calendario');
        }

        // 2. Trigger MP4 Download
        const a = document.createElement('a');
        a.href = vid.video_url;
        a.download = vid.video_filename || `${sanitizeFolderName(gameName)}_promo.mp4`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);

        // 3. Refresh calendar if loaded
        if (typeof loadCalendarEvents === 'function') {
            loadCalendarEvents();
        }

        showToast(`🎉 ¡Promo aprobada! Descargando vídeo y programada para el ${dateStr} en IGD ($)`, 'success');
    } catch (err) {
        showToast(`Error al aprobar promo: ${err.message}`, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<span>💾</span> Aprobar y Descargar Vídeo MP4';
        }
    }
}

