// =============================================================================
// Calendar Tab & Video Upload Planner Module (Format DD-MM-YY)
// =============================================================================

const CAL_MONTH_NAMES_ES = [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
];

/**
 * Normalizes any date string or Date object to "DD-MM-YY"
 */
function formatDateToDMY(dateInput) {
    if (!dateInput) return '';
    if (typeof dateInput === 'string') {
        const trimmed = dateInput.trim();
        // Check if YYYY-MM-DD
        const mIso = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (mIso) {
            const [, yyyy, mm, dd] = mIso;
            return `${dd}-${mm}-${yyyy.slice(-2)}`;
        }
        // Check if DD-MM-YY or DD-MM-YYYY
        const mDmy = trimmed.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})$/);
        if (mDmy) {
            const [, dd, mm, y] = mDmy;
            const yy = y.length === 4 ? y.slice(-2) : y.padStart(2, '0');
            return `${dd.padStart(2, '0')}-${mm.padStart(2, '0')}-${yy}`;
        }
    }
    const d = new Date(dateInput);
    if (isNaN(d.getTime())) return String(dateInput);
    const dd = String(d.getDate()).padStart(2, '0');
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const yy = String(d.getFullYear()).slice(-2);
    return `${dd}-${mm}-${yy}`;
}

/**
 * Converts "DD-MM-YY" or "DD-MM-YYYY" to "YYYY-MM-DD" for HTML date inputs
 */
function parseDMYToISO(dmyStr) {
    if (!dmyStr) return '';
    const trimmed = String(dmyStr).trim();
    const mDmy = trimmed.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})$/);
    if (mDmy) {
        const [, dd, mm, y] = mDmy;
        const yyyy = y.length === 2 ? `20${y}` : y;
        return `${yyyy}-${mm.padStart(2, '0')}-${dd.padStart(2, '0')}`;
    }
    const mIso = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (mIso) return trimmed;
    return '';
}

/**
 * Returns today's date formatted as DD-MM-YY
 */
function getTodayDMY() {
    return formatDateToDMY(new Date());
}

function initCalendarTab() {
    // Navigation (Prev, Next, Today)
    const btnPrev = document.getElementById('btnCalPrevMonth');
    const btnNext = document.getElementById('btnCalNextMonth');
    const btnToday = document.getElementById('btnCalToday');

    if (btnPrev) {
        btnPrev.addEventListener('click', () => {
            if (state.calendar.currentMonth === 0) {
                state.calendar.currentMonth = 11;
                state.calendar.currentYear -= 1;
            } else {
                state.calendar.currentMonth -= 1;
            }
            renderCalendar();
        });
    }

    if (btnNext) {
        btnNext.addEventListener('click', () => {
            if (state.calendar.currentMonth === 11) {
                state.calendar.currentMonth = 0;
                state.calendar.currentYear += 1;
            } else {
                state.calendar.currentMonth += 1;
            }
            renderCalendar();
        });
    }

    if (btnToday) {
        btnToday.addEventListener('click', () => {
            const now = new Date();
            state.calendar.currentYear = now.getFullYear();
            state.calendar.currentMonth = now.getMonth();
            renderCalendar();
        });
    }

    // Search filter
    const searchInput = document.getElementById('calSearchInput');
    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            state.calendar.searchQuery = (e.target.value || '').trim().toLowerCase();
            renderCalendar();
        });
    }

    // Account filter pills
    const accPills = document.querySelectorAll('#calAccountFilterPills button[data-account-filter]');
    accPills.forEach(pill => {
        pill.addEventListener('click', () => {
            accPills.forEach(p => p.classList.remove('active'));
            pill.classList.add('active');
            state.calendar.filterAccount = pill.dataset.accountFilter || 'all';
            renderCalendar();
        });
    });

    // Promo filter pills
    const promoPills = document.querySelectorAll('#calPromoFilterPills button[data-promo-filter]');
    promoPills.forEach(pill => {
        pill.addEventListener('click', () => {
            promoPills.forEach(p => p.classList.remove('active'));
            pill.classList.add('active');
            state.calendar.filterPromo = pill.dataset.promoFilter || 'all';
            renderCalendar();
        });
    });

    // Open Modal button
    const btnAdd = document.getElementById('btnOpenAddGameModal');
    if (btnAdd) {
        btnAdd.addEventListener('click', () => {
            openCalendarModal();
        });
    }

    // Modal close & cancel buttons
    const btnClose = document.getElementById('btnCloseCalModal');
    const btnCancel = document.getElementById('btnCancelCalModal');
    const modalEl = document.getElementById('modalCalendarGame');

    if (btnClose) btnClose.addEventListener('click', closeCalendarModal);
    if (btnCancel) btnCancel.addEventListener('click', closeCalendarModal);
    if (modalEl) {
        modalEl.addEventListener('click', (e) => {
            if (e.target === modalEl) closeCalendarModal();
        });
    }

    // Date picker live badge preview
    const dateInput = document.getElementById('calInputDate');
    const dateBadge = document.getElementById('calDateDisplayBadge');
    if (dateInput && dateBadge) {
        dateInput.addEventListener('input', () => {
            if (dateInput.value) {
                dateBadge.innerText = formatDateToDMY(dateInput.value);
            } else {
                dateBadge.innerText = '--/--/--';
            }
        });
    }

    // Account radio card selection
    const labelIgd = document.getElementById('labelCalAccIgd');
    const labelGuam = document.getElementById('labelCalAccGuam');
    if (labelIgd && labelGuam) {
        labelIgd.addEventListener('click', () => {
            labelIgd.classList.add('active-igd');
            labelGuam.classList.remove('active-guam');
            const rIgd = labelIgd.querySelector('input[type="radio"]');
            if (rIgd) rIgd.checked = true;
        });
        labelGuam.addEventListener('click', () => {
            labelGuam.classList.add('active-guam');
            labelIgd.classList.remove('active-igd');
            const rGuam = labelGuam.querySelector('input[type="radio"]');
            if (rGuam) rGuam.checked = true;
        });
    }

    // Promo toggle in modal
    const promoToggle = document.getElementById('calInputIsPromo');
    const promoCard = document.getElementById('calPromoToggleCard');
    const promoPreview = document.getElementById('calPromoBadgePreview');
    if (promoToggle) {
        promoToggle.addEventListener('change', () => {
            if (promoCard) promoCard.classList.toggle('active', promoToggle.checked);
            if (promoPreview) promoPreview.style.display = promoToggle.checked ? 'inline-block' : 'none';
        });
    }

    // Save Event Button
    const btnSave = document.getElementById('btnSaveCalEvent');
    if (btnSave) {
        btnSave.addEventListener('click', saveCalendarEvent);
    }

    // Delete Event Button
    const btnDelete = document.getElementById('btnDeleteCalEvent');
    if (btnDelete) {
        btnDelete.addEventListener('click', () => {
            if (state.calendar.editingEventId) {
                deleteCalendarEvent(state.calendar.editingEventId);
            }
        });
    }

    // Keydown ESC
    window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            const m = document.getElementById('modalCalendarGame');
            if (m && m.style.display !== 'none') {
                closeCalendarModal();
            }
        }
    });
}

async function loadCalendarEvents() {
    try {
        const resp = await fetch('/api/calendar');
        if (resp.ok) {
            const data = await resp.json();
            state.calendar.events = data.events || [];
            localStorage.setItem('cal_events_backup', JSON.stringify(state.calendar.events));
        } else {
            throw new Error(`Server returned ${resp.status}`);
        }
    } catch (err) {
        console.warn('Could not fetch calendar from server, falling back to local storage:', err);
        const backup = localStorage.getItem('cal_events_backup');
        if (backup) {
            try { state.calendar.events = JSON.parse(backup); } catch(e){}
        }
    }
    renderCalendar();
}

function renderCalendar() {
    const gridEl = document.getElementById('calendarDaysGrid');
    const monthLabelEl = document.getElementById('calCurrentMonthLabel');
    if (!gridEl) return;

    const year = state.calendar.currentYear;
    const month = state.calendar.currentMonth; // 0-11

    if (monthLabelEl) {
        monthLabelEl.innerText = `${CAL_MONTH_NAMES_ES[month]} ${year}`;
    }

    // Number of days in current month
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    // Day of week of 1st day of month (0 = Sun, 1 = Mon, ..., 6 = Sat)
    let firstDayIndex = new Date(year, month, 1).getDay();
    // Convert to Monday-first (0 = Mon, ..., 6 = Sun)
    firstDayIndex = (firstDayIndex + 6) % 7;

    // Number of days in previous month
    const prevMonthDays = new Date(year, month, 0).getDate();

    const todayStr = getTodayDMY();

    let gridHtml = '';

    // 1. Previous month trailing days
    for (let i = firstDayIndex - 1; i >= 0; i--) {
        const dayNum = prevMonthDays - i;
        const prevMonth = month === 0 ? 11 : month - 1;
        const prevYear = month === 0 ? year - 1 : year;
        const dStr = formatDateToDMY(new Date(prevYear, prevMonth, dayNum));
        gridHtml += `
            <div class="calendar-day-cell other-month" data-date="${dStr}">
                <div class="day-header-row">
                    <span class="day-number">${dayNum}</span>
                </div>
                <div class="day-events-container"></div>
            </div>
        `;
    }

    // 2. Current month days
    let monthTotalCount = 0;
    let monthIgdCount = 0;
    let monthGuamCount = 0;
    let monthPromoCount = 0;

    for (let day = 1; day <= daysInMonth; day++) {
        const cellDate = new Date(year, month, day);
        const cellDmy = formatDateToDMY(cellDate);
        const isToday = (cellDmy === todayStr);

        // Filter events matching this date
        const dayEvents = (state.calendar.events || []).filter(ev => {
            const evDmy = formatDateToDMY(ev.date);
            return evDmy === cellDmy;
        });

        // Count for stats
        dayEvents.forEach(ev => {
            monthTotalCount++;
            if ((ev.account || '').toUpperCase() === 'IGD') monthIgdCount++;
            if ((ev.account || '').toUpperCase() === 'GUAM') monthGuamCount++;
            if (ev.is_promo) monthPromoCount++;
        });

        // Filter events for display based on active filters
        const visibleEvents = dayEvents.filter(ev => {
            // Account filter
            if (state.calendar.filterAccount !== 'all') {
                if ((ev.account || '').toUpperCase() !== state.calendar.filterAccount.toUpperCase()) {
                    return false;
                }
            }
            // Promo filter
            if (state.calendar.filterPromo === 'promo') {
                if (!ev.is_promo) return false;
            }
            // Search query
            if (state.calendar.searchQuery) {
                const q = state.calendar.searchQuery;
                const matchName = (ev.game_name || '').toLowerCase().includes(q);
                const matchNotes = (ev.notes || '').toLowerCase().includes(q);
                if (!matchName && !matchNotes) return false;
            }
            return true;
        });

        let eventsHtml = '';
        visibleEvents.forEach(ev => {
            const accClass = (ev.account || 'IGD').toUpperCase() === 'GUAM' ? 'account-guam' : 'account-igd';
            const promoBadge = ev.is_promo ? `<span class="event-promo-dollar" title="Contenido Promocional ($)">$</span>` : '';
            const gameEscaped = escapeHtml(ev.game_name || 'Juego sin título');
            eventsHtml += `
                <div class="calendar-event-card ${accClass}" data-event-id="${escapeHtml(ev.id)}" title="${gameEscaped} (${escapeHtml(ev.account || 'IGD')}) • ${escapeHtml(cellDmy)}${ev.is_promo ? ' • Promo $' : ''}">
                    <div class="event-left-info">
                        <span class="event-account-dot"></span>
                        <span class="event-game-title">${gameEscaped}</span>
                    </div>
                    ${promoBadge}
                </div>
            `;
        });

        gridHtml += `
            <div class="calendar-day-cell ${isToday ? 'today' : ''}" data-date="${cellDmy}">
                <div class="day-header-row">
                    <span class="day-number" title="${cellDmy}">${day}</span>
                    <button type="button" class="btn-quick-add-day" data-add-date="${cellDmy}" title="Añadir juego el ${cellDmy}">+</button>
                </div>
                <div class="day-events-container">
                    ${eventsHtml}
                </div>
            </div>
        `;
    }

    // 3. Next month leading days (to complete 35 or 42 grid slots)
    const totalCellsSoFar = firstDayIndex + daysInMonth;
    const totalGridSlots = totalCellsSoFar > 35 ? 42 : 35;
    const nextMonthDays = totalGridSlots - totalCellsSoFar;

    for (let day = 1; day <= nextMonthDays; day++) {
        const nextMonth = month === 11 ? 0 : month + 1;
        const nextYear = month === 11 ? year + 1 : year;
        const dStr = formatDateToDMY(new Date(nextYear, nextMonth, day));
        gridHtml += `
            <div class="calendar-day-cell other-month" data-date="${dStr}">
                <div class="day-header-row">
                    <span class="day-number">${day}</span>
                </div>
                <div class="day-events-container"></div>
            </div>
        `;
    }

    gridEl.innerHTML = gridHtml;

    // Attach click listeners on day cells & event cards
    gridEl.querySelectorAll('.btn-quick-add-day').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const d = btn.dataset.addDate;
            openCalendarModal(null, d);
        });
    });

    gridEl.querySelectorAll('.calendar-day-cell:not(.other-month)').forEach(cell => {
        cell.addEventListener('click', (e) => {
            if (e.target === cell || e.target.classList.contains('day-events-container') || e.target.classList.contains('day-header-row')) {
                const d = cell.dataset.date;
                openCalendarModal(null, d);
            }
        });
    });

    gridEl.querySelectorAll('.calendar-event-card').forEach(card => {
        card.addEventListener('click', (e) => {
            e.stopPropagation();
            const id = card.dataset.eventId;
            if (id) openCalendarModal(id);
        });
    });

    // Update Stats Pills
    const statTotalEl = document.getElementById('calStatTotal');
    const statIgdEl = document.getElementById('calStatIgd');
    const statGuamEl = document.getElementById('calStatGuam');
    const statPromoEl = document.getElementById('calStatPromo');

    if (statTotalEl) statTotalEl.innerText = `${monthTotalCount} vídeo${monthTotalCount === 1 ? '' : 's'}`;
    if (statIgdEl) statIgdEl.innerText = `${monthIgdCount} IGD`;
    if (statGuamEl) statGuamEl.innerText = `${monthGuamCount} GUAM`;
    if (statPromoEl) statPromoEl.innerText = `${monthPromoCount} Promo${monthPromoCount === 1 ? '' : 's'}`;

    // Render Upcoming list at bottom
    renderUpcomingList();
}

function renderUpcomingList() {
    const listEl = document.getElementById('calendarUpcomingList');
    if (!listEl) return;

    const events = [...(state.calendar.events || [])];
    if (events.length === 0) {
        listEl.innerHTML = `
            <div style="grid-column: 1 / -1; text-align: center; padding: 24px; color: var(--text-muted); font-size: 13px;">
                No hay vídeos programados todavía. Pulsa <strong>➕ Añadir juego</strong> para planificar tu primera subida.
            </div>
        `;
        return;
    }

    // Sort by date chronological
    events.sort((a, b) => {
        const isoA = parseDMYToISO(a.date) || '9999-99-99';
        const isoB = parseDMYToISO(b.date) || '9999-99-99';
        return isoA.localeCompare(isoB);
    });

    // Take next 8 events
    const nextEvents = events.slice(0, 8);

    listEl.innerHTML = nextEvents.map(ev => {
        const acc = (ev.account || 'IGD').toUpperCase();
        const accClass = acc === 'GUAM' ? 'guam' : 'igd';
        const dmyStr = formatDateToDMY(ev.date);
        const promoBadge = ev.is_promo ? `<span class="event-promo-dollar" style="font-size: 11px; padding: 2px 6px;">$ PROMO</span>` : '';
        const gameEscaped = escapeHtml(ev.game_name || 'Sin título');

        return `
            <div class="upcoming-item-card" data-event-id="${escapeHtml(ev.id)}">
                <div class="upcoming-item-left">
                    <div class="upcoming-acc-indicator ${accClass}">
                        ${escapeHtml(acc)}
                    </div>
                    <div class="upcoming-meta-wrap">
                        <span class="upcoming-game-name">${gameEscaped}</span>
                        <span class="upcoming-date-str">📅 ${escapeHtml(dmyStr)}</span>
                    </div>
                </div>
                <div class="upcoming-item-right">
                    ${promoBadge}
                </div>
            </div>
        `;
    }).join('');

    listEl.querySelectorAll('.upcoming-item-card').forEach(card => {
        card.addEventListener('click', () => {
            const id = card.dataset.eventId;
            if (id) openCalendarModal(id);
        });
    });
}

function openCalendarModal(eventId = null, defaultDateDMY = null) {
    const modalEl = document.getElementById('modalCalendarGame');
    if (!modalEl) return;

    state.calendar.editingEventId = eventId;

    const titleEl = document.getElementById('calModalTitle');
    const inputId = document.getElementById('calInputEventId');
    const inputName = document.getElementById('calInputGameName');
    const inputDate = document.getElementById('calInputDate');
    const dateBadge = document.getElementById('calDateDisplayBadge');
    const inputPromo = document.getElementById('calInputIsPromo');
    const promoCard = document.getElementById('calPromoToggleCard');
    const promoPreview = document.getElementById('calPromoBadgePreview');
    const inputNotes = document.getElementById('calInputNotes');
    const btnDelete = document.getElementById('btnDeleteCalEvent');
    const labelIgd = document.getElementById('labelCalAccIgd');
    const labelGuam = document.getElementById('labelCalAccGuam');

    // Populate game datalist suggestions
    populateCalendarGameSuggestions();

    if (eventId) {
        // Edit Mode
        const ev = (state.calendar.events || []).find(e => e.id === eventId);
        if (!ev) return;

        if (titleEl) titleEl.innerText = 'Editar Juego Programado';
        if (inputId) inputId.value = ev.id;
        if (inputName) inputName.value = ev.game_name || '';

        const dmy = formatDateToDMY(ev.date);
        if (inputDate) inputDate.value = parseDMYToISO(dmy);
        if (dateBadge) dateBadge.innerText = dmy || '--/--/--';

        const isGuam = (ev.account || '').toUpperCase() === 'GUAM';
        if (labelIgd && labelGuam) {
            labelIgd.classList.toggle('active-igd', !isGuam);
            labelGuam.classList.toggle('active-guam', isGuam);
            const rIgd = labelIgd.querySelector('input[type="radio"]');
            const rGuam = labelGuam.querySelector('input[type="radio"]');
            if (rIgd) rIgd.checked = !isGuam;
            if (rGuam) rGuam.checked = isGuam;
        }

        const isPromo = Boolean(ev.is_promo);
        if (inputPromo) inputPromo.checked = isPromo;
        if (promoCard) promoCard.classList.toggle('active', isPromo);
        if (promoPreview) promoPreview.style.display = isPromo ? 'inline-block' : 'none';

        if (inputNotes) inputNotes.value = ev.notes || '';
        if (btnDelete) btnDelete.style.display = 'inline-flex';

    } else {
        // Create Mode
        if (titleEl) titleEl.innerText = 'Programar Subida de Vídeo';
        if (inputId) inputId.value = '';
        if (inputName) inputName.value = '';

        const targetDmy = defaultDateDMY || getTodayDMY();
        if (inputDate) inputDate.value = parseDMYToISO(targetDmy);
        if (dateBadge) dateBadge.innerText = targetDmy;

        if (labelIgd && labelGuam) {
            labelIgd.classList.add('active-igd');
            labelGuam.classList.remove('active-guam');
            const rIgd = labelIgd.querySelector('input[type="radio"]');
            if (rIgd) rIgd.checked = true;
        }

        if (inputPromo) inputPromo.checked = false;
        if (promoCard) promoCard.classList.remove('active');
        if (promoPreview) promoPreview.style.display = 'none';

        if (inputNotes) inputNotes.value = '';
        if (btnDelete) btnDelete.style.display = 'none';
    }

    modalEl.style.display = 'flex';
    // Force reflow for CSS transition
    void modalEl.offsetWidth;
    modalEl.classList.add('active');

    if (inputName) {
        setTimeout(() => inputName.focus(), 80);
    }
}

function closeCalendarModal() {
    const modalEl = document.getElementById('modalCalendarGame');
    if (!modalEl) return;
    modalEl.classList.remove('active');
    setTimeout(() => {
        modalEl.style.display = 'none';
        state.calendar.editingEventId = null;
    }, 200);
}

function populateCalendarGameSuggestions() {
    const datalist = document.getElementById('calGameSuggestions');
    if (!datalist) return;

    const gameNames = new Set();

    // From Game Profiles
    if (state.gamedev && Array.isArray(state.gamedev.games)) {
        state.gamedev.games.forEach(g => {
            if (g.title) gameNames.add(g.title);
            if (g.name) gameNames.add(g.name);
        });
    }

    // From Promos saved games
    if (state.promos && Array.isArray(state.promos.savedGames)) {
        state.promos.savedGames.forEach(g => {
            if (typeof g === 'string') gameNames.add(g);
            else if (g && g.name) gameNames.add(g.name);
        });
    }

    // From existing calendar events
    if (state.calendar && Array.isArray(state.calendar.events)) {
        state.calendar.events.forEach(e => {
            if (e.game_name) gameNames.add(e.game_name);
        });
    }

    datalist.innerHTML = Array.from(gameNames)
        .map(name => `<option value="${escapeHtml(name)}">`)
        .join('');
}

async function saveCalendarEvent() {
    const inputId = document.getElementById('calInputEventId');
    const inputName = document.getElementById('calInputGameName');
    const inputDate = document.getElementById('calInputDate');
    const inputPromo = document.getElementById('calInputIsPromo');
    const inputNotes = document.getElementById('calInputNotes');
    const rGuam = document.querySelector('input[name="calAccount"][value="GUAM"]');

    const gameName = (inputName ? inputName.value : '').trim();
    if (!gameName) {
        showToast('Introduce el nombre del juego', 'error');
        if (inputName) inputName.focus();
        return;
    }

    const rawDate = inputDate ? inputDate.value : '';
    if (!rawDate) {
        showToast('Selecciona la fecha de subida', 'error');
        if (inputDate) inputDate.focus();
        return;
    }

    const dmyDate = formatDateToDMY(rawDate);
    const account = (rGuam && rGuam.checked) ? 'GUAM' : 'IGD';
    const isPromo = inputPromo ? Boolean(inputPromo.checked) : false;
    const notes = inputNotes ? inputNotes.value.trim() : '';
    const eventId = inputId ? inputId.value.trim() : null;

    const payload = {
        id: eventId || undefined,
        game_name: gameName,
        date: dmyDate, // Format: DD-MM-YY
        is_promo: isPromo,
        account: account,
        notes: notes,
    };

    try {
        const resp = await fetch('/api/calendar', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
        });

        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const result = await resp.json();

        // Update local state
        const savedEvent = result.event || payload;
        const existingIdx = (state.calendar.events || []).findIndex(e => e.id === savedEvent.id);
        if (existingIdx >= 0) {
            state.calendar.events[existingIdx] = savedEvent;
        } else {
            state.calendar.events.push(savedEvent);
        }

        localStorage.setItem('cal_events_backup', JSON.stringify(state.calendar.events));
        showToast(`Juego "${gameName}" programado para el ${dmyDate}`, 'success');
        closeCalendarModal();
        renderCalendar();

    } catch (err) {
        console.error('Error saving calendar event:', err);
        // Save locally anyway
        const fallbackId = eventId || `cal_${Date.now()}`;
        const localEvent = { ...payload, id: fallbackId };
        const existingIdx = (state.calendar.events || []).findIndex(e => e.id === fallbackId);
        if (existingIdx >= 0) {
            state.calendar.events[existingIdx] = localEvent;
        } else {
            state.calendar.events.push(localEvent);
        }
        localStorage.setItem('cal_events_backup', JSON.stringify(state.calendar.events));
        showToast(`Guardado localmente (${dmyDate})`, 'info');
        closeCalendarModal();
        renderCalendar();
    }
}

async function deleteCalendarEvent(eventId) {
    if (!eventId) return;

    try {
        const resp = await fetch(`/api/calendar/${encodeURIComponent(eventId)}`, {
            method: 'DELETE',
        });
        if (!resp.ok && resp.status !== 404) {
            throw new Error(`HTTP ${resp.status}`);
        }
    } catch (err) {
        console.warn('Error deleting event on server:', err);
    }

    // Remove from state
    state.calendar.events = (state.calendar.events || []).filter(e => e.id !== eventId);
    localStorage.setItem('cal_events_backup', JSON.stringify(state.calendar.events));
    showToast('Subida eliminada del calendario', 'info');
    closeCalendarModal();
    renderCalendar();
}

// Global exposure
window.initCalendarTab = initCalendarTab;
window.loadCalendarEvents = loadCalendarEvents;
window.renderCalendar = renderCalendar;
window.openCalendarModal = openCalendarModal;
window.closeCalendarModal = closeCalendarModal;
window.saveCalendarEvent = saveCalendarEvent;
window.deleteCalendarEvent = deleteCalendarEvent;


