function updatePromoV3SessionBanner(sessionData = null) {
    const banner = document.getElementById('promov3SessionInfoBanner');
    if (!banner) return;

    const s1 = sessionData ? sessionData.has_step1 : Boolean(state.promov3 && state.promov3.step1Result);
    const s2 = sessionData ? sessionData.has_step2 : Boolean(state.promov3 && state.promov3.step2Result);
    const s3 = sessionData ? sessionData.has_step3 : Boolean(state.promov3 && state.promov3.step3Result);
    const s4 = sessionData ? sessionData.has_step4 : Boolean(state.promov3 && state.promov3.step4Result);

    if (!s1 && !s2 && !s3 && !s4) {
        banner.style.display = 'none';
        return;
    }

    banner.style.display = 'flex';
    const videoName = state.promov3 && state.promov3.selectedVideo ? state.promov3.selectedVideo.filename : (sessionData && sessionData.video_info ? sessionData.video_info.filename : 'Vídeo');
    const titleEl = document.getElementById('promov3SessionVideoTitle');
    if (titleEl) titleEl.textContent = videoName;

    const sessId = (sessionData && sessionData.session_id) || (state.promov3 && state.promov3.sessionId) || (state.promov3 && state.promov3.step1Result && state.promov3.step1Result.session_id) || '';
    const sessText = document.getElementById('promov3SessionIdText');
    if (sessText) sessText.textContent = sessId ? `[${sessId.length > 25 ? sessId.slice(0, 25) + '...' : sessId}]` : '';

    const p1 = document.getElementById('pillSessionStep1');
    if (p1) {
        p1.textContent = s1 ? 'Paso 1: ✓ Planos listos' : 'Paso 1: -';
        p1.style.background = s1 ? 'rgba(52, 211, 153, 0.15)' : 'rgba(255, 255, 255, 0.06)';
        p1.style.color = s1 ? '#34d399' : 'var(--text-muted)';
        p1.style.border = s1 ? '1px solid rgba(52, 211, 153, 0.3)' : 'none';
    }

    const p2 = document.getElementById('pillSessionStep2');
    if (p2) {
        p2.textContent = s2 ? 'Paso 2: ✓ Evaluación 9:16 lista' : 'Paso 2: -';
        p2.style.background = s2 ? 'rgba(167, 139, 250, 0.15)' : 'rgba(255, 255, 255, 0.06)';
        p2.style.color = s2 ? '#a78bfa' : 'var(--text-muted)';
        p2.style.border = s2 ? '1px solid rgba(167, 139, 250, 0.3)' : 'none';
    }

    const p3 = document.getElementById('pillSessionStep3');
    if (p3) {
        p3.textContent = s3 ? 'Paso 3: ✓ Guión y voz listos' : 'Paso 3: -';
        p3.style.background = s3 ? 'rgba(56, 189, 248, 0.15)' : 'rgba(255, 255, 255, 0.06)';
        p3.style.color = s3 ? '#38bdf8' : 'var(--text-muted)';
        p3.style.border = s3 ? '1px solid rgba(56, 189, 248, 0.3)' : 'none';
    }

    const p4 = document.getElementById('pillSessionStep4');
    if (p4) {
        p4.textContent = s4 ? 'Paso 4: ✓ Montaje listo' : 'Paso 4: -';
        p4.style.background = s4 ? 'rgba(251, 191, 36, 0.15)' : 'rgba(255, 255, 255, 0.06)';
        p4.style.color = s4 ? '#fbbf24' : 'var(--text-muted)';
        p4.style.border = s4 ? '1px solid rgba(251, 191, 36, 0.3)' : 'none';
    }
}

function resetPromoV3Steps() {
    if (!state.promov3) state.promov3 = {};
    state.promov3.step1Result = null;
    state.promov3.step2Result = null;
    state.promov3.step3Result = null;

    // Reset Step 1 Output
    const out1 = document.getElementById('promov3OutputSection');
    if (out1) out1.style.display = 'none';
    const rerun1 = document.getElementById('btnPromoV3RerunStep1');
    if (rerun1) rerun1.style.display = 'none';
    const save1 = document.getElementById('btnPromoV3SaveStep1');
    if (save1) save1.style.display = 'none';
    const badge1 = document.getElementById('promov3Step1StatusBadge');
    if (badge1) {
        badge1.textContent = 'Listo para ejecutar';
        badge1.style.background = 'rgba(255, 255, 255, 0.05)';
        badge1.style.color = 'var(--text-secondary)';
    }

    // Lock Step 2
    const cell2 = document.getElementById('cellPromoV3Step2');
    if (cell2) {
        cell2.classList.add('cell-disabled');
        cell2.classList.remove('cell-active');
    }
    const btnRun2 = document.getElementById('btnPromoV3RunStep2');
    if (btnRun2) btnRun2.disabled = true;
    const rerun2 = document.getElementById('btnPromoV3RerunStep2');
    if (rerun2) rerun2.style.display = 'none';
    const save2 = document.getElementById('btnPromoV3SaveStep2');
    if (save2) save2.style.display = 'none';
    const out2 = document.getElementById('promov3Step2OutputSection');
    if (out2) out2.style.display = 'none';
    const badge2 = document.getElementById('promov3Step2StatusBadge');
    if (badge2) {
        badge2.textContent = 'Pendiente de Paso 1';
        badge2.style.background = 'rgba(255, 255, 255, 0.06)';
        badge2.style.color = 'var(--text-muted)';
    }

    // Lock Step 3
    const cell3 = document.getElementById('cellPromoV3Step3');
    if (cell3) {
        cell3.classList.add('cell-disabled', 'cell-locked');
        cell3.classList.remove('cell-active');
    }
    const badge3 = document.getElementById('promov3Step3StatusBadge');
    if (badge3) {
        badge3.textContent = 'Pendiente de Paso 2';
        badge3.style.background = 'rgba(255, 255, 255, 0.06)';
        badge3.style.color = 'var(--text-muted)';
    }

    // Reset Step 4
    if (state.promov3) {
        state.promov3.step4Result = null;
        state.promov3.isStep4Running = false;
    }
    const cell4 = document.getElementById('cellPromoV3Step4');
    if (cell4) {
        cell4.classList.add('cell-locked');
        cell4.style.opacity = '0.55';
    }
    const badge4 = document.getElementById('promov3Step4StatusBadge');
    if (badge4) {
        badge4.textContent = 'Bloqueado hasta validar Paso 3';
        badge4.style.background = 'rgba(255, 255, 255, 0.05)';
        badge4.style.color = 'var(--text-muted)';
    }
    const lock4 = document.getElementById('promov3Step4LockIcon');
    if (lock4) lock4.textContent = '🔒';
    const s4Results = document.getElementById('promov3Step4ResultsContainer');
    if (s4Results) s4Results.style.display = 'none';
    const s4Empty = document.getElementById('promov3Step4EmptyPlaceholder');
    if (s4Empty) s4Empty.style.display = 'block';

    // Reset Step 5
    if (state.promov3) {
        state.promov3.step5Result = null;
        state.promov3.isStep5Running = false;
    }
    const cell5 = document.getElementById('cellPromoV3Step5');
    if (cell5) {
        cell5.classList.add('cell-locked');
        cell5.style.opacity = '0.55';
    }
    const badge5 = document.getElementById('promov3Step5StatusBadge');
    if (badge5) {
        badge5.textContent = 'Bloqueado hasta validar Paso 4';
        badge5.style.background = 'rgba(255, 255, 255, 0.05)';
        badge5.style.color = 'var(--text-muted)';
    }
    const lock5 = document.getElementById('promov3Step5LockIcon');
    if (lock5) lock5.textContent = '🔒';
    const s5Delivery = document.getElementById('promov3Step5DeliveryContainer');
    if (s5Delivery) s5Delivery.style.display = 'none';
    const s5Progress = document.getElementById('promov3Step5ProgressBox');
    if (s5Progress) s5Progress.style.display = 'none';

    // Reset Stepper indicators
    const stepperIndicators = document.querySelectorAll('.v3-step-indicator');
    stepperIndicators.forEach((ind, idx) => {
        if (idx === 0) {
            ind.classList.remove('locked');
            ind.classList.add('active');
            ind.style.opacity = '1';
        } else {
            ind.classList.add('locked');
            ind.classList.remove('active');
            ind.style.opacity = '0.6';
        }
    });

    // Hide Session Banner
    const banner = document.getElementById('promov3SessionInfoBanner');
    if (banner) banner.style.display = 'none';
}

function restorePromoV3Session(sessionData) {
    if (!sessionData) return;

    // 0. Restore selected videos in state and UI
    if (sessionData.step1) {
        const s1 = sessionData.step1;
        if (s1.videos && s1.videos.length > 0) {
            state.promov3.selectedVideos = s1.videos.map(v => ({
                filename: v.filename,
                path: v.path,
                url: v.url || `/media/PromosFootage/${encodeURIComponent(v.filename)}`,
                size_mb: v.size_mb || 0,
                duration: v.duration,
                width: v.width,
                height: v.height,
                fps: v.fps,
                is_vertical: v.is_vertical,
            }));
            state.promov3.selectedVideo = state.promov3.selectedVideos[0];
            renderPromoV3SelectedVideos();
        } else if (s1.video_info && s1.video_info.path) {
            state.promov3.selectedVideos = [{
                filename: s1.video_info.filename,
                path: s1.video_info.path,
                duration: s1.video_info.duration,
                width: s1.video_info.width,
                height: s1.video_info.height,
                fps: s1.video_info.fps,
                is_vertical: s1.video_info.is_vertical,
            }];
            state.promov3.selectedVideo = state.promov3.selectedVideos[0];
            renderPromoV3SelectedVideos();
        }
    }

    // 1. Restore Step 1
    if (sessionData.has_step1 && sessionData.step1) {
        state.promov3.step1Result = sessionData.step1;
        finishPromoV3Step1Success(sessionData.step1, true);
    }

    // 2. Restore Step 2
    if (sessionData.has_step2 && sessionData.step2) {
        state.promov3.step2Result = sessionData.step2;
        finishPromoV3Step2Success(sessionData.step2, true);
    }

    // 3. Restore Step 3
    if (sessionData.has_step3 && sessionData.step3) {
        const s3 = sessionData.step3;
        state.promov3.step3Result = s3;

        const gName = document.getElementById('promov3GameName');
        if (gName && s3.game_name) gName.value = s3.game_name;

        state.promov3.openingText = s3.opening_text || '';
        const openingInput = document.getElementById('promov3OpeningText');
        if (openingInput) openingInput.value = state.promov3.openingText;
        setPromoV3HookType(s3.hook_type || 'steam_new_game');

        const toneSel = document.getElementById('promov3ToneSelect');
        if (toneSel && s3.tone) toneSel.value = s3.tone;

        const durSlider = document.getElementById('promov3TargetDuration');
        const durVal = document.getElementById('promov3TargetDurationVal');
        if (durSlider && s3.target_duration) {
            durSlider.value = s3.target_duration;
            if (durVal) durVal.textContent = `${s3.target_duration}s`;
        }

        const briefEl = document.getElementById('promov3Briefing');
        if (briefEl && s3.briefing_text) briefEl.value = s3.briefing_text;

        const scriptEl = document.getElementById('promov3ScriptText');
        if (scriptEl && s3.script_text) {
            scriptEl.value = s3.script_text;
            state.promov3.scriptText = s3.script_text;
        }

        if (s3.voice_path || s3.voice_url) {
            state.promov3.voiceMode = s3.voice_mode || 'custom';
            state.promov3.voicePath = s3.voice_path || '';
            state.promov3.voiceUrl = s3.voice_url || '';
            state.promov3.voiceDuration = s3.voice_duration || 0;

            const playerBox = document.getElementById('promov3VoicePlayerContainer');
            const audioElem = document.getElementById('promov3VoiceAudioElem');
            const fileNameElem = document.getElementById('promov3VoiceFileName');
            const durElem = document.getElementById('promov3VoiceDurationDisplay');
            const spdSlider = document.getElementById('promov3VoiceSpeedSlider');
            const spdValElem = document.getElementById('promov3VoiceSpeedVal');
            const stbSlider = document.getElementById('promov3VoiceStabilitySlider');
            const stbValElem = document.getElementById('promov3VoiceStabilityVal');

            if (s3.speed !== undefined && spdSlider) {
                spdSlider.value = s3.speed;
                if (spdValElem) spdValElem.textContent = `${parseFloat(s3.speed).toFixed(2)}x`;
            }
            if (s3.stability !== undefined && stbSlider) {
                stbSlider.value = s3.stability;
                if (stbValElem) stbValElem.textContent = parseFloat(s3.stability).toFixed(2);
            }
            const simSlider = document.getElementById('promov3VoiceSimilaritySlider');
            if (s3.similarity_boost !== undefined && s3.similarity_boost !== null && simSlider) {
                simSlider.value = s3.similarity_boost;
                const simValElem = document.getElementById('promov3VoiceSimilarityVal');
                if (simValElem) simValElem.textContent = parseFloat(s3.similarity_boost).toFixed(2);
            }

            if (playerBox) playerBox.style.display = 'block';
            if (audioElem && s3.voice_url) audioElem.src = s3.voice_url;
            const curSpd = s3.speed !== undefined ? parseFloat(s3.speed).toFixed(2) : '1.10';
            const curStb = s3.stability !== undefined ? parseFloat(s3.stability).toFixed(2) : '0.50';
            if (fileNameElem) {
                const timing = s3.alignment || s3;
                const speeds = timing.speed_hook != null
                    ? `Hook ${Number(timing.speed_hook).toFixed(2)}x · Resto ${Number(timing.speed_full ?? timing.speed_hook).toFixed(2)}x`
                    : `${Number(timing.speed_full ?? curSpd).toFixed(2)}x`;
                fileNameElem.textContent = `Locución (${speeds}, Estabilidad ${curStb})`;
            }
            if (durElem) durElem.textContent = `${(s3.voice_duration || 0).toFixed(3)}s`;
            const curTimeDisp = document.getElementById('promov3VoiceCurrentTimeDisplay');
            if (curTimeDisp) curTimeDisp.textContent = `⏱️ 0.000s / ${(s3.voice_duration || 0).toFixed(3)}s`;

            if (s3.sentence_1_end_s !== undefined && s3.sentence_1_end_s !== null) {
                state.promov3.sentence1EndS = s3.sentence_1_end_s;
                const cutSlider = document.getElementById('promov3Sentence1CutSlider');
                const cutValElem = document.getElementById('promov3Sentence1CutVal');
                const cutMaxLabel = document.getElementById('promov3Sentence1CutMaxLabel');
                const maxVal = s3.voice_duration ? Math.min(10.0, s3.voice_duration) : 6.0;
                if (cutSlider) {
                    cutSlider.max = maxVal.toFixed(3);
                    cutSlider.value = parseFloat(s3.sentence_1_end_s).toFixed(3);
                }
                if (cutValElem) cutValElem.textContent = `${parseFloat(s3.sentence_1_end_s).toFixed(3)}s`;
                if (cutMaxLabel) cutMaxLabel.textContent = `${maxVal.toFixed(3)}s`;
                if (typeof window.updateRaiser2AutoTiming === 'function') {
                    window.updateRaiser2AutoTiming(s3.sentence_1_end_s);
                }
            }
        }

        updatePromoV3ScriptStats();

        const badge3 = document.getElementById('promov3Step3StatusBadge');
        if (badge3) {
            badge3.textContent = `Aprobado: ${s3.word_count || 0} palabras`;
            badge3.style.background = 'rgba(52, 211, 153, 0.2)';
            badge3.style.color = '#34d399';
        }

        unlockPromoV3Step4(s3);
    }

    // 4. Restore Step 4
    if (sessionData.has_step4 && sessionData.step4) {
        const s4 = sessionData.step4;
        state.promov3.step4Result = s4;
        if (s4.cut_start_mode) {
            state.promov3.cutStartMode = normalizeCutStartMode(s4.cut_start_mode);
            const cutModeSel = document.getElementById('promov3CutStartMode');
            if (cutModeSel) cutModeSel.value = state.promov3.cutStartMode;
        }
        finishPromoV3Step4Success(s4, true);
    }

    // 5. Restore Step 5
    if (sessionData.has_step5 && sessionData.step5) {
        const s5 = sessionData.step5;
        state.promov3.step5Result = s5;
        const restoredRenderOptions = renderOptionsFromResult(s5);
        if (restoredRenderOptions) {
            applyRenderOptionsToState(state.promov3, restoredRenderOptions);
            writeRenderOptionsToUi('promov3', restoredRenderOptions);
        }
        finishPromoV3Step5Success(s5, true);
        if (typeof setupClassicPromoV3ApprovalUI === 'function') {
            setupClassicPromoV3ApprovalUI(s5, sessionData.approval);
        }
        if (typeof wizardSetupApprovalUI === 'function') {
            wizardSetupApprovalUI(s5, sessionData.approval);
        }
    }
}

async function checkAndLoadPromoV3SavedProgress(videoPath, silent = false) {
    if (!videoPath) return false;
    const sessId = (state.promov3 && state.promov3.sessionId) || localStorage.getItem('promov3_active_session_id') || '';
    try {
        const url = `/api/promov3/session?video_path=${encodeURIComponent(videoPath)}&session_id=${encodeURIComponent(sessId)}`;
        const res = await fetch(url);
        const data = await res.json();
        if (data.status === 'ok' && data.found) {
            state.promov3.sessionId = data.session_id;
            localStorage.setItem('promov3_active_session_id', data.session_id);
            localStorage.setItem('promov3_active_video_path', videoPath);
            restorePromoV3Session(data);
            if (!silent) {
                const parts = [];
                if (data.has_step1) parts.push('Paso 1');
                if (data.has_step2) parts.push('Paso 2');
                if (data.has_step3) parts.push('Paso 3');
                if (data.has_step4) parts.push('Paso 4');
                if (data.has_step5) parts.push('Paso 5 (Final Render)');
                showToast(`📂 Progreso restaurado desde disco: ${parts.join(', ')} listos para continuar.`, 'info');
            }
            return true;
        } else {
            resetPromoV3Steps();
            return false;
        }
    } catch (e) {
        console.warn('Error checking saved session progress:', e);
        return false;
    }
}

async function savePromoV3Step1Progress(silent = false) {
    if (!state.promov3 || !state.promov3.step1Result) {
        if (!silent) showToast('No hay resultados del Paso 1 para guardar. Ejecuta la detección primero.', 'warning');
        return;
    }
    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || (state.promov3.step1Result.video_info && state.promov3.step1Result.video_info.path) || '';
    if (!videoPath) {
        if (!silent) showToast('No se ha identificado el vídeo asociado al Paso 1.', 'warning');
        return;
    }
    try {
        const res = await fetch('/api/promov3/step1/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                video_path: videoPath,
                session_id: state.promov3.step1Result.session_id || state.promov3.sessionId,
                step1_result: state.promov3.step1Result,
            }),
        });
        const data = await parseJsonResponse(res);
        if (data.status === 'ok') {
            state.promov3.sessionId = data.session_id;
            localStorage.setItem('promov3_active_session_id', data.session_id);
            localStorage.setItem('promov3_active_video_path', videoPath);
            updatePromoV3SessionBanner();
            if (!silent) showToast('💾 Progreso del Paso 1 guardado correctamente en disco.', 'success');
        } else {
            if (!silent) showToast('Error guardando Paso 1: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        if (!silent) showToast('Error al conectar para guardar Paso 1: ' + e.message, 'error');
    }
}

async function savePromoV3Step2Progress(silent = false) {
    if (!state.promov3 || !state.promov3.step2Result) {
        if (!silent) showToast('No hay resultados del Paso 2 para guardar. Ejecuta la evaluación primero.', 'warning');
        return;
    }
    const sessionId = state.promov3.step2Result.session_id || (state.promov3.step1Result && state.promov3.step1Result.session_id) || state.promov3.sessionId;
    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || '';
    if (!sessionId && !videoPath) {
        if (!silent) showToast('No se encontró sesión activa del Paso 2.', 'warning');
        return;
    }
    try {
        const res = await fetch('/api/promov3/step2/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                session_id: sessionId,
                video_path: videoPath,
                step2_result: state.promov3.step2Result,
            }),
        });
        const data = await parseJsonResponse(res);
        if (data.status === 'ok') {
            state.promov3.sessionId = data.session_id;
            localStorage.setItem('promov3_active_session_id', data.session_id);
            if (videoPath) localStorage.setItem('promov3_active_video_path', videoPath);
            updatePromoV3SessionBanner();
            if (!silent) showToast('💾 Progreso del Paso 2 guardado correctamente en disco.', 'success');
        } else {
            if (!silent) showToast('Error guardando Paso 2: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        if (!silent) showToast('Error al conectar para guardar Paso 2: ' + e.message, 'error');
    }
}

async function savePromoV3Step3Progress(isDraft = true, silent = false) {
    const scriptEl = document.getElementById('promov3ScriptText');
    const scriptText = (scriptEl ? scriptEl.value : (state.promov3.scriptText || '')).trim();
    const gameName = (document.getElementById('promov3GameName') ? document.getElementById('promov3GameName').value : 'Gameplay').trim();
    const hookFields = promoV3HookFields();
    const tone = (document.getElementById('promov3ToneSelect') ? document.getElementById('promov3ToneSelect').value : 'viral_hype');
    const targetDur = parseFloat(document.getElementById('promov3TargetDuration') ? document.getElementById('promov3TargetDuration').value : 30.0) || 30.0;
    const briefing = (document.getElementById('promov3Briefing') ? document.getElementById('promov3Briefing').value : '').trim();
    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || '';
    const sessionId = (state.promov3.step1Result && state.promov3.step1Result.session_id) || (state.promov3.step2Result && state.promov3.step2Result.session_id) || state.promov3.sessionId || localStorage.getItem('promov3_active_session_id') || '';

    const words = scriptText ? scriptText.split(/\s+/).filter(Boolean).length : 0;
    const estDur = words > 0 ? parseFloat((words / 2.3).toFixed(1)) : (state.promov3.voiceDuration || 0);

    const step3Data = {
        session_id: sessionId || null,
        video_path: videoPath || null,
        game_name: gameName,
        ...hookFields,
        tone: tone,
        target_duration: targetDur,
        briefing_text: briefing,
        script_text: scriptText,
        word_count: words,
        estimated_duration: estDur,
        voice_mode: state.promov3.voiceMode || 'elevenlabs',
        voice_path: state.promov3.voicePath || null,
        voice_url: state.promov3.voiceUrl || null,
        voice_duration: state.promov3.voiceDuration || null,
        sentence_1_end_s: parseFloat(document.getElementById('promov3Sentence1CutSlider')?.value) || state.promov3.sentence1EndS || null,
    };

    try {
        const res = await fetch('/api/promov3/step3/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(step3Data),
        });
        const data = await parseJsonResponse(res);
        if (data.status === 'ok') {
            state.promov3.step3Result = data.data;
            state.promov3.sessionId = data.session_id;
            localStorage.setItem('promov3_active_session_id', data.session_id);
            if (videoPath) localStorage.setItem('promov3_active_video_path', videoPath);
            updatePromoV3SessionBanner();
            if (!silent) showToast(isDraft ? '💾 Borrador del Paso 3 guardado en disco' : '¡Paso 3 guardado!', 'success');
            return true;
        } else {
            if (!silent) showToast('Error guardando Paso 3: ' + (data.detail || 'Error'), 'error');
            return false;
        }
    } catch (e) {
        if (!silent) showToast('Error al guardar Paso 3: ' + e.message, 'error');
        return false;
    }
}

function initPromoV3() {
    if (state.promov3 && state.promov3.initialized) {
        return;
    }
    state.promov3 = state.promov3 || {};
    state.promov3.initialized = true;

    // 1. Setup Drop Area & File Input (Multiple Files Supported)
    const dropArea = document.getElementById('promov3DropArea');
    const fileInput = document.getElementById('promov3FileInput');
    if (dropArea && fileInput) {
        dropArea.addEventListener('click', () => fileInput.click());
        dropArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropArea.classList.add('drag-over');
        });
        dropArea.addEventListener('dragleave', () => dropArea.classList.remove('drag-over'));
        dropArea.addEventListener('drop', (e) => {
            e.preventDefault();
            dropArea.classList.remove('drag-over');
            if (e.dataTransfer.files && e.dataTransfer.files.length) {
                handlePromoV3FileUpload(e.dataTransfer.files);
            }
        });
        fileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files.length) {
                handlePromoV3FileUpload(e.target.files);
            }
        });
    }

    // 2. Setup Footage Dropdown Selector & Add Button
    const footageSelect = document.getElementById('promov3FootageSelect');
    const btnAddFootage = document.getElementById('btnPromoV3AddFootage');
    if (btnAddFootage) {
        btnAddFootage.addEventListener('click', () => {
            const select = document.getElementById('promov3FootageSelect');
            if (select && select.value) {
                handlePromoV3FootageSelection(select.value, true);
            } else {
                showToast('Selecciona una carpeta o clip del desplegable para añadirlo', 'info');
            }
        });
    }
    if (footageSelect) {
        footageSelect.addEventListener('change', (e) => {
            const val = e.target.value;
            handlePromoV3FootageSelection(val, true);
        });
    }

    // 2b. Setup Clear Footage Button
    const btnClearFootage = document.getElementById('btnPromoV3ClearFootage');
    if (btnClearFootage) {
        btnClearFootage.addEventListener('click', () => clearPromoV3Videos());
    }

    // 2c. Setup YouTube Ingestion Handler (Promo V3 tab)
    const btnPromoV3Yt = document.getElementById('btnPromoV3IngestYoutube');
    if (btnPromoV3Yt) {
        btnPromoV3Yt.addEventListener('click', () => ingestYoutubeVideo('promov3YoutubeUrl', 'promov3GameName', 'btnPromoV3IngestYoutube', true));
    }
    const ytInput3 = document.getElementById('promov3YoutubeUrl');
    if (ytInput3) {
        ytInput3.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                ingestYoutubeVideo('promov3YoutubeUrl', 'promov3GameName', 'btnPromoV3IngestYoutube', true);
            }
        });
    }

    // 3. Setup Parameter Sliders & Number Sync
    const thSlider = document.getElementById('promov3AdaptiveThreshold');
    const thVal = document.getElementById('promov3AdaptiveThresholdVal');
    if (thSlider && thVal) {
        thSlider.addEventListener('input', (e) => {
            thVal.textContent = parseFloat(e.target.value).toFixed(1);
        });
    }

    const winWidthSlider = document.getElementById('promov3WindowWidth');
    const winWidthVal = document.getElementById('promov3WindowWidthVal');
    if (winWidthSlider && winWidthVal) {
        winWidthSlider.addEventListener('input', (e) => {
            winWidthVal.textContent = e.target.value;
        });
    }

    const minLenSlider = document.getElementById('promov3MinSceneLen');
    const minLenVal = document.getElementById('promov3MinSceneLenVal');
    if (minLenSlider && minLenVal) {
        minLenSlider.addEventListener('input', (e) => {
            minLenVal.textContent = parseFloat(e.target.value).toFixed(1) + 's';
        });
    }

    const minClipDurSlider = document.getElementById('promov3MinClipDur');
    const minClipDurVal = document.getElementById('promov3MinClipDurVal');
    if (minClipDurSlider && minClipDurVal) {
        minClipDurSlider.addEventListener('input', (e) => {
            minClipDurVal.textContent = `≥ ${parseFloat(e.target.value).toFixed(1)}s`;
        });
    }

    const trimSlider = document.getElementById('promov3TrimFrames');
    const trimVal = document.getElementById('promov3TrimFramesVal');
    if (trimSlider && trimVal) {
        trimSlider.addEventListener('input', (e) => {
            trimVal.textContent = `${e.target.value} frames`;
        });
    }

    // 4. Setup Execution & Save Buttons for Step 1
    const btnReloadSess = document.getElementById('btnPromoV3ReloadSession');
    if (btnReloadSess) {
        btnReloadSess.addEventListener('click', () => {
            const vPath = state.promov3?.selectedVideo?.path || localStorage.getItem('promov3_active_video_path');
            if (vPath) checkAndLoadPromoV3SavedProgress(vPath, false);
            else showToast('Selecciona un vídeo para cargar su progreso guardado', 'info');
        });
    }

    const btnRun = document.getElementById('btnPromoV3RunStep1');
    if (btnRun) {
        btnRun.addEventListener('click', () => runPromoV3Step1());
    }

    const btnRerun = document.getElementById('btnPromoV3RerunStep1');
    if (btnRerun) {
        btnRerun.addEventListener('click', () => runPromoV3Step1());
    }

    const btnSaveStep1 = document.getElementById('btnPromoV3SaveStep1');
    if (btnSaveStep1) {
        btnSaveStep1.addEventListener('click', () => savePromoV3Step1Progress(false));
    }

    const btnSaveStep1Alt = document.getElementById('btnPromoV3SaveStep1Alt');
    if (btnSaveStep1Alt) {
        btnSaveStep1Alt.addEventListener('click', () => savePromoV3Step1Progress(false));
    }

    // 5. Setup Refresh & Reset Buttons
    const btnRefresh = document.getElementById('btnPromoV3RefreshFootage');
    if (btnRefresh) {
        btnRefresh.addEventListener('click', () => {
            loadPromoV3Footage();
            showToast('Librería de footage recargada', 'info');
        });
    }

    const btnReset = document.getElementById('btnPromoV3Reset');
    if (btnReset) {
        btnReset.addEventListener('click', () => resetPromoV3Notebook());
    }

    // 6. Setup Copy & Download JSON Buttons
    const btnCopyJson = document.getElementById('btnPromoV3CopyJson');
    if (btnCopyJson) {
        btnCopyJson.addEventListener('click', () => copyPromoV3Json());
    }

    const btnDownloadJson = document.getElementById('btnPromoV3DownloadJson');
    if (btnDownloadJson) {
        btnDownloadJson.addEventListener('click', () => downloadPromoV3Json());
    }

    // 7. Setup Output Sub-tab navigation
    const viewButtons = [
        { id: 'btnPromoV3ViewPreviews', view: 'previews' },
        { id: 'btnPromoV3ViewJson', view: 'json' },
        { id: 'btnPromoV3ViewTimeline', view: 'timeline' },
        { id: 'btnPromoV3ViewLogs', view: 'logs' },
    ];
    viewButtons.forEach(item => {
        const btn = document.getElementById(item.id);
        if (btn) {
            btn.addEventListener('click', () => switchPromoV3View(item.view));
        }
    });

    // 8. Auto-loop Toggle for video cards
    const autoLoopCheck = document.getElementById('promov3AutoLoopClips');
    if (autoLoopCheck) {
        autoLoopCheck.addEventListener('change', (e) => {
            state.promov3.autoLoop = e.target.checked;
            document.querySelectorAll('#promov3ShotsGrid video').forEach(v => {
                v.loop = e.target.checked;
            });
        });
    }

    // 9. Step 2 Setup: Batch Duration Slider, Execution & Save Buttons
    const batchDurSlider = document.getElementById('promov3BatchDuration');
    const batchDurVal = document.getElementById('promov3BatchDurationVal');
    if (batchDurSlider && batchDurVal) {
        batchDurSlider.addEventListener('input', (e) => {
            batchDurVal.textContent = `~${e.target.value}s`;
        });
    }

    const btnRunStep2 = document.getElementById('btnPromoV3RunStep2');
    if (btnRunStep2) {
        btnRunStep2.addEventListener('click', () => runPromoV3Step2());
    }

    const btnRerunStep2 = document.getElementById('btnPromoV3RerunStep2');
    if (btnRerunStep2) {
        btnRerunStep2.addEventListener('click', () => runPromoV3Step2());
    }

    const btnSaveStep2 = document.getElementById('btnPromoV3SaveStep2');
    if (btnSaveStep2) {
        btnSaveStep2.addEventListener('click', () => savePromoV3Step2Progress(false));
    }

    const btnSaveStep2Alt = document.getElementById('btnPromoV3SaveStep2Alt');
    if (btnSaveStep2Alt) {
        btnSaveStep2Alt.addEventListener('click', () => savePromoV3Step2Progress(false));
    }

    // 10. Step 2 View Tabs
    const step2ViewBtns = [
        { id: 'btnPromoV3Step2ViewTable', view: 'table' },
        { id: 'btnPromoV3Step2ViewJson', view: 'json' },
    ];
    step2ViewBtns.forEach(item => {
        const btn = document.getElementById(item.id);
        if (btn) {
            btn.addEventListener('click', () => switchPromoV3Step2View(item.view));
        }
    });

    // 11. Step 3 Setup: Hook Selection, Duration, Toolbar & Voice
    initPromoV3Step3Listeners();

    // 12. Step 4 Setup: Director IA & EDL Storyboard
    initPromoV3Step4Listeners();

    // 13. Step 5 Setup: Final Render, Visual Sliders & Live Mockup
    initPromoV3Step5Listeners();

    // Load available footage
    loadPromoV3Footage();
}

async function loadPromoV3Footage() {
    try {
        const res = await fetch('/api/promov3/footage');
        const data = await res.json();
        const select = document.getElementById('promov3FootageSelect');
        if (!select) return;

        state.promov3.footageFolders = data.folders || [];
        state.promov3.footageList = data.items || [];

        select.innerHTML = '<option value="">📁 Selecciona una carpeta o un clip...</option>';

        if (data.folders && data.folders.length > 0) {
            data.folders.forEach(folder => {
                const optgroup = document.createElement('optgroup');
                optgroup.label = folder.name;

                // 1. Folder option at top of optgroup
                const folderOpt = document.createElement('option');
                folderOpt.value = `folder:${folder.folder_id}`;
                folderOpt.textContent = `📁 [CARPETA COMPLETA] ${folder.name} (${folder.clip_count} vídeos — ${folder.total_size_mb} MB)`;
                folderOpt.style.fontWeight = 'bold';
                optgroup.appendChild(folderOpt);

                // 2. Individual clips inside optgroup
                folder.clips.forEach(clip => {
                    const clipOpt = document.createElement('option');
                    clipOpt.value = `file:${clip.path}`;
                    clipOpt.textContent = `  🎬 Clip: ${clip.filename} (${clip.size_mb} MB)`;
                    optgroup.appendChild(clipOpt);
                });

                select.appendChild(optgroup);
            });
        }

        if (state.promov3.selectedVideos && state.promov3.selectedVideos.length > 0) {
            renderPromoV3SelectedVideos();
        } else {
            select.value = "";
            renderPromoV3SelectedVideos();
        }
    } catch (e) {
        console.warn('Error loading Promo V3 footage folders:', e);
    }
}

async function ingestYoutubeVideo(urlInputId, gameNameInputId, btnId, isPromoV3 = false) {
    const urlInput = document.getElementById(urlInputId);
    const url = (urlInput?.value || '').trim();

    if (!url) {
        showToast('Por favor, introduce una URL válida de YouTube.', 'warning');
        return;
    }

    if (!url.toLowerCase().includes('youtube.com') && !url.toLowerCase().includes('youtu.be')) {
        showToast('La URL debe ser un enlace válido de YouTube (ej. https://www.youtube.com/watch?v=...)', 'warning');
        return;
    }

    const gameNameInput = document.getElementById(gameNameInputId);
    const gameName = (gameNameInput?.value || '').trim();

    const btn = document.getElementById(btnId);
    const origHtml = btn ? btn.innerHTML : 'Importar YouTube';

    if (btn) btn.disabled = true;
    if (btn) btn.innerHTML = '<span class="spinner" style="display:inline-block; width:12px; height:12px; border:2px solid #fff; border-top-color:transparent; border-radius:50%; animation:spin 0.8s linear infinite; margin-right:4px;"></span> Descargando...';

    showToast('Descargando vídeo de YouTube con yt-dlp... (Esto puede tardar unos segundos)', 'info');

    try {
        const res = await fetch('/api/ingest/youtube', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                url: url,
                game_name: gameName || null,
            }),
        });

        const data = await parseJsonResponse(res);
        if (data.status === 'ok') {
            const durStr = data.duration ? ` (${data.duration.toFixed(1)}s, ${data.size_mb} MB)` : ` (${data.size_mb} MB)`;
            showToast(`🎬 ¡Vídeo de YouTube descargado e ingestado con éxito!${durStr}`, 'success');
            if (urlInput) urlInput.value = '';

            if (isPromoV3) {
                await loadPromoV3Footage();
                if (data.saved_path) {
                    handlePromoV3FootageSelection(`file:${data.saved_path}`, true);
                }
            } else {
                if (data.clip) {
                    if (!state.promos) state.promos = {};
                    if (!state.promos.uploadedFiles) state.promos.uploadedFiles = [];
                    state.promos.uploadedFiles.push({
                        name: data.filename,
                        saved_path: data.saved_path,
                        url: data.url,
                        size_mb: data.size_mb,
                    });
                    if (typeof renderPromosFootageList === 'function') {
                        renderPromosFootageList();
                    }
                }
            }
        } else {
            showToast('Error descargando de YouTube: ' + (data.detail || 'Fallo desconocido'), 'error');
        }
    } catch (e) {
        showToast('Error al conectar con el servidor: ' + e.message, 'error');
    } finally {
        if (btn) btn.disabled = false;
        if (btn) btn.innerHTML = origHtml;
    }
}
window.ingestYoutubeVideo = ingestYoutubeVideo;

function handlePromoV3FootageSelection(val, autoRestore = true) {
    if (!val) {
        clearPromoV3Videos();
        return;
    }
    if (val.startsWith('folder:')) {
        const folderId = val.replace('folder:', '');
        const folder = (state.promov3.footageFolders || []).find(f => f.folder_id === folderId);
        if (folder && folder.clips && folder.clips.length > 0) {
            state.promov3.selectedVideos = [...folder.clips];
            state.promov3.selectedVideo = folder.clips[0];
            localStorage.setItem('promov3_active_video_path', folder.clips[0].path);
            renderPromoV3SelectedVideos();
            showToast(`Cargada la carpeta completa '${folder.name}' con ${folder.clips.length} vídeo(s)`, 'info');
            if (autoRestore) {
                checkAndLoadPromoV3SavedProgress(folder.clips[0].path, true);
            }
        }
    } else if (val.startsWith('file:') || val.includes('/') || val.includes('\\') || val.includes(':')) {
        const cleanPath = val.replace('file:', '');
        const item = (state.promov3.footageList || []).find(f => f.path === cleanPath || f.url === cleanPath) || {
            filename: cleanPath.split(/[\/\\]/).pop(),
            path: cleanPath,
            url: cleanPath,
            size_mb: 0
        };
        state.promov3.selectedVideos = [item];
        state.promov3.selectedVideo = item;
        localStorage.setItem('promov3_active_video_path', item.path);
        renderPromoV3SelectedVideos();
        showToast(`Seleccionado clip individual: ${item.filename}`, 'info');
        if (autoRestore) {
            checkAndLoadPromoV3SavedProgress(item.path, true);
        }
    }
}
window.handlePromoV3FootageSelection = handlePromoV3FootageSelection;

async function handlePromoV3FileUpload(filesInput) {
    if (!filesInput) return;
    const files = filesInput.length !== undefined ? Array.from(filesInput) : [filesInput];
    if (files.length === 0) return;

    showToast(`Subiendo ${files.length} archivo(s) de vídeo...`, 'info');

    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData,
            });
            const data = await res.json();
            if (data.status === 'ok') {
                const newItem = {
                    group: 'Subidos Recientes (Uploads)',
                    game_name: 'Uploads',
                    filename: file.name,
                    label: `Subido: ${file.name} (${(file.size / (1024 * 1024)).toFixed(1)} MB)`,
                    path: data.saved_path,
                    url: data.url,
                    size_mb: parseFloat((file.size / (1024 * 1024)).toFixed(1)),
                };

                state.promov3.footageList = [newItem, ...(state.promov3.footageList || [])];
                addPromoV3Video(newItem, false);
            } else {
                showToast(`Error al subir ${file.name}`, 'error');
            }
        } catch (e) {
            showToast(`Error al subir ${file.name}: ${e}`, 'error');
        }
    }

    await loadPromoV3Footage();
    renderPromoV3SelectedVideos();
    showToast(`¡${files.length} archivo(s) listos para análisis!`, 'success');
}

function addPromoV3VideoByPath(videoPathOrUrl, autoRestore = true) {
    if (!videoPathOrUrl) return;
    let item = (state.promov3.footageList || []).find(f => f.path === videoPathOrUrl || f.url === videoPathOrUrl);

    // Auto-select ALL videos in the same folder / group if item belongs to a group
    if (item && item.group && state.promov3.footageList) {
        const folderItems = state.promov3.footageList.filter(f => f.group === item.group);
        if (folderItems.length > 0) {
            folderItems.forEach((fItem, idx) => {
                addPromoV3Video(fItem, autoRestore && idx === 0);
            });
            showToast(`Añadida la carpeta '${item.group}' con ${folderItems.length} vídeo(s)`, 'info');
            return;
        }
    }

    if (!item) {
        item = {
            filename: videoPathOrUrl.split(/[\/\\]/).pop(),
            path: videoPathOrUrl,
            url: videoPathOrUrl,
            size_mb: 0,
        };
    }
    addPromoV3Video(item, autoRestore);
}

function addPromoV3Video(item, autoRestore = true) {
    if (!item || !item.path) return;
    if (!state.promov3.selectedVideos) state.promov3.selectedVideos = [];

    // Check if already in list
    const existing = state.promov3.selectedVideos.find(v => v.path === item.path);
    if (!existing) {
        state.promov3.selectedVideos.push(item);
    }
    state.promov3.selectedVideo = state.promov3.selectedVideos[0];
    localStorage.setItem('promov3_active_video_path', state.promov3.selectedVideos[0].path);

    renderPromoV3SelectedVideos();

    if (autoRestore && state.promov3.selectedVideos.length === 1) {
        checkAndLoadPromoV3SavedProgress(item.path, true);
    }
}

function removePromoV3Video(idx) {
    if (!state.promov3.selectedVideos) return;
    state.promov3.selectedVideos.splice(idx, 1);
    state.promov3.selectedVideo = state.promov3.selectedVideos.length > 0 ? state.promov3.selectedVideos[0] : null;
    if (state.promov3.selectedVideo) {
        localStorage.setItem('promov3_active_video_path', state.promov3.selectedVideo.path);
    } else {
        localStorage.removeItem('promov3_active_video_path');
    }
    renderPromoV3SelectedVideos();
}
window.removePromoV3Video = removePromoV3Video;

function clearPromoV3Videos() {
    state.promov3.selectedVideos = [];
    state.promov3.selectedVideo = null;
    localStorage.removeItem('promov3_active_video_path');
    renderPromoV3SelectedVideos();
}
window.clearPromoV3Videos = clearPromoV3Videos;

function renderPromoV3SelectedVideos() {
    const listEl = document.getElementById('promov3SelectedFilesList');
    const containerEl = document.getElementById('promov3SelectedFilesContainer');
    const countEl = document.getElementById('promov3SelectedFilesCount');

    const nameEl = document.getElementById('promov3VideoName');
    const resEl = document.getElementById('promov3SpecRes');
    const durEl = document.getElementById('promov3SpecDur');
    const fpsEl = document.getElementById('promov3SpecFps');
    const sizeEl = document.getElementById('promov3SpecSize');
    const aspectBadge = document.getElementById('promov3VideoAspectBadge');

    const videos = state.promov3.selectedVideos || [];

    if (videos.length === 0) {
        if (containerEl) containerEl.style.display = 'none';
        if (listEl) listEl.innerHTML = '';
        if (nameEl) nameEl.textContent = 'Ningún vídeo seleccionado';
        if (resEl) resEl.textContent = '-';
        if (durEl) durEl.textContent = '-';
        if (fpsEl) fpsEl.textContent = '-';
        if (sizeEl) sizeEl.textContent = '-';
        if (aspectBadge) aspectBadge.style.display = 'none';
        return;
    }

    if (containerEl) containerEl.style.display = 'block';
    if (countEl) countEl.textContent = videos.length;

    if (listEl) {
        listEl.innerHTML = videos.map((v, i) => `
            <div style="display: flex; align-items: center; justify-content: space-between; background: rgba(30, 41, 59, 0.7); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 6px; padding: 6px 10px; font-size: 12px; gap: 8px;">
                <div style="display: flex; align-items: center; gap: 8px; overflow: hidden; flex: 1;">
                    <span style="font-family: monospace; font-size: 11px; font-weight: 700; color: #818cf8; background: rgba(99, 102, 241, 0.2); padding: 1px 6px; border-radius: 4px;">#${i+1}</span>
                    <span style="font-weight: 600; color: var(--text-primary); text-overflow: ellipsis; overflow: hidden; white-space: nowrap; max-width: 170px;" title="${escapeHtml(v.filename)}">
                        ${escapeHtml(v.filename)}
                    </span>
                    ${v.size_mb ? `<span style="font-size: 11px; color: var(--text-muted); font-family: monospace;">(${escapeHtml(v.size_mb)} MB)</span>` : ''}
                </div>
                <button type="button" onclick="removePromoV3Video(${i})" style="background: none; border: none; color: #f87171; cursor: pointer; font-size: 14px; padding: 0 4px; line-height: 1;" title="Quitar este clip">✕</button>
            </div>
        `).join('');
    }

    if (videos.length > 1) {
        const totalSize = videos.reduce((acc, v) => acc + (parseFloat(v.size_mb) || 0), 0).toFixed(1);
        const grpName = videos[0].group || 'Lote de Vídeos';
        if (nameEl) nameEl.textContent = `📁 Carpeta: ${grpName} (${videos.length} vídeos)`;
        if (sizeEl) sizeEl.textContent = `${totalSize} MB total`;
        if (resEl) resEl.textContent = `Lote de ${videos.length} clips`;
        if (durEl) durEl.textContent = `Metraje combinado listo`;
        if (fpsEl) fpsEl.textContent = `Procesamiento en lote`;
        if (aspectBadge) aspectBadge.style.display = 'none';
    } else if (videos.length === 1) {
        const item = videos[0];
        if (nameEl) nameEl.textContent = item.filename;
        if (sizeEl) sizeEl.textContent = item.size_mb ? `${item.size_mb} MB` : 'Desconocido';
        if (resEl) resEl.textContent = item.width ? `${item.width} x ${item.height}` : 'Analizando...';
        if (durEl) durEl.textContent = item.duration ? `${item.duration.toFixed(1)}s` : '...';
        if (fpsEl) fpsEl.textContent = item.fps ? `${item.fps} FPS` : '...';

        if (item.url && (!item.duration || !item.width)) {
            try {
                const probe = document.createElement('video');
                probe.preload = 'metadata';
                probe.src = item.url;
                probe.onloadedmetadata = () => {
                    item.width = probe.videoWidth;
                    item.height = probe.videoHeight;
                    item.duration = probe.duration;
                    item.is_vertical = probe.videoHeight > probe.videoWidth;
                    if (resEl) resEl.textContent = `${item.width} x ${item.height}`;
                    if (durEl) durEl.textContent = `${item.duration.toFixed(1)}s (${Math.floor(item.duration / 60)}m ${Math.floor(item.duration % 60)}s)`;
                    if (fpsEl) fpsEl.textContent = '30 / 60 FPS (detectado)';
                    if (aspectBadge) {
                        aspectBadge.style.display = 'inline-block';
                        if (item.is_vertical) {
                            aspectBadge.textContent = '📱 9:16 Vertical';
                            aspectBadge.style.background = 'rgba(34, 197, 94, 0.15)';
                            aspectBadge.style.color = '#4ade80';
                            aspectBadge.style.border = '1px solid rgba(34, 197, 94, 0.3)';
                        } else {
                            aspectBadge.textContent = '🖥️ 16:9 Horizontal';
                            aspectBadge.style.background = 'rgba(59, 130, 246, 0.15)';
                            aspectBadge.style.color = '#60a5fa';
                            aspectBadge.style.border = '1px solid rgba(59, 130, 246, 0.3)';
                        }
                    }
                };
            } catch (e) {
                console.warn(e);
            }
        } else if (aspectBadge) {
            aspectBadge.style.display = 'inline-block';
            aspectBadge.textContent = item.is_vertical ? '📱 9:16 Vertical' : '🖥️ 16:9 Horizontal';
        }
    } else {
        const totalSize = videos.reduce((acc, v) => acc + (v.size_mb || 0), 0);
        if (nameEl) nameEl.textContent = `🎬 ${videos.length} clips seleccionados (Metraje Combinado)`;
        if (sizeEl) sizeEl.textContent = totalSize > 0 ? `${totalSize.toFixed(1)} MB total` : 'Calculando...';
        if (resEl) resEl.textContent = 'Multi-Resolución';
        if (durEl) durEl.textContent = 'Acumulada en análisis';
        if (fpsEl) fpsEl.textContent = '12 FPS (análisis proxy)';
        if (aspectBadge) {
            aspectBadge.style.display = 'inline-block';
            aspectBadge.textContent = `📦 ${videos.length} archivos`;
            aspectBadge.style.background = 'rgba(99, 102, 241, 0.2)';
            aspectBadge.style.color = '#818cf8';
            aspectBadge.style.border = '1px solid rgba(99, 102, 241, 0.4)';
        }
    }
}

function selectPromoV3Video(videoPathOrUrl, autoRestore = true) {
    addPromoV3VideoByPath(videoPathOrUrl, autoRestore);
}

async function runPromoV3Step1() {
    const videos = state.promov3.selectedVideos || [];
    if (videos.length === 0) {
        showToast('Por favor, selecciona o añade al menos un vídeo primero.', 'warning');
        return;
    }

    if (state.promov3.isRunning) {
        showToast('El Paso 1 ya está ejecutándose...', 'info');
        return;
    }

    const videoPaths = videos.map(v => v.path);
    const videoPath = videos[0].path;
    const proxyFps = parseInt(document.getElementById('promov3ProxyFps').value) || 12;
    const forceReproxy = document.getElementById('promov3ForceReproxy').checked;
    const adaptiveThreshold = parseFloat(document.getElementById('promov3AdaptiveThreshold').value) || 1.5;
    const minSceneLenSec = parseFloat(document.getElementById('promov3MinSceneLen').value) || 0.6;
    const windowWidth = parseInt(document.getElementById('promov3WindowWidth').value) || 8;
    const minClipDuration = parseFloat(document.getElementById('promov3MinClipDur')?.value) || 1.0;
    const trimFrames = parseInt(document.getElementById('promov3TrimFrames')?.value) || 5;
    const detectFades = true;

    state.promov3.isRunning = true;

    // UI Updates: Running State
    const cell = document.getElementById('cellPromoV3Step1');
    if (cell) {
        cell.classList.add('cell-running');
    }

    const btnRun = document.getElementById('btnPromoV3RunStep1');
    const btnRunText = document.getElementById('btnPromoV3RunStep1Text');
    if (btnRun) btnRun.disabled = true;
    if (btnRunText) btnRunText.textContent = `Ejecutando Paso 1 (${videos.length} vídeo${videos.length > 1 ? 's' : ''})...`;

    const statusBadge = document.getElementById('promov3Step1StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = 'Procesando...';
        statusBadge.style.background = 'rgba(217, 119, 87, 0.2)';
        statusBadge.style.color = '#d97757';
    }

    const progressBanner = document.getElementById('promov3ProgressBanner');
    const progressTitle = document.getElementById('promov3ProgressTitle');
    const progressPct = document.getElementById('promov3ProgressPct');
    const progressBar = document.getElementById('promov3ProgressBar');
    const progressLog = document.getElementById('promov3ProgressLog');
    const timerBadge = document.getElementById('promov3Step1TimerBadge');

    if (progressBanner) progressBanner.style.display = 'block';
    if (progressTitle) progressTitle.textContent = `Iniciando análisis de ${videos.length} vídeo(s)...`;
    if (progressPct) progressPct.textContent = '0%';
    if (progressBar) progressBar.style.width = '0%';
    if (progressLog) progressLog.textContent = 'Conectando con el motor de análisis...';
    if (timerBadge) {
        timerBadge.style.display = 'inline-block';
        timerBadge.textContent = '⏱️ 0.0s';
    }

    const logConsole = document.getElementById('promov3LogConsole');
    if (logConsole) {
        logConsole.innerHTML = `<div style="color: #60a5fa;">[${new Date().toLocaleTimeString()}] Iniciando Paso 1: Scene & Shot Detection (${videos.length} vídeo(s))...</div>`;
    }

    const startTime = Date.now();
    if (promov3TimerInterval) clearInterval(promov3TimerInterval);
    promov3TimerInterval = setInterval(() => {
        const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
        if (timerBadge) timerBadge.textContent = `⏱️ ${elapsed}s`;
    }, 100);

    try {
        const res = await fetch('/api/promov3/step1/detect', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                video_path: videoPath,
                video_paths: videoPaths,
                proxy_height: 720,
                proxy_fps: proxyFps,
                force_reproxy: forceReproxy,
                adaptive_threshold: adaptiveThreshold,
                min_scene_len_sec: minSceneLenSec,
                window_width: windowWidth,
                detect_fades: detectFades,
                generate_previews: true,
                min_clip_duration: minClipDuration,
                trim_frames: trimFrames,
                enable_deduplication: true,
            }),
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.detail || `HTTP ${res.status}`);
        }

        const data = await res.json();
        const jobId = data.job_id;
        state.promov3.currentJobId = jobId;

        // Connect SSE Stream (closing any previous stream or poller first)
        if (promov3EventSource) {
            promov3EventSource.close();
            promov3EventSource = null;
        }
        if (promov3Step1PollStop) {
            promov3Step1PollStop();
            promov3Step1PollStop = null;
        }

        const step1Source = new EventSource(`/api/jobs/${jobId}/stream`);
        promov3EventSource = step1Source;

        promov3EventSource.onmessage = (event) => {
            try {
                const payload = JSON.parse(event.data);
                const p = Math.min(Math.round(payload.progress || 0), 100);

                if (progressBar) progressBar.style.width = `${p}%`;
                if (progressPct) progressPct.textContent = `${p}%`;
                if (progressTitle) progressTitle.textContent = payload.message || 'Procesando...';
                if (progressLog) progressLog.textContent = payload.log || payload.message || '';

                if (logConsole && payload.log) {
                    const line = document.createElement('div');
                    line.style.marginTop = '2px';
                    line.textContent = `[${new Date().toLocaleTimeString()}] ${payload.log}`;
                    logConsole.appendChild(line);
                    logConsole.scrollTop = logConsole.scrollHeight;
                }

                if (payload.type === 'completed') {
                    if (promov3EventSource) {
                        promov3EventSource.close();
                        promov3EventSource = null;
                    }
                    if (promov3TimerInterval) {
                        clearInterval(promov3TimerInterval);
                        promov3TimerInterval = null;
                    }
                    state.promov3.isRunning = false;
                    state.promov3.step1Result = payload.result;

                    finishPromoV3Step1Success(payload.result);
                } else if (payload.type === 'error') {
                    if (promov3EventSource) {
                        promov3EventSource.close();
                        promov3EventSource = null;
                    }
                    if (promov3TimerInterval) {
                        clearInterval(promov3TimerInterval);
                        promov3TimerInterval = null;
                    }
                    state.promov3.isRunning = false;
                    finishPromoV3Step1Error(payload.error || payload.message);
                }
            } catch (err) {
                console.warn('Error parsing SSE event:', err);
            }
        };

        promov3EventSource.onerror = (err) => {
            console.warn('SSE connection error:', err);
        };
        guardJobEventSource(step1Source, () => {
            if (promov3EventSource !== step1Source) return;
            promov3EventSource = null;
            promov3Step1PollStop = pollJobUntilDone(jobId, msg => {
                if (msg.type === 'completed' || msg.type === 'error') promov3Step1PollStop = null;
                step1Source.onmessage({ data: JSON.stringify(msg) });
            });
        });

    } catch (e) {
        state.promov3.isRunning = false;
        if (promov3TimerInterval) clearInterval(promov3TimerInterval);
        finishPromoV3Step1Error(e.message || String(e));
    }
}

function finishPromoV3Step1Success(result, silent = false) {
    const cell = document.getElementById('cellPromoV3Step1');
    if (cell) cell.classList.remove('cell-running');

    const btnRun = document.getElementById('btnPromoV3RunStep1');
    const btnRunText = document.getElementById('btnPromoV3RunStep1Text');
    if (btnRun) btnRun.disabled = false;
    if (btnRunText) btnRunText.textContent = 'Re-ejecutar Paso 1 (Detectar Cortes)';

    const btnRerun = document.getElementById('btnPromoV3RerunStep1');
    if (btnRerun) btnRerun.style.display = 'inline-flex';

    const btnSave1 = document.getElementById('btnPromoV3SaveStep1');
    if (btnSave1) btnSave1.style.display = 'inline-flex';
    const btnSave1Alt = document.getElementById('btnPromoV3SaveStep1Alt');
    if (btnSave1Alt) btnSave1Alt.style.display = 'inline-flex';

    const statusBadge = document.getElementById('promov3Step1StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = `Completado: ${result.shots.length} planos`;
        statusBadge.style.background = 'rgba(52, 211, 153, 0.2)';
        statusBadge.style.color = '#34d399';
    }

    const progressBanner = document.getElementById('promov3ProgressBanner');
    if (progressBanner) {
        setTimeout(() => {
            progressBanner.style.display = 'none';
        }, 1500);
    }

    renderPromoV3Step1Output(result);
    state.promov3.step1Result = result;
    unlockPromoV3Step2(result);
    updatePromoV3SessionBanner();

    if (!silent) {
        savePromoV3Step1Progress(true);
        showToast(`¡Paso 1 completado! ${result.shots.length} planos detectados.`, 'success');
    }
}

function finishPromoV3Step1Error(errorMsg) {
    const cell = document.getElementById('cellPromoV3Step1');
    if (cell) cell.classList.remove('cell-running');

    const btnRun = document.getElementById('btnPromoV3RunStep1');
    const btnRunText = document.getElementById('btnPromoV3RunStep1Text');
    if (btnRun) btnRun.disabled = false;
    if (btnRunText) btnRunText.textContent = 'Reintentar Paso 1';

    const statusBadge = document.getElementById('promov3Step1StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = 'Error en detección';
        statusBadge.style.background = 'rgba(239, 68, 68, 0.2)';
        statusBadge.style.color = '#ef4444';
    }

    const progressTitle = document.getElementById('promov3ProgressTitle');
    const progressLog = document.getElementById('promov3ProgressLog');
    if (progressTitle) progressTitle.textContent = 'Error durante la ejecución';
    if (progressLog) progressLog.textContent = errorMsg;

    showToast(`Error en Paso 1: ${errorMsg}`, 'error');
}

function renderPromoV3Step1Output(result) {
    const outputSec = document.getElementById('promov3OutputSection');
    if (!outputSec) return;
    outputSec.style.display = 'block';

    const shots = result.shots || [];
    const stats = result.stats || {};
    const videoInfo = result.video_info || {};

    // 1. Populate Metrics
    const totalShotsEl = document.getElementById('promov3StatTotalShots');
    const avgDurEl = document.getElementById('promov3StatAvgDur');
    const minDurEl = document.getElementById('promov3StatMinDur');
    const maxDurEl = document.getElementById('promov3StatMaxDur');
    const timeEl = document.getElementById('promov3StatTime');

    const renderedCount = shots.filter(s => s.rendered !== false && s.preview_url).length;
    if (totalShotsEl) totalShotsEl.textContent = `${stats.total_shots || shots.length} (${renderedCount} ≥ 1s)`;
    if (avgDurEl) avgDurEl.textContent = `${stats.avg_duration || 0}s`;
    if (minDurEl) minDurEl.textContent = `${stats.min_duration || 0}s`;
    if (maxDurEl) maxDurEl.textContent = `${stats.max_duration || 0}s`;
    if (timeEl) timeEl.textContent = `${stats.detection_time_sec || 0}s`;

    // 2. Render Video Preview Grid (MUY IMPORTANTE - Solo clips renderizados >= 1s)
    renderPromoV3ShotCards(shots, videoInfo.is_vertical, result.detector_params);

    // 3. Render Formatted JSON
    const jsonCode = document.getElementById('promov3JsonCode');
    if (jsonCode) {
        jsonCode.textContent = JSON.stringify(shots, null, 2);
    }

    // 4. Render Timeline Bar
    renderPromoV3Timeline(shots, videoInfo.duration || stats.total_duration || 1);

    // Default view: Previews
    switchPromoV3View(state.promov3.activeView || 'previews');
}

function renderPromoV3ShotCards(shots, isVertical, detectorParams) {
    const grid = document.getElementById('promov3ShotsGrid');
    if (!grid) return;
    grid.innerHTML = '';

    if (!shots || shots.length === 0) {
        grid.innerHTML = '<div style="grid-column: 1/-1; text-align: center; padding: 30px; color: var(--text-muted);">No se detectó ningún corte.</div>';
        return;
    }

    // Filter to only shots that were rendered (duration >= min_duration, default 1.0s)
    const minDurFilter = detectorParams?.min_clip_duration || 1.0;
    const renderedShots = shots.filter(s => s.rendered !== false && s.preview_url);
    const skippedCount = shots.length - renderedShots.length;

    if (renderedShots.length === 0) {
        grid.innerHTML = `<div style="grid-column: 1/-1; text-align: center; padding: 30px; color: #f59e0b; background: rgba(245, 158, 11, 0.1); border-radius: 8px;">
            ⚠️ Ninguno de los ${shots.length} planos detectados supera la duración mínima de ${minDurFilter}s para renderizado.
        </div>`;
        return;
    }

    const MAX_DISPLAY_SHOTS = 30;
    const showAll = state.promov3.showAllShots === true;
    const shotsToDisplay = showAll ? renderedShots : renderedShots.slice(0, MAX_DISPLAY_SHOTS);

    const filterNotice = document.createElement('div');
    filterNotice.style.gridColumn = '1 / -1';
    filterNotice.style.padding = '10px 16px';
    filterNotice.style.background = 'rgba(52, 211, 153, 0.1)';
    filterNotice.style.border = '1px solid rgba(52, 211, 153, 0.25)';
    filterNotice.style.borderRadius = '8px';
    filterNotice.style.fontSize = '12px';
    filterNotice.style.color = '#34d399';
    filterNotice.style.display = 'flex';
    filterNotice.style.justifyContent = 'space-between';
    filterNotice.style.alignItems = 'center';
    filterNotice.style.flexWrap = 'wrap';
    filterNotice.style.gap = '8px';

    const blackShotsCount = shots.filter(s => s.is_black).length;
    const duplicateShotsCount = shots.filter(s => s.is_duplicate).length;
    const durSkippedCount = skippedCount - blackShotsCount - duplicateShotsCount;
    const details = [];
    if (durSkippedCount > 0) details.push(`${durSkippedCount} micro-cortes < ${minDurFilter}s`);
    if (blackShotsCount > 0) details.push(`🛡️ ${blackShotsCount} fundidos a negro descartados`);
    if (duplicateShotsCount > 0) details.push(`👥 ${duplicateShotsCount} clips duplicados descartados`);

    const countLabel = renderedShots.length > MAX_DISPLAY_SHOTS && !showAll
        ? `Mostrando los <strong>${shotsToDisplay.length}</strong> primeros planos generados (de ${renderedShots.length} totales)`
        : `Mostrando <strong>${renderedShots.length}</strong> clips renderizados`;

    filterNotice.innerHTML = `
        <div style="display: flex; align-items: center; gap: 8px;">
            <span>🎬 ${countLabel} (duración ≥ ${minDurFilter}s, recorte anti-leak: ${detectorParams?.trim_frames ?? 5} frames inicio/fin).</span>
            ${details.length ? `<span style="color: var(--text-muted); font-size: 11px;">(${details.join(', ')})</span>` : ''}
        </div>
        <div style="display: flex; align-items: center; gap: 10px;">
            ${renderedShots.length > MAX_DISPLAY_SHOTS ? `
                <button type="button" class="btn btn-tag" id="btnToggleAllPromoV3Shots" style="font-size: 11px; padding: 4px 12px; background: rgba(56, 189, 248, 0.2); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.4); border-radius: 4px; cursor: pointer; font-weight: 600;">
                    ${showAll ? '🔼 Mostrar solo 30' : `👁️ Ver todos (${renderedShots.length})`}
                </button>
            ` : ''}
        </div>
    `;
    grid.appendChild(filterNotice);

    const toggleBtn = filterNotice.querySelector('#btnToggleAllPromoV3Shots');
    if (toggleBtn) {
        toggleBtn.addEventListener('click', () => {
            state.promov3.showAllShots = !state.promov3.showAllShots;
            renderPromoV3ShotCards(shots, isVertical, detectorParams);
        });
    }

    const autoLoop = state.promov3.autoLoop !== false;
    const detDesc = detectorParams ? `${detectorParams.detector} (th=${detectorParams.adaptive_threshold})` : 'PySceneDetect';

    shotsToDisplay.forEach(shot => {
        const card = document.createElement('div');
        card.className = 'v3-shot-card card';
        card.id = `v3ShotCard_${shot.shot_id}`;

        const videoSrc = shot.preview_url || '';

        card.innerHTML = `
            <div class="v3-shot-header">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <span style="font-family: monospace; font-size: 13px; font-weight: 700; color: #d97757; background: rgba(217, 119, 87, 0.18); padding: 2px 7px; border-radius: 4px;">Shot #${escapeHtml(shot.shot_id)}</span>
                    ${shot.video_name ? `
                        <span class="badge-status" style="font-size: 10.5px; padding: 1px 6px; background: rgba(99, 102, 241, 0.15); color: #a5b4fc; border: 1px solid rgba(99, 102, 241, 0.3); border-radius: 4px; max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${escapeHtml(shot.video_name)}">
                            📁 ${escapeHtml(shot.video_name)}
                        </span>
                    ` : ''}
                </div>
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span class="badge-status" style="font-family: monospace; font-size: 11px; padding: 2px 7px; background: rgba(255, 255, 255, 0.07); color: var(--text-primary); border-radius: 4px;">
                        ⏱️ ${escapeHtml(shot.start_timecode)} → ${escapeHtml(shot.end_timecode)}
                    </span>
                    ${shot.trim_frames ? `
                        <span class="badge-status" style="font-size: 10px; padding: 1px 5px; background: rgba(167, 139, 250, 0.15); color: #c4b5fd; border: 1px solid rgba(167, 139, 250, 0.3); border-radius: 3px;" title="Corte de seguridad anti-leak: -${escapeHtml(shot.trim_frames)} frames al inicio y fin">
                            ✂️ -${escapeHtml(shot.trim_frames)}f
                        </span>
                    ` : ''}
                </div>
            </div>

            <div class="v3-shot-video-wrap ${isVertical ? 'vertical-video' : ''}">
                ${videoSrc ? `
                    <video class="v3-shot-video" controls preload="metadata" playsinline ${autoLoop ? 'loop' : ''} src="${escapeHtml(videoSrc)}"></video>
                ` : `
                    <div style="color: var(--text-muted); font-size: 12px; padding: 20px;">Clip no generado</div>
                `}
            </div>

            <div class="v3-shot-meta">
                <div style="display: flex; justify-content: space-between; align-items: center; font-size: 12px;">
                    <span style="color: var(--text-secondary);">Duración: <strong style="color: #4ade80; font-family: monospace;">${shot.duration.toFixed(2)}s</strong></span>
                    <span style="font-size: 11px; color: var(--text-muted); font-family: monospace;">${shot.start.toFixed(2)}s - ${shot.end.toFixed(2)}s${shot.raw_start !== undefined && shot.trim_frames ? ` (raw: ${shot.raw_start.toFixed(2)}-${shot.raw_end.toFixed(2)})` : ''}</span>
                </div>
                <div style="display: flex; justify-content: space-between; align-items: center; font-size: 11px; color: var(--text-muted); border-top: 1px solid rgba(255, 255, 255, 0.05); padding-top: 5px;">
                    <span>Método: ${escapeHtml(detDesc)}</span>
                    <button type="button" class="btn btn-tag" onclick="replayPromoV3Shot(${Number(shot.shot_id) || 0})" style="font-size: 11px; padding: 2px 6px;">
                        🔄 Repetir
                    </button>
                </div>
            </div>
        `;

        grid.appendChild(card);
    });
}

function replayPromoV3Shot(shotId) {
    const card = document.getElementById(`v3ShotCard_${shotId}`);
    if (!card) return;
    const video = card.querySelector('video');
    if (video) {
        video.currentTime = 0;
        video.play().catch(() => {});
    }
}

function renderPromoV3Timeline(shots, totalDuration) {
    const bar = document.getElementById('promov3TimelineBar');
    const durLabel = document.getElementById('promov3TimelineDuration');
    const endLabel = document.getElementById('promov3TimelineEndLabel');
    if (!bar) return;
    bar.innerHTML = '';

    if (!shots || shots.length === 0 || totalDuration <= 0) return;

    if (durLabel) durLabel.textContent = `Total: ${totalDuration.toFixed(2)}s`;
    if (endLabel) endLabel.textContent = formatPromoV3Timecode(totalDuration);

    const colors = [
        '#d97757', '#e28a6d', '#3b82f6', '#60a5fa', '#10b981', '#34d399', '#8b5cf6', '#a78bfa', '#f59e0b', '#fbbf24'
    ];

    shots.forEach((shot, idx) => {
        const block = document.createElement('div');
        block.className = 'v3-timeline-block';
        const pct = Math.max((shot.duration / totalDuration) * 100, 0.5);
        if (shot.rendered === false) {
            block.style.opacity = '0.35';
            block.style.filter = 'grayscale(0.6)';
            if (shot.is_duplicate) {
                block.style.background = '#475569';
            }
            const reason = shot.skip_reason || '< 1.0s';
            const icon = shot.is_duplicate ? '👥 ' : (shot.is_black ? '🛡️ ' : '');
            block.dataset.tooltip = `${icon}Shot #${shot.shot_id} (${shot.duration}s) [${reason}]`;
        } else {
            block.dataset.tooltip = `Shot #${shot.shot_id} (${shot.duration}s) [${shot.start_timecode} - ${shot.end_timecode}]`;
        }

        block.addEventListener('click', () => {
            if (shot.rendered === false) {
                const reason = shot.skip_reason || 'duración menor a 1.0s';
                showToast(`Plano #${shot.shot_id} (${shot.duration.toFixed(2)}s) descartado: ${reason}`, 'info');
                return;
            }
            switchPromoV3View('previews');
            const card = document.getElementById(`v3ShotCard_${shot.shot_id}`);
            if (card) {
                card.scrollIntoView({ behavior: 'smooth', block: 'center' });
                card.classList.add('highlighted');
                setTimeout(() => card.classList.remove('highlighted'), 2000);
                const vid = card.querySelector('video');
                if (vid) {
                    vid.currentTime = 0;
                    vid.play().catch(() => {});
                }
            }
        });

        bar.appendChild(block);
    });
}

function switchPromoV3View(viewName) {
    state.promov3.activeView = viewName;

    // Toggle button styles
    const viewButtons = [
        { id: 'btnPromoV3ViewPreviews', view: 'previews' },
        { id: 'btnPromoV3ViewJson', view: 'json' },
        { id: 'btnPromoV3ViewTimeline', view: 'timeline' },
        { id: 'btnPromoV3ViewLogs', view: 'logs' },
    ];
    viewButtons.forEach(item => {
        const btn = document.getElementById(item.id);
        if (btn) btn.classList.toggle('active', item.view === viewName);
    });

    // Toggle Panes
    const panes = {
        previews: document.getElementById('promov3ViewPanePreviews'),
        json: document.getElementById('promov3ViewPaneJson'),
        timeline: document.getElementById('promov3ViewPaneTimeline'),
        logs: document.getElementById('promov3ViewPaneLogs'),
    };

    Object.keys(panes).forEach(k => {
        if (panes[k]) {
            panes[k].style.display = (k === viewName) ? 'block' : 'none';
        }
    });
}

function copyPromoV3Json() {
    if (!state.promov3.step1Result || !state.promov3.step1Result.shots) {
        showToast('No hay datos JSON que copiar', 'warning');
        return;
    }
    const jsonStr = JSON.stringify(state.promov3.step1Result.shots, null, 2);
    navigator.clipboard.writeText(jsonStr).then(() => {
        showToast('¡JSON de shots copiado al portapapeles!', 'success');
    }).catch(e => {
        showToast(`Error al copiar: ${e}`, 'error');
    });
}

function downloadPromoV3Json() {
    if (!state.promov3.step1Result || !state.promov3.step1Result.shots) {
        showToast('No hay datos JSON que descargar', 'warning');
        return;
    }
    const jsonStr = JSON.stringify(state.promov3.step1Result, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const name = state.promov3.selectedVideo ? state.promov3.selectedVideo.filename.replace(/\.[^/.]+$/, '') : 'promo_v3';
    a.download = `${name}_v3_step1_shots.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('Descarga iniciada para el archivo JSON', 'info');
}

async function resetPromoV3Notebook() {
    if (promov3EventSource) {
        promov3EventSource.close();
        promov3EventSource = null;
    }
    if (promov3TimerInterval) {
        clearInterval(promov3TimerInterval);
        promov3TimerInterval = null;
    }

    // Call backend to purge saved session cache files from disk
    try {
        const activeVideoPath = state.promov3.selectedVideo ? state.promov3.selectedVideo.path : localStorage.getItem('promov3_active_video_path');
        const activeSessionId = state.promov3.sessionId || localStorage.getItem('promov3_session_id');
        const videoPaths = (state.promov3.selectedVideos || []).map(v => v.path);

        await fetch('/api/promov3/reset', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                session_id: activeSessionId,
                video_path: activeVideoPath,
                video_paths: videoPaths.length > 0 ? videoPaths : null,
                clear_all: false
            })
        });
    } catch (e) {
        console.warn('Error purging session cache on backend:', e);
    }

    // Reset all frontend state memory
    state.promov3.step1Result = null;
    state.promov3.step2Result = null;
    state.promov3.step3Result = null;
    state.promov3.step4Result = null;
    state.promov3.step5Result = null;
    state.promov3.selectedVideos = [];
    state.promov3.selectedVideo = null;
    state.promov3.sessionId = null;
    state.promov3.isRunning = false;

    // Clear localStorage keys
    localStorage.removeItem('promov3_active_video_path');
    localStorage.removeItem('promov3_session_id');

    // Hide output section and progress banner
    const outputSec = document.getElementById('promov3OutputSection');
    if (outputSec) outputSec.style.display = 'none';

    const banner = document.getElementById('promov3ProgressBanner');
    if (banner) banner.style.display = 'none';

    // Reset selected videos list UI
    renderPromoV3SelectedVideos();

    // Reset Step 1 cell UI
    const cell1 = document.getElementById('cellPromoV3Step1');
    if (cell1) cell1.classList.remove('cell-running');

    const statusBadge = document.getElementById('promov3Step1StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = 'Listo para ejecutar';
        statusBadge.style.background = 'rgba(255, 255, 255, 0.05)';
        statusBadge.style.color = 'var(--text-secondary)';
    }

    const timerBadge = document.getElementById('promov3Step1TimerBadge');
    if (timerBadge) timerBadge.style.display = 'none';

    const btnRunText = document.getElementById('btnPromoV3RunStep1Text');
    if (btnRunText) btnRunText.textContent = 'Ejecutar Paso 1 (Detectar Planos)';

    const btnRerun = document.getElementById('btnPromoV3RerunStep1');
    if (btnRerun) btnRerun.style.display = 'none';

    // Lock cells 2, 3, 4, 5
    ['cellPromoV3Step2', 'cellPromoV3Step3', 'cellPromoV3Step4', 'cellPromoV3Step5'].forEach(id => {
        const c = document.getElementById(id);
        if (c) {
            c.classList.add('cell-locked', 'cell-disabled');
            c.style.opacity = '0.55';
        }
    });

    // Reset step 2 UI containers
    const step2ShotsGrid = document.getElementById('promov3Step2ShotsGrid');
    if (step2ShotsGrid) step2ShotsGrid.innerHTML = '';
    const step2Summary = document.getElementById('promov3Step2SummaryBox');
    if (step2Summary) step2Summary.style.display = 'none';

    // Reset step 3 script text
    const scriptBox = document.getElementById('promov3ScriptText');
    if (scriptBox) scriptBox.value = '';

    // Reset step 4 EDL timeline
    const edlTimeline = document.getElementById('promov3EdlTimeline');
    if (edlTimeline) edlTimeline.innerHTML = '';

    showToast('Notebook y archivos guardados eliminados correctamente', 'info');
}

function formatPromoV3Timecode(seconds) {
    const s = Math.max(0, parseFloat(seconds) || 0);
    const m = Math.floor(s / 60);
    const sec = (s % 60).toFixed(1);
    return `${m.toString().padStart(2, '0')}:${sec.padStart(4, '0')}`;
}

// Global exposure for Promo V3
window.initPromoV3 = initPromoV3;
window.runPromoV3Step1 = runPromoV3Step1;
window.runPromoV3Step2 = runPromoV3Step2;
window.unlockPromoV3Step2 = unlockPromoV3Step2;
window.replayPromoV3Shot = replayPromoV3Shot;
window.switchPromoV3View = switchPromoV3View;
window.switchPromoV3Step2View = switchPromoV3Step2View;
window.togglePlayPromoV3Mini = togglePlayPromoV3Mini;
window.copyPromoV3Json = copyPromoV3Json;
window.downloadPromoV3Json = downloadPromoV3Json;
window.resetPromoV3Notebook = resetPromoV3Notebook;


// =============================================================================
// PROMO V3 — PASO 2: Multimodal Scene Understanding & Semantic Tagging (9:16)
// =============================================================================

let promov3Step2EventSource = null;
let promov3Step2TimerInterval = null;

function unlockPromoV3Step2(step1Result) {
    if (!step1Result) return;
    state.promov3.step1Result = step1Result;

    const cell2 = document.getElementById('cellPromoV3Step2');
    if (cell2) {
        cell2.classList.remove('cell-disabled', 'cell-locked');
        cell2.style.opacity = '1';
    }

    const shots = step1Result.shots || [];
    const rendered = shots.filter(s => s.rendered);
    const totalUsefulSec = rendered.reduce((acc, s) => acc + (s.duration || 0), 0);

    const statusBadge = document.getElementById('promov3Step2StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = `Listo para ejecutar (${rendered.length} clips)`;
        statusBadge.style.background = 'rgba(167, 139, 250, 0.2)';
        statusBadge.style.color = '#c4b5fd';
    }

    const inputNotice = document.getElementById('promov3Step2InputNotice');
    if (inputNotice) {
        inputNotice.innerHTML = `📥 Recibiendo <strong>${rendered.length} clips supervivientes</strong> del Paso 1 (duración acumulada útil: <strong>${totalUsefulSec.toFixed(1)}s</strong>) listos para transformar a vertical 9:16 y evaluar con Gemini.`;
    }

    const btnRun2 = document.getElementById('btnPromoV3RunStep2');
    if (btnRun2) {
        btnRun2.disabled = false;
        const btnText = document.getElementById('btnPromoV3RunStep2Text');
        if (btnText) btnText.textContent = `Ejecutar Paso 2 (Transformar ${rendered.length} clips a 9:16 y Analizar)`;
    }
}

async function runPromoV3Step2() {
    const videoPath = state.promov3.selectedVideo ? state.promov3.selectedVideo.path : document.getElementById('promov3FootageSelect')?.value;
    if (!videoPath) {
        showToast('Por favor, selecciona un vídeo antes de ejecutar', 'warning');
        return;
    }

    const sessionId = state.promov3.step1Result ? state.promov3.step1Result.session_id : null;
    const batchTargetDur = parseFloat(document.getElementById('promov3BatchDuration')?.value) || 60.0;
    const forceReanalyze = document.getElementById('promov3ForceReanalyze')?.checked || false;
    const enableEarlyStopping = document.getElementById('promov3EarlyStopping') ? document.getElementById('promov3EarlyStopping').checked : true;
    const stripSplash = document.getElementById('promov3StripSplash') ? document.getElementById('promov3StripSplash').checked : true;

    state.promov3.isStep2Running = true;

    // UI Updates: Running State
    const cell2 = document.getElementById('cellPromoV3Step2');
    if (cell2) cell2.classList.add('cell-running');

    const btnRun = document.getElementById('btnPromoV3RunStep2');
    const btnRunText = document.getElementById('btnPromoV3RunStep2Text');
    if (btnRun) btnRun.disabled = true;
    if (btnRunText) btnRunText.textContent = 'Ejecutando Paso 2 (Transformando a 9:16 y consultando Gemini)...';

    const statusBadge = document.getElementById('promov3Step2StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = 'Procesando con Gemini...';
        statusBadge.style.background = 'rgba(124, 58, 237, 0.25)';
        statusBadge.style.color = '#c4b5fd';
    }

    const progressBanner = document.getElementById('promov3Step2ProgressBanner');
    const progressTitle = document.getElementById('promov3Step2ProgressTitle');
    const progressPct = document.getElementById('promov3Step2ProgressPct');
    const progressBar = document.getElementById('promov3Step2ProgressBar');
    const progressLog = document.getElementById('promov3Step2ProgressLog');
    const timerBadge = document.getElementById('promov3Step2TimerBadge');

    if (progressBanner) progressBanner.style.display = 'block';
    if (progressTitle) progressTitle.textContent = 'Iniciando conversión vertical 9:16...';
    if (progressPct) progressPct.textContent = '0%';
    if (progressBar) progressBar.style.width = '0%';
    if (progressLog) progressLog.textContent = 'Conectando con el motor de análisis multimodal...';
    if (timerBadge) {
        timerBadge.style.display = 'inline-block';
        timerBadge.textContent = '⏱️ 0.0s';
    }

    const startTime = Date.now();
    if (promov3Step2TimerInterval) clearInterval(promov3Step2TimerInterval);
    promov3Step2TimerInterval = setInterval(() => {
        const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
        if (timerBadge) timerBadge.textContent = `⏱️ ${elapsed}s`;
    }, 100);

    try {
        const videoPaths = state.promov3.selectedVideos && state.promov3.selectedVideos.length > 0
            ? state.promov3.selectedVideos.map(v => v.path)
            : (videoPath ? [videoPath] : []);

        const res = await fetch('/api/promov3/step2/analyze', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                video_path: videoPaths[0] || videoPath,
                video_paths: videoPaths,
                session_id: sessionId,
                batch_target_duration: batchTargetDur,
                force_reanalyze: forceReanalyze,
                enable_early_stopping: enableEarlyStopping,
                strip_splash: stripSplash,
            }),
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.detail || `HTTP ${res.status}`);
        }

        const data = await res.json();
        const jobId = data.job_id;

        // Connect SSE Stream for Step 2 (closing any previous stream or poller first)
        if (promov3Step2EventSource) {
            promov3Step2EventSource.close();
            promov3Step2EventSource = null;
        }
        if (promov3Step2PollStop) {
            promov3Step2PollStop();
            promov3Step2PollStop = null;
        }

        const step2Source = new EventSource(`/api/jobs/${jobId}/stream`);
        promov3Step2EventSource = step2Source;

        promov3Step2EventSource.onmessage = (event) => {
            try {
                const msg = JSON.parse(event.data);

                if (msg.type === 'progress') {
                    if (progressPct) progressPct.textContent = `${Math.round(msg.progress)}%`;
                    if (progressBar) progressBar.style.width = `${msg.progress}%`;
                    if (progressTitle && msg.message) progressTitle.textContent = msg.message;
                    if (progressLog && msg.log) progressLog.textContent = msg.log;
                } else if (msg.type === 'completed') {
                    if (promov3Step2EventSource) promov3Step2EventSource.close();
                    promov3Step2EventSource = null;
                    state.promov3.isStep2Running = false;
                    if (promov3Step2TimerInterval) clearInterval(promov3Step2TimerInterval);
                    finishPromoV3Step2Success(msg.result);
                } else if (msg.type === 'error') {
                    if (promov3Step2EventSource) promov3Step2EventSource.close();
                    promov3Step2EventSource = null;
                    state.promov3.isStep2Running = false;
                    if (promov3Step2TimerInterval) clearInterval(promov3Step2TimerInterval);
                    finishPromoV3Step2Error(msg.error || 'Error desconocido');
                }
            } catch (err) {
                console.warn('Error parsing SSE event in Step 2:', err);
            }
        };

        promov3Step2EventSource.onerror = (err) => {
            console.warn('SSE connection error in Step 2:', err);
        };
        guardJobEventSource(step2Source, () => {
            if (promov3Step2EventSource !== step2Source) return;
            promov3Step2EventSource = null;
            promov3Step2PollStop = pollJobUntilDone(jobId, msg => {
                if (msg.type === 'completed' || msg.type === 'error') promov3Step2PollStop = null;
                step2Source.onmessage({ data: JSON.stringify(msg) });
            });
        });

    } catch (e) {
        state.promov3.isStep2Running = false;
        if (promov3Step2TimerInterval) clearInterval(promov3Step2TimerInterval);
        finishPromoV3Step2Error(e.message || String(e));
    }
}

function finishPromoV3Step2Success(result, silent = false) {
    const cell2 = document.getElementById('cellPromoV3Step2');
    if (cell2) cell2.classList.remove('cell-running');

    const btnRun = document.getElementById('btnPromoV3RunStep2');
    const btnRunText = document.getElementById('btnPromoV3RunStep2Text');
    if (btnRun) btnRun.disabled = false;
    if (btnRunText) btnRunText.textContent = 'Re-ejecutar Paso 2 (Re-evaluar clips 9:16)';

    const btnRerun = document.getElementById('btnPromoV3RerunStep2');
    if (btnRerun) btnRerun.style.display = 'inline-flex';

    const btnSave2 = document.getElementById('btnPromoV3SaveStep2');
    if (btnSave2) btnSave2.style.display = 'inline-flex';
    const btnSave2Alt = document.getElementById('btnPromoV3SaveStep2Alt');
    if (btnSave2Alt) btnSave2Alt.style.display = 'inline-flex';

    const statusBadge = document.getElementById('promov3Step2StatusBadge');
    if (statusBadge) {
        const stats = result.batch_stats || {};
        const count = stats.clips_evaluated || (result.shots || []).filter(s => s.format_score !== undefined).length;
        if (stats.early_stopped) {
            statusBadge.textContent = `Optimizado: ${count} clips (Lote 1)`;
            statusBadge.style.background = 'rgba(52, 211, 153, 0.2)';
            statusBadge.style.color = '#34d399';
        } else {
            statusBadge.textContent = `Completado: ${count} clips evaluados`;
            statusBadge.style.background = 'rgba(52, 211, 153, 0.2)';
            statusBadge.style.color = '#34d399';
        }
    }

    const progressBanner = document.getElementById('promov3Step2ProgressBanner');
    if (progressBanner) {
        setTimeout(() => {
            progressBanner.style.display = 'none';
        }, 1200);
    }

    state.promov3.step2Result = result;
    renderPromoV3Step2Table(result);
    unlockPromoV3Step3(result);
    updatePromoV3SessionBanner();

    if (!silent) {
        savePromoV3Step2Progress(true);
        const stats = result.batch_stats || {};
        const v = stats.sufficiency_verdict || {};
        if (stats.early_stopped) {
            const evalLabel = v.model_evaluator ? ` (${v.model_evaluator})` : '';
            const bNum = stats.batches_evaluated || 1;
            showToast(`⚡ ¡Paso 2 completado con optimización! Suficiencia en lote ${bNum}/${stats.total_batches || bNum}${evalLabel}: ${stats.clips_evaluated} clips, ahorrados ${stats.batches_saved} lotes.`, 'success');
        } else {
            showToast(`¡Paso 2 completado! ${stats.clips_evaluated || result.shots.length} clips evaluados en 9:16.`, 'success');
        }
    }
}

function finishPromoV3Step2Error(errorMsg) {
    const cell2 = document.getElementById('cellPromoV3Step2');
    if (cell2) cell2.classList.remove('cell-running');

    const btnRun = document.getElementById('btnPromoV3RunStep2');
    const btnRunText = document.getElementById('btnPromoV3RunStep2Text');
    if (btnRun) btnRun.disabled = false;
    if (btnRunText) btnRunText.textContent = 'Reintentar Paso 2';

    const statusBadge = document.getElementById('promov3Step2StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = 'Error en evaluación';
        statusBadge.style.background = 'rgba(239, 68, 68, 0.2)';
        statusBadge.style.color = '#ef4444';
    }

    const progressTitle = document.getElementById('promov3Step2ProgressTitle');
    const progressLog = document.getElementById('promov3Step2ProgressLog');
    if (progressTitle) progressTitle.textContent = 'Error durante la evaluación de Gemini';
    if (progressLog) progressLog.textContent = errorMsg;

    showToast(`Error en Paso 2: ${errorMsg}`, 'error');
}

function renderPromoV3Step2Table(result) {
    const outputSec = document.getElementById('promov3Step2OutputSection');
    if (!outputSec) return;
    outputSec.style.display = 'block';

    const stats = result.batch_stats || {};
    // Only display shots that have evaluations
    const shots = (result.shots || []).filter(s => s.rendered && s.format_score !== undefined);

    // 0. Render Early Stopping Alert Notice if triggered
    const earlyNotice = document.getElementById('promov3Step2EarlyStopNotice');
    if (earlyNotice) {
        if (stats.early_stopped) {
            earlyNotice.style.display = 'block';
            const v = stats.sufficiency_verdict || {};
            const bNum = stats.batches_evaluated || 1;
            earlyNotice.innerHTML = `
                <div style="display: flex; align-items: flex-start; gap: 12px;">
                    <div style="font-size: 22px; line-height: 1;">⚡</div>
                    <div style="flex: 1;">
                        <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 6px;">
                            <span style="font-size: 13.5px; font-weight: 700; color: #34d399;">
                                ¡Optimización de Tiempo Exitosa! Suficiencia alcanzada tras Lote ${escapeHtml(bNum)} (${escapeHtml(stats.clips_evaluated)} clips acumulados)
                            </span>
                            <span style="font-family: monospace; font-size: 11px; padding: 2px 8px; border-radius: 4px; background: rgba(52, 211, 153, 0.2); color: #34d399; font-weight: 700;">
                                Ahorrados ${escapeHtml(stats.batches_saved || 0)} de ${escapeHtml(stats.total_batches)} lotes
                            </span>
                        </div>
                        <div style="font-size: 12px; color: var(--text-secondary); margin-top: 4px; line-height: 1.45;">
                            ${escapeHtml(v.verdict_reason || 'El Director IA ha determinado que este metraje acumulado contiene gancho visual, metraje útil y variedad suficiente para producir el vídeo sin gastar más tiempo.')}
                        </div>
                        <div style="display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; font-size: 11px;">
                            ${v.model_evaluator ? `
                                <span style="background: rgba(245, 158, 11, 0.15); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.3); padding: 2px 7px; border-radius: 4px; font-weight: 600;">
                                    🧠 Evaluador: ${escapeHtml(v.model_evaluator)}
                                </span>
                            ` : ''}
                            ${v.hook_clip_id ? `
                                <span style="background: rgba(239, 68, 68, 0.15); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.3); padding: 2px 7px; border-radius: 4px; font-weight: 600;">
                                    🔥 Hook Recomendado: Clip #${escapeHtml(v.hook_clip_id)}
                                </span>
                            ` : ''}
                            ${v.variety_score ? `
                                <span style="background: rgba(56, 189, 248, 0.15); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3); padding: 2px 7px; border-radius: 4px; font-weight: 600;">
                                    🎮 Variedad Mecánicas: ${escapeHtml(v.variety_score)}/100
                                </span>
                            ` : ''}
                            ${v.usable_duration_seconds ? `
                                <span style="background: rgba(167, 139, 250, 0.15); color: #c4b5fd; border: 1px solid rgba(167, 139, 250, 0.3); padding: 2px 7px; border-radius: 4px; font-weight: 600;">
                                    ⏱️ Metraje Útil: ${escapeHtml(v.usable_duration_seconds)}s
                                </span>
                            ` : ''}
                            ${v.actions_detected && v.actions_detected.length ? `
                                <span style="color: var(--text-muted); padding: 2px 0;">
                                    Acciones: <em>${escapeHtml(v.actions_detected.join(', '))}</em>
                                </span>
                            ` : ''}
                        </div>
                    </div>
                </div>
            `;
        } else {
            earlyNotice.style.display = 'none';
        }
    }

    // 0b. Render Splash Filter Alert Notice if any shots were stripped
    const splashNotice = document.getElementById('promov3Step2SplashNotice');
    if (splashNotice) {
        if (stats.splash_shots_discarded > 0) {
            splashNotice.style.display = 'block';
            splashNotice.innerHTML = `
                <div style="display: flex; align-items: center; gap: 10px;">
                    <span style="font-size: 18px;">🛡️</span>
                    <div>
                        <strong style="color: #38bdf8;">Filtro Splash Final Activo:</strong>
                        <span style="color: var(--text-secondary); margin-left: 4px;">
                            Se han detectado y descartado <strong>${stats.splash_shots_discarded} plano(s)</strong> de títulos, logos, wishlist de Steam o fecha final del tráiler para evitar que se cuelen en el montaje.
                        </span>
                    </div>
                </div>
            `;
        } else {
            splashNotice.style.display = 'none';
        }
    }

    // 1. Update Metrics
    const metricEval = document.getElementById('promov3Step2MetricEvaluated');
    const metricBatches = document.getElementById('promov3Step2MetricBatches');
    const metricModel = document.getElementById('promov3Step2MetricModel');

    if (metricEval) metricEval.textContent = stats.clips_evaluated || shots.length;
    if (metricBatches) {
        if (stats.early_stopped) {
            metricBatches.innerHTML = `${stats.batches_evaluated || 1} <span style="font-size: 11px; color: #34d399; font-weight: 600;">(⚡ ${stats.batches_saved || 0} ahorrados)</span>`;
        } else {
            metricBatches.textContent = stats.total_batches || 1;
        }
    }
    if (metricModel) metricModel.textContent = (stats.models_used || []).join(', ') || 'Gemini Flash';

    // 2. Populate Table
    const tbody = document.getElementById('promov3Step2TableBody');
    if (!tbody) return;
    tbody.innerHTML = '';

    shots.forEach(shot => {
        const tr = document.createElement('tr');
        const isSplash = Boolean(shot.is_splash);

        if (isSplash) {
            tr.style.opacity = '0.68';
            tr.style.background = 'rgba(239, 68, 68, 0.04)';
        }

        // Format Score styling
        const fScore = Number.isFinite(shot.format_score) ? shot.format_score : 50;
        const fClass = fScore >= 75 ? 'score-badge-high' : (fScore >= 45 ? 'score-badge-mid' : 'score-badge-low');
        const fColor = fScore >= 75 ? '#34d399' : (fScore >= 45 ? '#fbbf24' : '#f87171');

        // Viral Score styling
        const vScore = Number.isFinite(shot.viral_score) ? shot.viral_score : 50;
        const vClass = vScore >= 75 ? 'score-badge-high' : (vScore >= 45 ? 'score-badge-mid' : 'score-badge-low');
        const vColor = vScore >= 75 ? '#a78bfa' : (vScore >= 45 ? '#38bdf8' : '#94a3b8');

        // Descriptive Score styling
        const dScore = Number.isFinite(shot.descriptive_score) ? shot.descriptive_score : 50;
        const dClass = dScore >= 75 ? 'score-badge-high' : (dScore >= 45 ? 'score-badge-mid' : 'score-badge-low');
        const dColor = dScore >= 75 ? '#38bdf8' : (dScore >= 45 ? '#fbbf24' : '#94a3b8');

        // Role badge styling
        const role = shot.suggested_role || 'gameplay';
        const roleColors = {
            hook: { bg: 'rgba(239, 68, 68, 0.15)', text: '#f87171', label: '🔥 Hook' },
            climax: { bg: 'rgba(245, 158, 11, 0.15)', text: '#fbbf24', label: '⚡ Climax' },
            gameplay: { bg: 'rgba(56, 189, 248, 0.15)', text: '#38bdf8', label: '🎮 Gameplay' },
            mechanic: { bg: 'rgba(167, 139, 250, 0.15)', text: '#c4b5fd', label: '⚙️ Mecánica' },
            discard: { bg: 'rgba(255, 255, 255, 0.07)', text: '#94a3b8', label: '🗑️ Descartar' },
        };
        let rConf = roleColors[role] || roleColors.gameplay;
        if (isSplash) {
            rConf = { bg: 'rgba(239, 68, 68, 0.2)', text: '#fca5a5', label: '🏷️ Splash (Descartado)' };
        }

        const videoUrl = shot.preview_9_16_url || shot.preview_url || '';

        tr.innerHTML = `
            <td>
                <div style="font-family: monospace; font-size: 13px; font-weight: 700; color: #a78bfa;">Shot #${escapeHtml(shot.shot_id)}</div>
                ${shot.video_name ? `
                    <div style="font-size: 10px; color: #a5b4fc; background: rgba(99, 102, 241, 0.15); border: 1px solid rgba(99, 102, 241, 0.3); border-radius: 3px; padding: 1px 5px; margin-top: 3px; max-width: 125px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${escapeHtml(shot.video_name)}">
                        📁 ${escapeHtml(shot.video_name)}
                    </div>
                ` : ''}
                <div style="font-size: 11px; color: var(--text-muted); font-family: monospace; margin-top: 2px;">
                    ${shot.start.toFixed(2)}s - ${shot.end.toFixed(2)}s
                </div>
                <div style="font-size: 11px; color: #4ade80; font-family: monospace; font-weight: 600;">
                    ${shot.duration.toFixed(1)}s
                </div>
                <div style="margin-top: 4px;">
                    <span style="font-size: 10px; padding: 2px 6px; border-radius: 4px; background: ${rConf.bg}; color: ${rConf.text}; font-weight: 600; display: inline-block;">
                        ${escapeHtml(rConf.label)}
                    </span>
                </div>
            </td>
            <td>
                <div class="v3-mini-video-wrap" id="v3MiniWrap_${escapeHtml(shot.shot_id)}" onclick="togglePlayPromoV3Mini(this)">
                    <video class="v3-mini-video" loop playsinline preload="metadata" src="${escapeHtml(videoUrl)}"></video>
                    <div class="v3-mini-video-play-btn">▶</div>
                </div>
            </td>
            <td>
                <div style="font-size: 13px; font-weight: 500; color: var(--text-primary); line-height: 1.45;">
                    ${escapeHtml(shot.description || 'Sin descripción')}
                </div>
                ${isSplash ? `
                    <div style="font-size: 11px; color: #f87171; margin-top: 5px; display: flex; align-items: center; gap: 4px;">
                        <span>🛡️ Splash final del tráiler:</span>
                        <span style="color: #fca5a5;">Tarjetas de logo, fecha de lanzamiento o wishlist descartadas.</span>
                    </div>
                ` : (shot.format_reason ? `
                    <div style="font-size: 11px; color: var(--text-muted); margin-top: 5px; display: flex; align-items: center; gap: 4px;">
                        <span>📱 Encuadre 9:16:</span>
                        <span style="color: var(--text-secondary);">${escapeHtml(shot.format_reason)}</span>
                    </div>
                ` : '')}
            </td>
            <td>
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span class="badge-status ${fClass}" style="font-family: monospace; font-size: 12px; font-weight: 700; padding: 2px 8px;">
                        ${fScore}/100
                    </span>
                </div>
                <div class="v3-score-meter" title="Format Score: ${fScore}/100">
                    <div class="v3-score-meter-fill" style="width: ${fScore}%; background: ${fColor};"></div>
                </div>
            </td>
            <td>
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span class="badge-status ${vClass}" style="font-family: monospace; font-size: 12px; font-weight: 700; padding: 2px 8px;">
                        🔥 ${vScore}/100
                    </span>
                </div>
                <div class="v3-score-meter" title="Viral Score: ${vScore}/100">
                    <div class="v3-score-meter-fill" style="width: ${vScore}%; background: ${vColor};"></div>
                </div>
            </td>
            <td>
                <div style="display: flex; align-items: center; gap: 6px;">
                    <span class="badge-status ${dClass}" style="font-family: monospace; font-size: 12px; font-weight: 700; padding: 2px 8px;">
                        ⚙️ ${dScore}/100
                    </span>
                </div>
                <div class="v3-score-meter" title="Descriptive Score: ${dScore}/100">
                    <div class="v3-score-meter-fill" style="width: ${dScore}%; background: ${dColor};"></div>
                </div>
            </td>
        `;

        tbody.appendChild(tr);

        // Add hover play/pause to mini video
        const miniWrap = tr.querySelector(`#v3MiniWrap_${shot.shot_id}`);
        const miniVideo = miniWrap?.querySelector('video');
        if (miniWrap && miniVideo) {
            miniWrap.addEventListener('mouseenter', () => {
                miniVideo.play().catch(() => {});
                miniWrap.classList.add('playing');
            });
            miniWrap.addEventListener('mouseleave', () => {
                miniVideo.pause();
                miniVideo.currentTime = 0;
                miniWrap.classList.remove('playing');
            });
        }
    });

    // Populate JSON Viewer
    const jsonCode = document.getElementById('promov3Step2JsonCode');
    if (jsonCode) {
        jsonCode.textContent = JSON.stringify(result, null, 2);
    }
}

function togglePlayPromoV3Mini(wrapEl) {
    if (!wrapEl) return;
    const video = wrapEl.querySelector('video');
    if (!video) return;

    if (video.paused) {
        video.play().catch(() => {});
        wrapEl.classList.add('playing');
    } else {
        video.pause();
        wrapEl.classList.remove('playing');
    }
}

function switchPromoV3Step2View(view) {
    const paneTable = document.getElementById('promov3Step2PaneTable');
    const paneJson = document.getElementById('promov3Step2PaneJson');

    document.querySelectorAll('#cellPromoV3Step2 [data-v3-step2-view]').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.v3Step2View === view);
    });

    if (paneTable) paneTable.style.display = (view === 'table') ? 'block' : 'none';
    if (paneJson) paneJson.style.display = (view === 'json') ? 'block' : 'none';
}

// =============================================================================
// PROMO V3: STEP 3 CONTROLLER — GUIÓN, HOOK & LOCUCIÓN (VOICEOVER)
// =============================================================================

function initPromoV3Step3Listeners() {
    // 1. Hook Cards Selection (Steam / So in this / Directo / Entrada propia)
    Object.entries(PROMOV3_HOOK_CARD_IDS).forEach(([hookValue, cardId]) => {
        const card = document.getElementById(cardId);
        if (card) card.addEventListener('click', () => {
            const changed = normalizeHookType(hookValue) !== state.promov3.hookType;
            setPromoV3HookType(hookValue);
            if (changed && (hookValue === 'direct' || hookValue === 'custom') && state.promov3.enableSteamHook !== false) {
                showToast('El rótulo animado «NEW STEAM GAME» del Paso 5 sigue activo: desactívalo allí si no lo quieres en este vídeo.', 'info', 7000);
            }
        });
    });
    const promov3OpeningInput = document.getElementById('promov3OpeningText');
    if (promov3OpeningInput) {
        promov3OpeningInput.addEventListener('input', () => { state.promov3.openingText = promov3OpeningInput.value; });
    }

    // 2. Target Duration Slider
    const durSlider = document.getElementById('promov3TargetDuration');
    const durVal = document.getElementById('promov3TargetDurationVal');
    if (durSlider && durVal) {
        durSlider.addEventListener('input', (e) => {
            const sec = parseInt(e.target.value) || 30;
            const words = Math.round(sec * 2.3);
            durVal.textContent = `~${sec}s (~${words} palabras)`;
        });
    }

    // 3. Script Textarea Input Counter
    const scriptInput = document.getElementById('promov3ScriptText');
    if (scriptInput) {
        scriptInput.addEventListener('input', (e) => {
            const val = e.target.value;
            state.promov3.scriptText = val;
            if (typeof wizState !== 'undefined') wizState.scriptText = val;
            const wInput = document.getElementById('wizardScriptText');
            if (wInput && wInput.value !== val) {
                wInput.value = val;
            }
            const dirtyBadge = document.getElementById('wizardScriptDirtyBadge');
            if (dirtyBadge) dirtyBadge.style.display = 'inline-block';
            updatePromoV3ScriptStats();
        });
    }

    // 4. Script Toolbar Actions
    const btnGen = document.getElementById('btnPromoV3GenScript');
    if (btnGen) btnGen.addEventListener('click', () => generatePromoV3Script());

    const btnRegen = document.getElementById('btnPromoV3RegenScript');
    if (btnRegen) btnRegen.addEventListener('click', () => generatePromoV3Script());

    const btnHook = document.getElementById('btnPromoV3ScriptHook');
    if (btnHook) btnHook.addEventListener('click', () => modifyPromoV3Script('change_hook'));

    const btnShorter = document.getElementById('btnPromoV3ScriptShorter');
    if (btnShorter) btnShorter.addEventListener('click', () => modifyPromoV3Script('shorter'));

    const btnLonger = document.getElementById('btnPromoV3ScriptLonger');
    if (btnLonger) btnLonger.addEventListener('click', () => modifyPromoV3Script('longer'));

    const btnViral = document.getElementById('btnPromoV3ScriptViral');
    if (btnViral) btnViral.addEventListener('click', () => modifyPromoV3Script('more_viral'));

    // 5. Custom Instruction Toggle & Apply
    const btnCustomToggle = document.getElementById('btnPromoV3ScriptCustomToggle');
    const customBar = document.getElementById('promov3CustomInstructionBar');
    const customInput = document.getElementById('promov3CustomInstructionInput');
    const btnApplyCustom = document.getElementById('btnPromoV3ApplyCustomInstruction');
    const btnCancelCustom = document.getElementById('btnPromoV3CancelCustomInstruction');

    if (btnCustomToggle && customBar) {
        btnCustomToggle.addEventListener('click', () => {
            const isHidden = customBar.style.display === 'none' || !customBar.style.display;
            customBar.style.display = isHidden ? 'block' : 'none';
            if (isHidden && customInput) {
                setTimeout(() => customInput.focus(), 50);
            }
        });
    }

    if (btnCancelCustom && customBar) {
        btnCancelCustom.addEventListener('click', () => {
            customBar.style.display = 'none';
        });
    }

    if (btnApplyCustom) {
        btnApplyCustom.addEventListener('click', () => {
            const instr = customInput ? customInput.value.trim() : '';
            if (!instr) {
                showToast('Escribe alguna indicación o petición para modificar el guión', 'info');
                return;
            }
            modifyPromoV3Script('custom_instruction', instr);
        });
    }

    if (customInput) {
        customInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                if (btnApplyCustom) btnApplyCustom.click();
            }
        });
    }

    // 6. Voice Dropzone & File Input
    const voiceDropArea = document.getElementById('promov3VoiceDropArea');
    const voiceFileInput = document.getElementById('promov3VoiceFileInput');
    if (voiceDropArea && voiceFileInput) {
        voiceDropArea.addEventListener('click', () => voiceFileInput.click());
        voiceDropArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            voiceDropArea.style.borderColor = '#38bdf8';
            voiceDropArea.style.background = 'rgba(56, 189, 248, 0.08)';
        });
        voiceDropArea.addEventListener('dragleave', () => {
            voiceDropArea.style.borderColor = 'rgba(255, 255, 255, 0.18)';
            voiceDropArea.style.background = '';
        });
        voiceDropArea.addEventListener('drop', (e) => {
            e.preventDefault();
            voiceDropArea.style.borderColor = 'rgba(255, 255, 255, 0.18)';
            voiceDropArea.style.background = '';
            if (e.dataTransfer.files && e.dataTransfer.files.length) {
                handlePromoV3VoiceUpload(e.dataTransfer.files[0]);
            }
        });
        voiceFileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files.length) {
                handlePromoV3VoiceUpload(e.target.files[0]);
            }
        });
    }

    const btnClearVoice = document.getElementById('btnPromoV3ClearVoice');
    if (btnClearVoice) {
        btnClearVoice.addEventListener('click', () => clearPromoV3Voice());
    }

    const btnSynthVoice = document.getElementById('btnPromoV3SynthesizeVoice');
    if (btnSynthVoice) {
        btnSynthVoice.addEventListener('click', () => synthesizePromoV3Voice());
    }

    // Sliders live update listeners
    const speedSlider = document.getElementById('promov3VoiceSpeedSlider');
    const speedValElem = document.getElementById('promov3VoiceSpeedVal');
    if (speedSlider && speedValElem) {
        speedSlider.addEventListener('input', (e) => {
            speedValElem.textContent = `${parseFloat(e.target.value).toFixed(2)}x`;
        });
    }

    const stabilitySlider = document.getElementById('promov3VoiceStabilitySlider');
    const stabilityValElem = document.getElementById('promov3VoiceStabilityVal');
    if (stabilitySlider && stabilityValElem) {
        stabilitySlider.addEventListener('input', (e) => {
            stabilityValElem.textContent = parseFloat(e.target.value).toFixed(2);
        });
    }

    const similaritySlider = document.getElementById('promov3VoiceSimilaritySlider');
    const similarityValElem = document.getElementById('promov3VoiceSimilarityVal');
    if (similaritySlider && similarityValElem) {
        similaritySlider.addEventListener('input', (e) => {
            similarityValElem.textContent = parseFloat(e.target.value).toFixed(2);
        });
    }

    // High-precision Sentence 1 Cut Slider listener (seeks audio in real-time)
    const cutSlider = document.getElementById('promov3Sentence1CutSlider');
    const cutValElem = document.getElementById('promov3Sentence1CutVal');
    const audioElem = document.getElementById('promov3VoiceAudioElem');
    const curTimeDisplay = document.getElementById('promov3VoiceCurrentTimeDisplay');

    const updatePrecisionTimeDisplay = () => {
        if (audioElem && curTimeDisplay) {
            const cur = audioElem.currentTime || 0;
            const dur = (audioElem.duration && !isNaN(audioElem.duration)) ? audioElem.duration : (state.promov3.voiceDuration || 0);
            curTimeDisplay.textContent = `⏱️ ${cur.toFixed(3)}s / ${dur.toFixed(3)}s`;
        }
    };

    if (audioElem) {
        ['timeupdate', 'seeking', 'seeked', 'durationchange', 'loadedmetadata', 'play', 'pause'].forEach(evt => {
            audioElem.addEventListener(evt, updatePrecisionTimeDisplay);
        });
    }

    if (cutSlider && cutValElem) {
        cutSlider.addEventListener('input', (e) => {
            const val = parseFloat(e.target.value);
            cutValElem.textContent = `${val.toFixed(3)}s`;
            state.promov3.sentence1EndS = val;
            if (audioElem && audioElem.src) {
                audioElem.currentTime = val;
                updatePrecisionTimeDisplay();
            }
            if (typeof window.updateRaiser2AutoTiming === 'function') {
                window.updateRaiser2AutoTiming(val);
            }
        });
    }

    // 7. Step 3 Save Draft & Confirm / Approve Buttons
    const btnSave3 = document.getElementById('btnPromoV3SaveStep3');
    if (btnSave3) {
        btnSave3.addEventListener('click', () => savePromoV3Step3Progress(true, false));
    }

    const btnConfirm = document.getElementById('btnPromoV3ConfirmStep3');
    if (btnConfirm) {
        btnConfirm.addEventListener('click', () => confirmPromoV3Step3());
    }
}

async function synthesizePromoV3Voice() {
    const scriptEl = document.getElementById('promov3ScriptText');
    const scriptText = (scriptEl?.value || state.promov3.scriptText || '').trim();
    if (!scriptText) {
        showToast('Escribe o genera un guión primero para sintetizar la voz.', 'warning');
        return;
    }

    const spdEl = document.getElementById('promov3VoiceSpeedSlider');
    const stbEl = document.getElementById('promov3VoiceStabilitySlider');
    const speedVal = spdEl ? parseFloat(spdEl.value) : 1.10;
    const stabilityVal = stbEl ? parseFloat(stbEl.value) : 0.50;
    const simEl = document.getElementById('promov3VoiceSimilaritySlider');
    const similarityParsed = simEl ? parseFloat(simEl.value) : NaN;
    const similarityVal = Number.isFinite(similarityParsed) ? similarityParsed : 0.75;

    const sessId = state.promov3.sessionId || localStorage.getItem('promov3_active_session_id') || '';
    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || localStorage.getItem('promov3_active_video_path') || null;
    const btn = document.getElementById('btnPromoV3SynthesizeVoice');
    const btnText = document.getElementById('btnPromoV3SynthesizeVoiceText');
    const origHtml = btnText ? btnText.innerHTML : 'Sintetizar Voz Ahora';

    if (btn) btn.disabled = true;
    if (btnText) btnText.innerHTML = '<span class="spinner" style="display:inline-block; width:12px; height:12px; border:2px solid #fff; border-top-color:transparent; border-radius:50%; animation:spin 0.8s linear infinite; margin-right:4px;"></span> Sintetizando...';

    try {
        const res = await fetch('/api/promov3/step3/synthesize-voice', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                session_id: sessId,
                video_path: videoPath,
                video_paths: state.promov3.selectedVideos && state.promov3.selectedVideos.length ? state.promov3.selectedVideos.map(v => v.path) : null,
                script_text: scriptText,
                speed: speedVal,
                stability: stabilityVal,
                similarity_boost: similarityVal,
            }),
        });
        const data = await parseJsonResponse(res);
        if (data.status === 'ok') {
            state.promov3.voicePath = data.voice_path;
            state.promov3.voiceUrl = data.voice_url;
            state.promov3.voiceDuration = data.duration;
            state.promov3.voiceMode = 'elevenlabs';
            state.promov3.synthesizedScriptText = scriptText;

            // Show single audio player
            const container = document.getElementById('promov3VoicePlayerContainer');
            const audioElem = document.getElementById('promov3VoiceAudioElem');
            const durDisplay = document.getElementById('promov3VoiceDurationDisplay');
            const curTimeDisp = document.getElementById('promov3VoiceCurrentTimeDisplay');
            const fnElem = document.getElementById('promov3VoiceFileName');

            if (container) container.style.display = 'block';
            if (audioElem && data.voice_url) {
                audioElem.src = data.voice_url;
                audioElem.load();
            }
            if (durDisplay) durDisplay.textContent = `${data.duration.toFixed(3)}s`;
            if (curTimeDisp) curTimeDisp.textContent = `⏱️ 0.000s / ${data.duration.toFixed(3)}s`;
            if (fnElem) {
                const speeds = data.speed_hook != null
                    ? `Hook ${Number(data.speed_hook).toFixed(2)}x · Resto ${Number(data.speed_full ?? data.speed_hook).toFixed(2)}x`
                    : `${Number(data.speed_full ?? speedVal).toFixed(2)}x`;
                fnElem.textContent = `Locución Sintetizada (${speeds}, Estabilidad ${stabilityVal.toFixed(2)})`;
            }

            // Update cut slider limits and value
            const cutVal = (data.sentence_1_end_s && data.sentence_1_end_s > 0.5) ? data.sentence_1_end_s : Math.min(2.5, data.duration * 0.4);
            const maxVal = Math.min(10.0, data.duration || 6.0);
            const cSlider = document.getElementById('promov3Sentence1CutSlider');
            const cValElem = document.getElementById('promov3Sentence1CutVal');
            const cMaxLabel = document.getElementById('promov3Sentence1CutMaxLabel');
            if (cSlider) {
                cSlider.max = maxVal.toFixed(3);
                cSlider.value = cutVal.toFixed(3);
            }
            if (cValElem) cValElem.textContent = `${cutVal.toFixed(3)}s`;
            if (cMaxLabel) cMaxLabel.textContent = `${maxVal.toFixed(3)}s`;
            state.promov3.sentence1EndS = cutVal;
            if (typeof window.updateRaiser2AutoTiming === 'function') {
                window.updateRaiser2AutoTiming(cutVal);
            }

            const badgeEl = document.getElementById('promov3VoiceStatusBadge');
            if (badgeEl) {
                badgeEl.innerText = `Sintetizada (${data.duration.toFixed(1)}s)`;
                badgeEl.style.background = 'rgba(52, 211, 153, 0.2)';
                badgeEl.style.color = '#34d399';
            }

            showToast(`🎙️ Locución sintetizada con éxito (${data.duration.toFixed(1)}s, ${data.word_count} palabras)`, 'success');
        } else {
            showToast('Error sintetizando voz: ' + (data.detail || 'Fallo en ElevenLabs'), 'error');
        }
    } catch (e) {
        showToast('Error de conexión al sintetizar voz: ' + e.message, 'error');
    } finally {
        if (btn) btn.disabled = false;
        if (btnText) btnText.innerHTML = origHtml;
    }
}

function unlockPromoV3Step3(step2Result) {
    const cell3 = document.getElementById('cellPromoV3Step3');
    if (cell3) {
        cell3.classList.remove('cell-disabled', 'cell-locked');
        cell3.style.opacity = '1';
    }

    // Update Top Stepper bar indicator 3
    const stepperIndicators = document.querySelectorAll('.v3-step-indicator');
    if (stepperIndicators && stepperIndicators[2]) {
        stepperIndicators[2].classList.remove('locked');
        stepperIndicators[2].classList.add('active');
        stepperIndicators[2].style.opacity = '1';
        stepperIndicators[2].style.color = '#38bdf8';
        const numCircle = stepperIndicators[2].querySelector('span');
        if (numCircle) {
            numCircle.style.background = '#0284c7';
            numCircle.style.color = '#fff';
        }
    }

    const statusBadge = document.getElementById('promov3Step3StatusBadge');
    if (statusBadge) {
        statusBadge.textContent = 'Listo para redactar';
        statusBadge.style.background = 'rgba(56, 189, 248, 0.2)';
        statusBadge.style.color = '#38bdf8';
    }

    // Auto-detect game name if empty
    const gameNameInput = document.getElementById('promov3GameName');
    if (gameNameInput && !gameNameInput.value.trim()) {
        let suggestedName = '';
        if (state.promov3.selectedVideo) {
            const raw = state.promov3.selectedVideo.filename || '';
            // Strip hash prefixes (e.g. "024fd9_") and extension
            suggestedName = raw.replace(/^[a-f0-9]{6}_/i, '').replace(/\.[^/.]+$/, '').replace(/[_\\-]/g, ' ').trim();
        }
        gameNameInput.value = suggestedName || 'Gameplay';
    }

    // Update Input Banner with Step 2 highlights
    const shots = (step2Result?.shots || []).filter(s => s.rendered && s.format_score !== undefined);
    const topViral = shots.slice().sort((a, b) => (b.viral_score || 0) - (a.viral_score || 0))[0];
    const topDesc = shots.slice().sort((a, b) => (b.descriptive_score || 0) - (a.descriptive_score || 0))[0];

    const inputNotice = document.getElementById('promov3Step3InputNotice');
    const clipsNotice = document.getElementById('promov3Step3ClipsNotice');
    if (inputNotice) {
        let text = `📥 Conectado con <strong>${shots.length} clips evaluados</strong> del Paso 2. `;
        if (step2Result?.batch_stats?.early_stopped) {
            text += `<span style="color: #34d399; font-weight: 600;">(⚡ Lote 1 Optimizado: ${escapeHtml(step2Result.batch_stats.batches_saved)} lotes ahorrados).</span> `;
        }
        if (topViral) text += `Top Viral: <em>Shot #${escapeHtml(topViral.shot_id)} (${escapeHtml(topViral.viral_score)}/100)</em>. `;
        if (topDesc) text += `Top Mecánica: <em>Shot #${escapeHtml(topDesc.shot_id)} (${escapeHtml(topDesc.descriptive_score)}/100)</em>.`;
        inputNotice.innerHTML = text;
    }
    if (clipsNotice) {
        clipsNotice.textContent = `${shots.length} clips 9:16 listos`;
    }

    // Populate active ElevenLabs voice name from settings
    const activeVoiceEl = document.getElementById('promov3ActiveVoiceName');
    const voiceSelectEl = document.getElementById('cfgVoiceId');
    if (activeVoiceEl) {
        const voiceVal = (voiceSelectEl?.value || 'JBFqnCBsd6RMkjVDRZzb').trim();
        activeVoiceEl.innerText = `ElevenLabs (${voiceVal.substring(0, 8)}...)`;
    }

    // Scroll smoothly to Cell 3
    if (cell3) {
        cell3.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}

function updatePromoV3ScriptStats() {
    const scriptEl = document.getElementById('promov3ScriptText');
    const text = (scriptEl?.value || state.promov3.scriptText || '').trim();
    const words = text ? text.split(/\s+/).filter(Boolean).length : 0;
    const estDur = words > 0 ? (words / 2.3).toFixed(1) : 0;

    const countEl = document.getElementById('promov3WordCount');
    const durEl = document.getElementById('promov3EstDuration');
    if (countEl) countEl.innerText = words;
    if (durEl) durEl.innerText = `${estDur}s`;
}

async function generatePromoV3Script() {
    if (state.promov3 && state.promov3.isGeneratingScript) return;

    const gameName = document.getElementById('promov3GameName')?.value.trim() || 'Gameplay';
    const targetDur = parseFloat(document.getElementById('promov3TargetDuration')?.value) || 30.0;
    const tone = document.getElementById('promov3ToneSelect')?.value || 'viral_hype';
    const briefing = document.getElementById('promov3Briefing')?.value.trim() || '';
    const hookFields = promoV3HookFields();
    const sessionId = state.promov3.step1Result ? state.promov3.step1Result.session_id : (state.promov3.step2Result?.session_id || null);
    if (hookFields.hook_type === 'custom' && !hookFields.opening_text) {
        showToast('Escribe la frase de «Entrada propia» o elige otra entrada antes de generar el guion.', 'warning');
        document.getElementById('promov3OpeningText')?.focus?.();
        return;
    }

    const btn = document.getElementById('btnPromoV3GenScript');
    const btnText = document.getElementById('btnPromoV3GenScriptText');
    state.promov3.isGeneratingScript = true;
    if (btn) btn.disabled = true;
    if (btnText) btnText.innerHTML = '<span>⏳</span> Redactando...';

    showToast('Generando guión viral con IA considerando el metraje del Paso 2...', 'info');

    try {
        const res = await fetch('/api/v2/script/generate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                game_name: gameName,
                target_duration: targetDur,
                tone: tone,
                ...hookFields,
                // Same speed the voice will use, so the word budget fits the duration.
                speech_speed: promoV3VoiceSpeed(),
                briefing_text: briefing,
                session_id: sessionId,
            }),
        });

        const data = await res.json();
        if (data.status === 'ok') {
            state.promov3.scriptText = data.script;
            state.promov3.retentionData = data.retention_data || null;
            if (typeof wizState !== 'undefined') {
                wizState.scriptText = data.script;
                wizState.retentionData = data.retention_data || null;
                if (typeof wizardRenderRetentionInspector === 'function') {
                    wizardRenderRetentionInspector(wizState.retentionData);
                }
            }
            const scriptEl = document.getElementById('promov3ScriptText');
            if (scriptEl) scriptEl.value = data.script;
            updatePromoV3ScriptStats();
            showToast('¡Guión viral generado con éxito! Puedes revisarlo o editarlo antes de sintetizar la voz.', 'success');
        } else {
            showToast('Error generando guión: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al conectar con la IA: ' + e.message, 'error');
    } finally {
        state.promov3.isGeneratingScript = false;
        if (btn) btn.disabled = false;
        if (btnText) btnText.textContent = 'Generar con IA';
    }
}

async function modifyPromoV3Script(action, customInstruction = '') {
    if (state.promov3 && state.promov3.isModifyingScript) return;

    const scriptEl = document.getElementById('promov3ScriptText');
    const currentScript = scriptEl ? scriptEl.value.trim() : (state.promov3.scriptText || '');
    if (!currentScript) {
        showToast('Escribe o genera un guión primero para modificarlo', 'info');
        return;
    }
    const gameName = document.getElementById('promov3GameName')?.value.trim() || 'Gameplay';
    const targetDur = parseFloat(document.getElementById('promov3TargetDuration')?.value) || 30.0;

    let toastMsg = 'Modificando guión...';
    if (action === 'shorter') toastMsg = 'Acortando guión...';
    else if (action === 'longer') toastMsg = 'Alargando guión...';
    else if (action === 'change_hook') toastMsg = 'Generando nuevo Hook inicial...';
    else if (action === 'more_viral') toastMsg = 'Aumentando impacto y energía viral...';
    else if (action === 'custom_instruction') toastMsg = 'Aplicando tus indicaciones al guión...';

    state.promov3.isModifyingScript = true;
    showToast(toastMsg, 'info');

    try {
        const res = await fetch('/api/v2/script/modify', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                script_text: currentScript,
                action: action,
                game_name: gameName,
                target_duration: targetDur,
                custom_instruction: customInstruction,
                // Keep the chosen opening (custom phrase / direct) and the voice speed.
                ...promoV3HookFields(),
                speech_speed: promoV3VoiceSpeed(),
            }),
        });

        const data = await res.json();
        if (data.status === 'ok') {
            state.promov3.scriptText = data.script;
            state.promov3.retentionData = data.retention_data || null;
            if (typeof wizState !== 'undefined') {
                wizState.scriptText = data.script;
                wizState.retentionData = data.retention_data || null;
                if (typeof wizardRenderRetentionInspector === 'function') {
                    wizardRenderRetentionInspector(wizState.retentionData);
                }
            }
            if (scriptEl) scriptEl.value = data.script;
            updatePromoV3ScriptStats();

            if (action === 'custom_instruction') {
                const inputEl = document.getElementById('promov3CustomInstructionInput');
                if (inputEl) inputEl.value = '';
                const barEl = document.getElementById('promov3CustomInstructionBar');
                if (barEl) barEl.style.display = 'none';
            }

            showToast('Guión modificado con éxito. Pulsa en "Sintetizar Voz Ahora" para generar la nueva locución.', 'success');
        } else {
            showToast('Error modificando guión: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al conectar con la IA: ' + e.message, 'error');
    } finally {
        state.promov3.isModifyingScript = false;
    }
}

async function handlePromoV3VoiceUpload(file) {
    if (!file) return;
    showToast(`Subiendo archivo de voz "${file.name}"...`, 'info');

    const formData = new FormData();
    formData.append('file', file);

    try {
        const res = await fetch('/api/v2/voiceover/upload', {
            method: 'POST',
            body: formData,
        });
        const data = await res.json();
        if (data.status === 'ok') {
            state.promov3.voiceMode = 'custom_file';
            state.promov3.voicePath = data.saved_path;
            state.promov3.voiceUrl = data.url;
            state.promov3.voiceDuration = data.duration;
            state.promov3.voiceFilename = data.filename;

            const hidden = document.getElementById('promov3VoicePath');
            if (hidden) hidden.value = data.saved_path;

            const container = document.getElementById('promov3VoicePlayerContainer');
            const nameEl = document.getElementById('promov3VoiceFileName');
            const durEl = document.getElementById('promov3VoiceDurationDisplay');
            const audioElem = document.getElementById('promov3VoiceAudioElem');
            const badgeEl = document.getElementById('promov3VoiceStatusBadge');

            if (container) container.style.display = 'block';
            if (nameEl) nameEl.innerText = data.filename;
            if (durEl) durEl.innerText = `${data.duration.toFixed(3)}s`;
            const curTimeDisp = document.getElementById('promov3VoiceCurrentTimeDisplay');
            if (curTimeDisp) curTimeDisp.textContent = `⏱️ 0.000s / ${data.duration.toFixed(3)}s`;
            if (audioElem) {
                audioElem.src = data.url;
                audioElem.load();
            }
            if (badgeEl) {
                badgeEl.innerText = `Voz cargada (${data.duration.toFixed(1)}s)`;
                badgeEl.style.background = 'rgba(34, 197, 94, 0.15)';
                badgeEl.style.color = '#4ade80';
            }

            showToast(`¡Voz cargada con éxito! Duración: ${data.duration.toFixed(1)}s`, 'success');
        } else {
            showToast('Error al procesar archivo de voz: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al subir archivo de voz: ' + e.message, 'error');
    }
}

function clearPromoV3Voice() {
    state.promov3.voiceMode = 'elevenlabs';
    state.promov3.voicePath = '';
    state.promov3.voiceUrl = '';
    state.promov3.voiceDuration = 0;
    state.promov3.voiceFilename = '';

    const hidden = document.getElementById('promov3VoicePath');
    if (hidden) hidden.value = '';

    const container = document.getElementById('promov3VoicePlayerContainer');
    if (container) container.style.display = 'none';

    const audioElem = document.getElementById('promov3VoiceAudioElem');
    if (audioElem) {
        audioElem.pause();
        audioElem.src = '';
    }

    const badgeEl = document.getElementById('promov3VoiceStatusBadge');
    if (badgeEl) {
        badgeEl.innerText = 'ElevenLabs Activo';
        badgeEl.style.background = 'rgba(59, 130, 246, 0.15)';
        badgeEl.style.color = '#60a5fa';
    }

    showToast('Archivo de voz quitado: se sintetizará el guión con ElevenLabs', 'info');
}

async function confirmPromoV3Step3() {
    const scriptEl = document.getElementById('promov3ScriptText');
    const scriptText = (scriptEl?.value || state.promov3.scriptText || '').trim();

    if (!scriptText) {
        showToast('Por favor, genera o redacta un guión antes de continuar.', 'warning');
        return;
    }

    if (!state.promov3.voicePath && !state.promov3.voiceUrl) {
        showToast('Por favor, sintetiza la voz con el botón "Sintetizar Voz Ahora" antes de aprobar.', 'warning');
        return;
    }

    const cutSliderEl = document.getElementById('promov3Sentence1CutSlider');
    const s1EndVal = cutSliderEl ? parseFloat(cutSliderEl.value) : (state.promov3.sentence1EndS || null);

    const gameName = document.getElementById('promov3GameName')?.value.trim() || 'Gameplay';
    const hookFields = promoV3HookFields();
    const tone = document.getElementById('promov3ToneSelect')?.value || 'viral_hype';
    const targetDur = parseFloat(document.getElementById('promov3TargetDuration')?.value) || 30.0;
    const briefing = document.getElementById('promov3Briefing')?.value.trim() || '';
    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || localStorage.getItem('promov3_active_video_path') || null;
    const sessionId = state.promov3.step1Result ? state.promov3.step1Result.session_id : (state.promov3.step2Result?.session_id || state.promov3.sessionId || localStorage.getItem('promov3_active_session_id') || `sess_${Date.now()}`);

    const words = scriptText ? scriptText.split(/\s+/).filter(Boolean).length : 0;
    const estDur = words > 0 ? parseFloat((words / 2.3).toFixed(1)) : (state.promov3.voiceDuration || 0);

    const step3Data = {
        session_id: sessionId,
        video_path: videoPath,
        game_name: gameName,
        ...hookFields,
        tone: tone,
        target_duration: targetDur,
        briefing_text: briefing,
        script_text: scriptText,
        word_count: words,
        estimated_duration: estDur,
        voice_mode: state.promov3.voiceMode || 'elevenlabs',
        voice_path: state.promov3.voicePath || null,
        voice_url: state.promov3.voiceUrl || null,
        voice_duration: state.promov3.voiceDuration || null,
        sentence_1_end_s: s1EndVal,
    };

    try {
        const res = await fetch('/api/promov3/step3/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(step3Data),
        });
        const data = await res.json();
        if (data.status === 'ok') {
            state.promov3.step3Result = data.data;
            state.promov3.sessionId = data.session_id || sessionId;
            localStorage.setItem('promov3_active_session_id', state.promov3.sessionId);
            if (videoPath) localStorage.setItem('promov3_active_video_path', videoPath);
            updatePromoV3SessionBanner();

            const statusBadge = document.getElementById('promov3Step3StatusBadge');
            if (statusBadge) {
                statusBadge.textContent = `Aprobado: ${words} palabras (~${estDur}s)`;
                statusBadge.style.background = 'rgba(52, 211, 153, 0.2)';
                statusBadge.style.color = '#34d399';
            }
            unlockPromoV3Step4(data.data);
            if (typeof window.updateRaiser2AutoTiming === 'function') {
                window.updateRaiser2AutoTiming(s1EndVal);
            }
            showToast('¡Paso 3 completado y aprobado! Guión fijado para montaje.', 'success');
        } else {
            showToast('Error guardando Paso 3: ' + (data.detail || 'Error'), 'error');
        }
    } catch (e) {
        showToast('Error al guardar datos del Paso 3: ' + e.message, 'error');
    }
}

// =============================================================================
// Promo V3 Step 4: Sequence Assembly & Short Director (EDL)
// =============================================================================

function unlockPromoV3Step4(step3Result) {
    const cell4 = document.getElementById('cellPromoV3Step4');
    if (cell4) {
        cell4.classList.remove('cell-locked');
        cell4.style.opacity = '1';
    }
    const badge4 = document.getElementById('promov3Step4StatusBadge');
    if (badge4 && (!state.promov3 || !state.promov3.step4Result)) {
        badge4.textContent = 'Listo para orquestación EDL';
        badge4.style.background = 'rgba(245, 158, 11, 0.2)';
        badge4.style.color = '#fbbf24';
    }
    const lock4 = document.getElementById('promov3Step4LockIcon');
    if (lock4) lock4.textContent = '🔓';

    // Auto prefill genre if empty
    const genreInput = document.getElementById('promov3Step4GameGenre');
    if (genreInput && !genreInput.value) {
        const tone = (step3Result && step3Result.tone) || (state.promov3 && state.promov3.step3Result && state.promov3.step3Result.tone) || '';
        const gameName = (step3Result && step3Result.game_name) || (state.promov3 && state.promov3.step3Result && state.promov3.step3Result.game_name) || '';
        if (tone.includes('cozy') || tone.includes('chill') || tone.includes('relax')) {
            genreInput.value = 'Cozy / Relaxing Simulator';
        } else if (tone.includes('hype') || tone.includes('epic') || tone.includes('action')) {
            genreInput.value = 'Acción / Aventura Dinámica';
        } else if (gameName) {
            genreInput.value = gameName;
        }
    }

    // Update Stepper indicator 4
    const stepperIndicators = document.querySelectorAll('.v3-step-indicator');
    if (stepperIndicators && stepperIndicators[3]) {
        stepperIndicators[3].classList.remove('locked');
        stepperIndicators[3].classList.add('active');
        stepperIndicators[3].style.opacity = '1';
        stepperIndicators[3].style.color = '#fbbf24';
        const numCircle = stepperIndicators[3].querySelector('span');
        if (numCircle) {
            numCircle.style.background = '#d97706';
            numCircle.style.color = '#fff';
        }
    }
}

async function runPromoV3Step4(approvedShotIds = []) {
    approvedShotIds = Array.isArray(approvedShotIds) ? approvedShotIds : [];
    if (state.promov3 && state.promov3.isStep4Running) return;

    if (!state.promov3 || !state.promov3.step2Result) {
        showToast('Debes completar el Paso 2 (Evaluación 9:16) antes de orquestar el montaje.', 'warning');
        return;
    }
    if (!state.promov3.step3Result && !state.promov3.scriptText) {
        showToast('Debes aprobar o guardar el guión del Paso 3 antes de orquestar el montaje.', 'warning');
        return;
    }

    const sessId = state.promov3.sessionId || localStorage.getItem('promov3_active_session_id') || '';
    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || (state.promov3.step1Result && state.promov3.step1Result.video_info && state.promov3.step1Result.video_info.path) || '';
    const gameName = (document.getElementById('promov3GameName') && document.getElementById('promov3GameName').value.trim()) || (state.promov3.step3Result && state.promov3.step3Result.game_name) || '';
    const gameGenreInput = document.getElementById('promov3Step4GameGenre');
    const gameGenre = (gameGenreInput && gameGenreInput.value.trim()) || (state.promov3.step3Result && state.promov3.step3Result.tone) || '';
    const allowSecondary = document.getElementById('promov3AllowSecondaryTransition') ? document.getElementById('promov3AllowSecondaryTransition').checked : true;
    const cutStartMode = normalizeCutStartMode(document.getElementById('promov3CutStartMode')?.value || state.promov3.cutStartMode);
    state.promov3.cutStartMode = cutStartMode;

    const btn = document.getElementById('btnPromoV3RunStep4');
    const btnText = document.getElementById('btnPromoV3RunStep4Text');
    const origHtml = btnText ? btnText.innerHTML : 'Orquestar Montaje con Director IA';

    state.promov3.isStep4Running = true;
    if (btn) btn.disabled = true;
    if (btnText) btnText.innerHTML = '<span class="spinner" style="display:inline-block; width:14px; height:14px; border:2px solid #fff; border-top-color:transparent; border-radius:50%; animation:spin 0.8s linear infinite; margin-right:6px;"></span> Orquestando con Director IA...';

    const badge4 = document.getElementById('promov3Step4StatusBadge');
    if (badge4) {
        badge4.textContent = 'Orquestando narrativa y transiciones...';
        badge4.style.background = 'rgba(245, 158, 11, 0.2)';
        badge4.style.color = '#fbbf24';
    }

    try {
        const res = await fetch('/api/promov3/step4/orchestrate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                session_id: sessId,
                approved_shot_ids: approvedShotIds,
                video_path: videoPath,
                game_name: gameName,
                game_genre: gameGenre,
                allow_secondary_transition: allowSecondary,
                cut_start_mode: cutStartMode,
                script_text: document.getElementById('promov3ScriptText')?.value.trim() || null,
                sentence_1_end_s: parseFloat(document.getElementById('promov3Sentence1CutSlider')?.value) || state.promov3.sentence1EndS || null,
                hook_duration: parseFloat(document.getElementById('promov3Sentence1CutSlider')?.value) || state.promov3.sentence1EndS || null,
            }),
        });

        const data = await res.json();
        if (data.status === 'needs_shot_approval') {
            if (badge4) badge4.textContent = 'Revisa los planos descartados para completar el montaje';
            const hostId = document.getElementById('promov3Step4EmptyPlaceholder')?.parentElement?.id;
            const host = document.getElementById('promov3Step4EmptyPlaceholder')?.parentElement;
            if (host && !host.id) host.id = 'promov3ShotRecoveryHost';
            wizardShowDiscardedShotRecovery(data.discarded_shots || [], host?.id || hostId, ids => runPromoV3Step4(ids));
            return;
        }
        if (data.status === 'ok' && data.edl) {
            state.promov3.step4Result = data.edl;
            if (data.session_id) {
                state.promov3.sessionId = data.session_id;
                localStorage.setItem('promov3_active_session_id', data.session_id);
            }
            finishPromoV3Step4Success(data.edl, false);
            showToast(`🎬 ¡Montaje orquestado con éxito! ${data.edl.cut_count} cortes (${data.edl.total_duration}s)`, 'success');
        } else {
            showToast('Error orquestando montaje: ' + wizardMontageErrorMessage(data.detail), 'error');
            if (badge4) {
                badge4.textContent = 'Error al orquestar';
                badge4.style.background = 'rgba(239, 68, 68, 0.2)';
                badge4.style.color = '#f87171';
            }
        }
    } catch (e) {
        showToast('Error de red al orquestar Paso 4: ' + e.message, 'error');
        if (badge4) {
            badge4.textContent = 'Error de conexión';
            badge4.style.background = 'rgba(239, 68, 68, 0.2)';
            badge4.style.color = '#f87171';
        }
    } finally {
        state.promov3.isStep4Running = false;
        if (btn) btn.disabled = false;
        if (btnText) btnText.innerHTML = origHtml;
    }
}

function finishPromoV3Step4Success(edl, isRestored = false) {
    if (!edl) return;

    unlockPromoV3Step4(state.promov3.step3Result);

    const badge4 = document.getElementById('promov3Step4StatusBadge');
    if (badge4) {
        const cutCount = edl.cut_count || (edl.timeline && edl.timeline.length) || 0;
        const dur = (edl.total_duration || 0).toFixed(3);
        badge4.textContent = `✓ Montaje Listo: ${cutCount} cortes (${dur}s)`;
        badge4.style.background = 'rgba(52, 211, 153, 0.2)';
        badge4.style.color = '#34d399';
    }

    if (edl.game_genre) {
        const genreInput = document.getElementById('promov3Step4GameGenre');
        if (genreInput && !genreInput.value) genreInput.value = edl.game_genre;
    }

    const s4Empty = document.getElementById('promov3Step4EmptyPlaceholder');
    if (s4Empty) s4Empty.style.display = 'none';

    const s4Results = document.getElementById('promov3Step4ResultsContainer');
    if (s4Results) s4Results.style.display = 'block';

    const titleEl = document.getElementById('promov3EdlTitle');
    if (titleEl) titleEl.textContent = edl.title || `Montaje Director Promo V3`;

    const conceptEl = document.getElementById('promov3EdlConcept');
    if (conceptEl) conceptEl.textContent = edl.concept_summary || 'Montaje sincronizado con gancho viral y ritmo narrativo.';

    const badgesContainer = document.getElementById('promov3EdlBadges');
    if (badgesContainer) {
        const badgesHtml = [];
        if (edl.director_model) {
            badgesHtml.push(`<span class="badge-status" style="font-size:11px; background:rgba(245,158,11,0.15); color:#fbbf24; border:1px solid rgba(245,158,11,0.3); border-radius:4px; padding:3px 8px;">🤖 ${escapeHtml(edl.director_model)}</span>`);
        }
        if (edl.game_genre) {
            badgesHtml.push(`<span class="badge-status" style="font-size:11px; background:rgba(167,139,250,0.15); color:#a78bfa; border:1px solid rgba(167,139,250,0.3); border-radius:4px; padding:3px 8px;">🎮 ${escapeHtml(edl.game_genre)}</span>`);
        }
        badgesHtml.push(`<span class="badge-status" style="font-size:11px; background:rgba(52,211,153,0.15); color:#34d399; border:1px solid rgba(52,211,153,0.3); border-radius:4px; padding:3px 8px;">⏱️ Duración: ${(edl.total_duration || 0).toFixed(3)}s</span>`);
        badgesHtml.push(`<span class="badge-status" style="font-size:11px; background:rgba(56,189,248,0.15); color:#38bdf8; border:1px solid rgba(56,189,248,0.3); border-radius:4px; padding:3px 8px;">✂️ ${edl.cut_count || (edl.timeline && edl.timeline.length) || 0} cortes</span>`);

        if (edl.secondary_transition_applied) {
            badgesHtml.push(`<span class="badge-status" style="font-size:11px; background:rgba(236,72,153,0.15); color:#f472b6; border:1px solid rgba(236,72,153,0.3); border-radius:4px; padding:3px 8px;">✨ Transición secundaria activa</span>`);
        } else {
            badgesHtml.push(`<span class="badge-status" style="font-size:11px; background:rgba(255,255,255,0.06); color:var(--text-muted); border-radius:4px; padding:3px 8px;">Cortes limpios (Sin trans. secundaria)</span>`);
        }
        badgesContainer.innerHTML = badgesHtml.join('');
    }

    const noteEl = document.getElementById('promov3EdlSecondaryTransitionNote');
    if (noteEl) {
        if (edl.secondary_transition_reason) {
            noteEl.style.display = 'block';
            noteEl.innerHTML = `<strong>💡 Criterio del Director sobre transición secundaria:</strong> ${escapeHtml(edl.secondary_transition_reason)}`;
        } else {
            noteEl.style.display = 'none';
        }
    }

    renderPromoV3Step4Timeline(edl);
    updatePromoV3SessionBanner();

    const hookEnd = parseFloat(edl.sentence_1_end_s || edl.hook_duration || (edl.timeline && edl.timeline[0]?.duration) || 2.45);
    if (typeof window.updateRaiser2AutoTiming === 'function') {
        window.updateRaiser2AutoTiming(hookEnd);
    }

    unlockPromoV3Step5(edl);
}

function renderPromoV3Step4Timeline(edl) {
    const container = document.getElementById('promov3Step4TimelineContainer');
    if (!container || !edl || !edl.timeline) return;

    container.innerHTML = '';

    edl.timeline.forEach((cut, idx) => {
        const card = document.createElement('div');
        card.className = 'card promov3-cut-card';
        card.style.padding = '14px 16px';
        card.style.background = 'rgba(15, 23, 42, 0.55)';
        card.style.border = '1px solid rgba(255, 255, 255, 0.08)';
        card.style.borderRadius = '10px';
        card.style.display = 'flex';
        card.style.flexDirection = 'column';
        card.style.gap = '12px';

        // Role styling
        let roleBadgeColor = '#38bdf8';
        let roleBg = 'rgba(56, 189, 248, 0.15)';
        let roleLabel = 'Gameplay';
        if (cut.role === 'hook' || idx === 0) {
            roleBadgeColor = '#f59e0b';
            roleBg = 'rgba(245, 158, 11, 0.15)';
            roleLabel = '⚡ Gancho (Hook)';
        } else if (cut.role === 'payoff' || cut.role === 'cta' || idx === edl.timeline.length - 1) {
            roleBadgeColor = '#34d399';
            roleBg = 'rgba(52, 211, 153, 0.15)';
            roleLabel = '🎯 Cierre / CTA';
        } else {
            roleLabel = `🎮 ${cut.role ? (cut.role.charAt(0).toUpperCase() + cut.role.slice(1)) : 'Gameplay'}`;
        }

        const transOut = cut.transition_out || { type: 'cut', name: 'Corte Limpio' };
        const transType = transOut.type || 'cut';

        // Video preview url
        const videoUrl = cut.preview_9_16_url || cut.preview_url || '';

        card.innerHTML = `
            <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; border-bottom: 1px solid rgba(255, 255, 255, 0.06); padding-bottom: 8px;">
                <div style="display: flex; align-items: center; gap: 10px;">
                    <span style="font-weight: 700; font-size: 13.5px; color: var(--text-primary); font-family: monospace;">#${escapeHtml(cut.order || (idx + 1))}</span>
                    <span class="badge-status" style="font-size: 11px; padding: 2px 8px; background: ${roleBg}; color: ${roleBadgeColor}; border-radius: 4px; font-weight: 600;">
                        ${escapeHtml(roleLabel)}
                    </span>
                    <span style="font-size: 12px; color: var(--text-muted); font-family: monospace;">
                        ⏱️ ${cut.start_time_in_video !== undefined ? cut.start_time_in_video.toFixed(3) : '0.000'}s ➔ ${cut.end_time_in_video !== undefined ? cut.end_time_in_video.toFixed(3) : '0.000'}s (${(cut.duration || 0).toFixed(3)}s)
                    </span>
                    ${cut.duration > ((cut.start_time_in_video ?? 0) < 12 ? 3 : 5) ? `
                        <span class="badge-status" style="font-size: 10px; padding: 1px 6px; background: rgba(239, 68, 68, 0.15); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 4px;" title="Supera el límite de ritmo aplicable al momento del vídeo">
                            ⚠️ Supera el máximo de ${(cut.start_time_in_video ?? 0) < 12 ? 3 : 5}s
                        </span>
                    ` : `
                        <span class="badge-status" style="font-size: 10px; padding: 1px 5px; background: rgba(52, 211, 153, 0.15); color: #34d399; border-radius: 3px;" title="Corte óptimo para retención viral">
                            ⚡ ≤${(cut.start_time_in_video ?? 0) < 12 ? 3 : 5}s
                        </span>
                    `}
                </div>
                <div style="font-size: 11.5px; color: var(--text-muted); display: flex; align-items: center; gap: 8px;">
                    ${cut.video_name ? `
                        <span class="badge-status" style="font-size: 10px; padding: 1px 6px; background: rgba(99, 102, 241, 0.15); color: #a5b4fc; border: 1px solid rgba(99, 102, 241, 0.3); border-radius: 4px; max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${escapeHtml(cut.video_name)}">
                            📁 ${escapeHtml(cut.video_name)}
                        </span>
                    ` : ''}
                    <span>Plano: <strong>Shot #${escapeHtml(cut.shot_id)}</strong> (in: ${(cut.source_in !== undefined ? cut.source_in.toFixed(3) : '0.000')}s)</span>
                </div>
            </div>

            <div style="display: grid; grid-template-columns: 100px 1fr; gap: 16px; align-items: start;">
                <!-- Left: 9:16 Video preview -->
                <div style="width: 100px; height: 160px; background: #000; border-radius: 8px; overflow: hidden; position: relative; border: 1px solid rgba(255, 255, 255, 0.1);">
                    ${videoUrl ? `
                        <video src="${escapeHtml(videoUrl)}" muted loop playsinline controls style="width: 100%; height: 100%; object-fit: cover; display: block;" onmouseenter="this.play()" onmouseleave="this.pause()"></video>
                    ` : `
                        <div style="display: flex; align-items: center; justify-content: center; height: 100%; font-size: 10px; color: var(--text-muted); text-align: center; padding: 4px;">
                            Sin preview 9:16
                        </div>
                    `}
                </div>

                <!-- Right: Script alignment, Director note & Transition selector -->
                <div style="display: flex; flex-direction: column; gap: 8px;">
                    <!-- Script segment -->
                    <div>
                        <span style="font-size: 10.5px; text-transform: uppercase; font-weight: 700; letter-spacing: 0.5px; color: var(--text-muted); display: block; margin-bottom: 3px;">
                            🎙️ Locución en este plano:
                        </span>
                        <div style="font-size: 13px; font-style: italic; color: #f8fafc; background: rgba(0, 0, 0, 0.35); padding: 8px 12px; border-radius: 6px; border-left: 3px solid ${roleBadgeColor}; line-height: 1.45;">
                            "${escapeHtml(cut.script_segment || 'Sin locución directa en este corte.')}"
                        </div>
                    </div>

                    <!-- Director Note -->
                    ${cut.director_notes ? `
                        <div style="font-size: 11.5px; color: var(--text-secondary); line-height: 1.4;">
                            💡 <strong>Criterio de montaje:</strong> ${escapeHtml(cut.director_notes)}
                        </div>
                    ` : ''}

                    <!-- Transition Out Selector -->
                    <div style="margin-top: 4px; padding-top: 8px; border-top: 1px dashed rgba(255, 255, 255, 0.08); display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px;">
                        <div style="display: flex; align-items: center; gap: 8px;">
                            <span style="font-size: 11.5px; font-weight: 600; color: var(--text-muted);">
                                ⚡ Transición de salida:
                            </span>
                            <select id="selectTransitionOut_${idx}" class="form-control" style="font-size: 12px; padding: 4px 8px; border-radius: 6px; background: rgba(0, 0, 0, 0.4); border: 1px solid var(--border-color); color: var(--text-primary); cursor: pointer;">
                                <option value="cut" ${transType === 'cut' ? 'selected' : ''}>✂️ Corte Limpio (0.0s)</option>
                                <option value="white_flash" ${transType === 'white_flash' ? 'selected' : ''}>⚡ Flash Blanco (0.15s) [Hook / Alto Impacto]</option>
                                <option value="circle_zoom" ${transType === 'circle_zoom' ? 'selected' : ''}>🎯 Zoom Radial (0.35s) [Foco Narrativo / Cozy]</option>
                                <option value="glitch_pixelize" ${transType === 'glitch_pixelize' ? 'selected' : ''}>👾 Glitch Pixelado (0.30s) [Acción / Cyberpunk]</option>
                            </select>
                        </div>
                        <span id="badgeTransitionReason_${idx}" style="font-size: 11px; color: var(--text-muted); font-style: italic;">
                            ${escapeHtml(transOut.reason || (transType !== 'cut' ? 'Transición contextual' : 'Corte directo'))}
                        </span>
                    </div>
                </div>
            </div>
        `;

        // Wire dropdown change
        const selectElem = card.querySelector(`#selectTransitionOut_${idx}`);
        if (selectElem) {
            selectElem.addEventListener('change', (e) => {
                const newType = e.target.value;
                const specMap = {
                    white_flash: { name: 'Flash Blanco', badge: '⚡ Flash Blanco (0.15s)', duration: 0.15 },
                    glitch_pixelize: { name: 'Glitch Pixelado', badge: '👾 Glitch Pixelado (0.30s)', duration: 0.30 },
                    circle_zoom: { name: 'Zoom Radial', badge: '🎯 Zoom Radial (0.35s)', duration: 0.35 },
                    cut: { name: 'Corte Limpio', badge: 'Corte Limpio', duration: 0.0 },
                };
                const spec = specMap[newType] || specMap.cut;
                if (state.promov3.step4Result && state.promov3.step4Result.timeline && state.promov3.step4Result.timeline[idx]) {
                    state.promov3.step4Result.timeline[idx].transition_out = {
                        type: newType,
                        name: spec.name,
                        badge: spec.badge,
                        duration: spec.duration,
                        reason: 'Ajuste manual del usuario',
                    };
                    const reasonElem = card.querySelector(`#badgeTransitionReason_${idx}`);
                    if (reasonElem) reasonElem.textContent = 'Modificado manualmente';
                    showToast(`Transición del corte #${idx + 1} actualizada a: ${spec.name}`, 'info');
                }
            });
        }

        container.appendChild(card);
    });
}

async function savePromoV3Step4Progress(silent = false) {
    if (!state.promov3 || !state.promov3.step4Result) {
        if (!silent) showToast('No hay datos del montaje del Paso 4 para guardar. Orquesta el montaje primero.', 'warning');
        return;
    }

    const videoPath = (state.promov3.selectedVideo && state.promov3.selectedVideo.path) || (state.promov3.step1Result && state.promov3.step1Result.video_info && state.promov3.step1Result.video_info.path) || '';
    const sessId = state.promov3.sessionId || (state.promov3.step4Result && state.promov3.step4Result.session_id) || '';

    try {
        const res = await fetch('/api/promov3/step4/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                session_id: sessId,
                video_path: videoPath,
                edl: state.promov3.step4Result,
            }),
        });

        const data = await parseJsonResponse(res);
        if (data.status === 'ok') {
            if (data.session_id) {
                state.promov3.sessionId = data.session_id;
                localStorage.setItem('promov3_active_session_id', data.session_id);
            }
            updatePromoV3SessionBanner();
            if (!silent) showToast('💾 Montaje y transiciones del Paso 4 guardados en disco.', 'success');
        } else {
            if (!silent) showToast('Error al guardar Paso 4: ' + (data.detail || 'Error desconocido'), 'error');
        }
    } catch (e) {
        if (!silent) showToast('Error de red al guardar Paso 4: ' + e.message, 'error');
    }
}

function initPromoV3Step4Listeners() {
    const btnRunStep4 = document.getElementById('btnPromoV3RunStep4');
    if (btnRunStep4) {
        btnRunStep4.addEventListener('click', () => runPromoV3Step4());
    }

    const btnSaveStep4 = document.getElementById('btnPromoV3SaveStep4');
    if (btnSaveStep4) {
        btnSaveStep4.addEventListener('click', () => savePromoV3Step4Progress(false));
    }
}

