            state.promov3.captionsHighlightColor = col;
            if (capColorInput) capColorInput.value = col;
            const hexVal = document.getElementById('promov3CaptionsHighlightColorHex');
            const hexPreview = document.getElementById('promov3CaptionsHighlightColorHexPreview');
            if (hexVal) { hexVal.innerText = col; hexVal.style.color = col; }
            if (hexPreview) hexPreview.innerText = col;

            document.querySelectorAll('#promov3PastelPalette .caption-color-chip, #promov3VibrantPalette .caption-color-chip').forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            setPromoV3PreviewMode('captions');
