/* =============================================================================
   STEAM DEALS CAROUSEL (IGD 3:4 FORMAT) CONTROLLER
   ============================================================================= */

const carouselState = {
    currentSubstep: 1,
    theme: 'igd',
    urls: [],
    games: [],
    currency: 'ES',
    headline: 'JUEGOS CO-OP DE OFERTA EN STEAM',
    swipeText: 'DESLIZA PARA VER',
    ctaTitle: '¿CUÁL VAS A JUGAR PRIMERO?',
    ctaSubtitle: 'Guarda este post y síguenos para más recomendaciones',
    useTestBg: true,
    bgImageB64: '',
    bgFilename: '',
    currentSlideIdx: 0,
    totalSlides: 1,
    slidesData: [],
    exportResult: null
};

window.carouselState = carouselState;

function carouselSelectTheme(theme) {
    theme = (theme || 'igd').toLowerCase();
    carouselState.theme = theme;

    const btnIgd = document.getElementById('btnThemeIgd');
    const btnGuam = document.getElementById('btnThemeGuam');
    const badge = document.getElementById('carouselThemeActiveBadge');

    if (btnIgd && btnGuam) {
        if (theme === 'guam') {
            btnGuam.classList.add('active');
            btnGuam.style.background = 'rgba(255, 125, 0, 0.22)';
            btnGuam.style.border = '2px solid #ff7d00';

            btnIgd.classList.remove('active');
            btnIgd.style.background = 'rgba(124, 160, 50, 0.08)';
            btnIgd.style.border = '1px solid rgba(124, 160, 50, 0.35)';

            if (badge) {
                badge.textContent = 'GUAM (Naranja Vibrante)';
                badge.style.background = 'rgba(255, 125, 0, 0.18)';
                badge.style.color = '#ff7d00';
                badge.style.borderColor = 'rgba(255, 125, 0, 0.4)';
            }
        } else {
            btnIgd.classList.add('active');
            btnIgd.style.background = 'rgba(124, 160, 50, 0.22)';
            btnIgd.style.border = '2px solid #7ca032';

            btnGuam.classList.remove('active');
            btnGuam.style.background = 'rgba(255, 125, 0, 0.08)';
            btnGuam.style.border = '1px solid rgba(255, 125, 0, 0.35)';

            if (badge) {
                badge.textContent = 'IGD (Verde Oliva)';
                badge.style.background = 'rgba(124, 160, 50, 0.2)';
                badge.style.color = '#7ca032';
                badge.style.borderColor = 'rgba(124, 160, 50, 0.4)';
            }
        }
    }

    const frame = document.querySelector('.carousel-preview-screen-frame');
    if (frame) {
        if (theme === 'guam') {
            frame.style.background = '#0c0c0e';
            frame.style.borderColor = 'rgba(255, 125, 0, 0.5)';
        } else {
            frame.style.background = '#eae0c8';
            frame.style.borderColor = 'rgba(124, 160, 50, 0.5)';
        }
    }

    if (typeof renderCarouselDots === 'function') {
        renderCarouselDots();
    }

    if (carouselState.currentSubstep === 2 && typeof renderScreenshotSelector === 'function') {
        renderScreenshotSelector();
    }

    if (carouselState.currentSubstep === 3 && carouselState.slidesData && carouselState.slidesData.length > 0) {
        buildCarouselSlideDeck();
        renderCurrentSlidePreview();
    }
}
window.carouselSelectTheme = carouselSelectTheme;

function initCarouselState() {
    carouselValidateUrls();
    carouselToggleTestMode();
    carouselSelectTheme(carouselState.theme || 'igd');

    const hostEl = document.getElementById('headerServerHost');
    if (hostEl && window.location.host) {
        hostEl.textContent = window.location.host;
    }

    const dropzone = document.getElementById('carouselBgDropzone');
    if (dropzone && !dropzone.dataset.dndInit) {
        dropzone.dataset.dndInit = 'true';
        dropzone.addEventListener('dragover', (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropzone.style.borderColor = '#7ca032';
            dropzone.style.background = 'rgba(124, 160, 50, 0.15)';
        });
        dropzone.addEventListener('dragleave', (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropzone.style.borderColor = 'rgba(124, 160, 50, 0.4)';
            dropzone.style.background = 'rgba(15, 26, 13, 0.4)';
        });
        dropzone.addEventListener('drop', (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropzone.style.borderColor = 'rgba(124, 160, 50, 0.4)';
            dropzone.style.background = 'rgba(15, 26, 13, 0.4)';
            if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                const fileInput = document.getElementById('carouselBgFileInput');
                if (fileInput) {
                    fileInput.files = e.dataTransfer.files;
                    carouselHandleBgFile(fileInput);
                }
            }
        });
    }
}
window.initCarouselState = initCarouselState;

function carouselGotoSubstep(stepNum) {
    if (stepNum === 2 && (!carouselState.games || carouselState.games.length === 0)) {
        showToast('Debes scrapear los juegos primero en el Paso 1.', 'warning');
        return;
    }
    if (stepNum === 3) {
        if (!carouselState.games || carouselState.games.length === 0) {
            showToast('Debes scrapear los juegos en el Paso 1 primero.', 'warning');
            return;
        }
        // Verify all games have exactly 2 screenshots selected
        for (let i = 0; i < carouselState.games.length; i++) {
            const g = carouselState.games[i];
            if (!g.selected_screenshots || g.selected_screenshots.length < 2) {
                showToast(`El juego "${g.name}" debe tener 2 capturas seleccionadas.`, 'warning');
                return;
            }
        }
    }

    carouselState.currentSubstep = stepNum;

    const s1 = document.getElementById('carouselSubstep1');
    const s2 = document.getElementById('carouselSubstep2');
    const s3 = document.getElementById('carouselSubstep3');
    if (s1) s1.style.display = (stepNum === 1) ? 'block' : 'none';
    if (s2) s2.style.display = (stepNum === 2) ? 'block' : 'none';
    if (s3) s3.style.display = (stepNum === 3) ? 'block' : 'none';

    document.querySelectorAll('.carousel-step-pill').forEach(p => p.classList.remove('active'));
    const activePill = document.getElementById(`carouselPillStep${stepNum}`);
    if (activePill) activePill.classList.add('active');

    if (stepNum === 3) {
        buildCarouselSlideDeck();
        renderCurrentSlidePreview();
    }
}
window.carouselGotoSubstep = carouselGotoSubstep;

function carouselValidateUrls() {
    const textarea = document.getElementById('carouselSteamUrlsInput');
    const badge = document.getElementById('carouselUrlCounterBadge');
    if (!textarea || !badge) return;

    const raw = textarea.value.trim();
    if (!raw) {
        badge.textContent = '0 juegos (Mínimo 3)';
        badge.style.background = 'rgba(239, 68, 68, 0.15)';
        badge.style.color = '#f87171';
        badge.style.borderColor = 'rgba(239, 68, 68, 0.3)';
        carouselState.urls = [];
        return;
    }

    const lines = raw.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);
    carouselState.urls = lines;
    const count = lines.length;

    if (count % 3 === 0 && count > 0) {
        const slides = count / 3;
        badge.textContent = `✓ ${count} juegos (${slides} ${slides === 1 ? 'slide' : 'slides'} de contenido)`;
        badge.style.background = 'rgba(124, 160, 50, 0.2)';
        badge.style.color = '#7ca032';
        badge.style.borderColor = 'rgba(124, 160, 50, 0.4)';
    } else {
        const needed = 3 - (count % 3);
        badge.textContent = `${count} juegos (Añade ${needed} más para múltiplo de 3)`;
        badge.style.background = 'rgba(245, 158, 11, 0.15)';
        badge.style.color = '#fbbf24';
        badge.style.borderColor = 'rgba(245, 158, 11, 0.3)';
    }
}
window.carouselValidateUrls = carouselValidateUrls;

function carouselToggleTestMode() {
    const checkbox = document.getElementById('carouselCheckTestMode');
    const dropzone = document.getElementById('carouselBgDropzone');
    if (!checkbox) return;
    carouselState.useTestBg = checkbox.checked;
    if (dropzone) {
        dropzone.style.opacity = checkbox.checked ? '0.45' : '1';
    }
}
window.carouselToggleTestMode = carouselToggleTestMode;

async function carouselHandleBgFile(input) {
    if (!input.files || input.files.length === 0) return;
    const file = input.files[0];
    const formData = new FormData();
    formData.append('bg_file', file);

    try {
        const res = await fetch('/api/steam/carousel/upload-bg', {
            method: 'POST',
            body: formData
        });
        const data = await res.json();
        if (!res.ok || !data.success) {
            throw new Error(data.detail || 'Error al subir la imagen');
        }

        carouselState.bgImageB64 = data.bg_image_b64;
        carouselState.bgFilename = data.filename;

        const testCheck = document.getElementById('carouselCheckTestMode');
        if (testCheck) {
            testCheck.checked = false;
            carouselToggleTestMode();
        }

        const prevWrap = document.getElementById('carouselBgPreviewWrap');
        const prevImg = document.getElementById('carouselBgPreviewImg');
        const placeholder = document.getElementById('carouselBgPlaceholder');
        if (prevImg) prevImg.src = data.bg_image_b64;
        if (prevWrap) prevWrap.style.display = 'block';
        if (placeholder) placeholder.style.display = 'none';

        showToast('Fondo 3:4 cargado correctamente', 'success');
    } catch (err) {
        showToast(err.message, 'error');
    }
}
window.carouselHandleBgFile = carouselHandleBgFile;

async function carouselFetchGames() {
    carouselValidateUrls();
    if (carouselState.urls.length === 0) {
        showToast('Por favor introduce al menos 3 URLs de Steam.', 'warning');
        return;
    }
    if (carouselState.urls.length % 3 !== 0) {
        showToast(`La cantidad de juegos (${carouselState.urls.length}) debe ser múltiplo de 3 (3, 6, 9...).`, 'warning');
        return;
    }

    const btn = document.getElementById('btnCarouselFetch');
    const btnIcon = document.getElementById('btnCarouselFetchIcon');
    const btnText = document.getElementById('btnCarouselFetchText');
    if (btn) btn.disabled = true;
    if (btnIcon) btnIcon.textContent = '⏳';
    if (btnText) btnText.textContent = 'Scrapeando Steam API (capturas y precios)...';

    const currSelect = document.getElementById('carouselCurrencySelect');
    carouselState.currency = currSelect ? currSelect.value : 'ES';

    carouselState.headline = (document.getElementById('carouselInputHeadline')?.value || '').trim() || 'JUEGOS CO-OP DE OFERTA EN STEAM';
    carouselState.swipeText = (document.getElementById('carouselInputSwipeText')?.value || '').trim() || 'DESLIZA PARA VER';
    carouselState.ctaTitle = (document.getElementById('carouselInputCtaTitle')?.value || '').trim() || '¿CUÁL VAS A JUGAR PRIMERO?';
    carouselState.ctaSubtitle = (document.getElementById('carouselInputCtaSubtitle')?.value || '').trim() || 'Guarda este post y síguenos para más recomendaciones';

    try {
        const res = await fetch('/api/steam/carousel/fetch', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                urls: carouselState.urls,
                currency: carouselState.currency,
                language: 'spanish'
            })
        });
        const data = await res.json();
        if (!res.ok || !data.success) {
            throw new Error(data.detail || 'Error al obtener datos de Steam');
        }

        carouselState.games = data.games;
        renderScreenshotSelector();
        carouselGotoSubstep(2);
        showToast(`Se han cargado ${data.games.length} juegos con precios y capturas.`, 'success');
    } catch (err) {
        showToast(err.message, 'error');
    } finally {
        if (btn) btn.disabled = false;
        if (btnIcon) btnIcon.textContent = '🔍';
        if (btnText) btnText.textContent = 'Scrapear Capturas y Precios de Steam →';
    }
}
window.carouselFetchGames = carouselFetchGames;

function renderScreenshotSelector() {
    const container = document.getElementById('carouselGamesCardsList');
    if (!container) return;
    container.innerHTML = '';

    carouselState.games.forEach((game, gIdx) => {
        const card = document.createElement('div');
        card.className = 'carousel-game-select-card';
        card.style.background = 'rgba(20, 35, 18, 0.6)';
        card.style.border = '1px solid rgba(124, 160, 50, 0.35)';
        card.style.borderRadius = '10px';
        card.style.padding = '12px 14px';

        let priceBadgeHtml = '';
        const brandColor = (carouselState.theme === 'guam') ? '#ff7d00' : '#7ca032';
        if (game.has_discount && game.initial_formatted) {
            const discountBadge = (game.discount_percent && game.discount_percent > 0)
                ? `<span style="font-size: 10px; font-weight: 800; background: ${brandColor}; color: #ffffff; padding: 1.5px 6px; border-radius: 4px; box-shadow: 0 1px 4px rgba(0,0,0,0.3); line-height: 1.1;">-${escapeHtml(game.discount_percent)}%</span>`
                : '';
            priceBadgeHtml = `
                <div style="display: inline-flex; align-items: center; gap: 7px; background: rgba(0,0,0,0.5); padding: 3px 8px; border-radius: 6px; border: 1px solid rgba(124, 160, 50, 0.4);">
                    <span style="font-size: 11px; text-decoration: line-through; color: rgba(253, 243, 218, 0.5);">${escapeHtml(game.initial_formatted)}</span>
                    ${discountBadge}
                    <span style="font-size: 12px; font-weight: 800; color: #fdf3da;">${escapeHtml(game.final_formatted)}</span>
                </div>
            `;
        } else if (game.final_formatted) {
            priceBadgeHtml = `
                <div style="display: inline-flex; align-items: center; background: rgba(0,0,0,0.5); padding: 3px 8px; border-radius: 6px; border: 1px solid rgba(124, 160, 50, 0.4);">
                    <span style="font-size: 12px; font-weight: 800; color: ${brandColor};">${escapeHtml(game.final_formatted)}</span>
                </div>
            `;
        }

        const selectedCount = (game.selected_screenshots || []).length;
        const countStatusColor = (selectedCount === 2) ? '#7ca032' : '#f87171';

        card.innerHTML = `
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; flex-wrap: wrap; gap: 6px;">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <span style="font-size: 13.5px; font-weight: 700; color: #fdf3da;">${gIdx + 1}. ${escapeHtml(game.name)}</span>
                    ${safeHttpUrl(game.store_url) ? `<a href="${escapeHtml(safeHttpUrl(game.store_url))}" target="_blank" rel="noopener noreferrer" style="color: #7ca032; font-size: 11px; text-decoration: none; opacity: 0.8;" title="Ver en Steam">🔗 Steam</a>` : ''}
                </div>
                <div style="display: flex; align-items: center; gap: 10px;">
                    ${priceBadgeHtml}
                    <span id="gameCountBadge_${gIdx}" style="font-size: 11.5px; font-weight: 700; color: ${countStatusColor}; background: rgba(0,0,0,0.4); padding: 2px 8px; border-radius: 4px; border: 1px solid ${countStatusColor};">
                        ${selectedCount} / 2 seleccionadas
                    </span>
                </div>
            </div>
            <div class="carousel-shots-strip" id="gameShotsStrip_${gIdx}" style="display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px;">
                ${(game.screenshots || []).map((s, sIdx) => {
                    const isSelected = (game.selected_screenshots || []).includes(s.full);
                    const borderStyle = isSelected ? '2px solid #7ca032' : '1px solid rgba(255,255,255,0.1)';
                    const opacityStyle = isSelected ? '1' : '0.65';
                    const checkmarkDisplay = isSelected ? 'flex' : 'none';
                    return `
                        <div class="carousel-shot-item" onclick="carouselToggleScreenshot(${gIdx}, ${sIdx})" style="position: relative; aspect-ratio: 16/9; border-radius: 6px; overflow: hidden; cursor: pointer; border: ${borderStyle}; opacity: ${opacityStyle}; transition: all 0.15s; background: #000;">
                            <img src="${escapeHtml(s.thumb || s.full)}" style="width: 100%; height: 100%; object-fit: cover;" />
                            <div class="carousel-shot-check" style="display: ${checkmarkDisplay}; position: absolute; top: 4px; right: 4px; width: 20px; height: 20px; background: #7ca032; color: #121e10; border-radius: 50%; font-size: 12px; font-weight: 900; align-items: center; justify-content: center; box-shadow: 0 2px 5px rgba(0,0,0,0.5);">
                                ✓
                            </div>
                        </div>
                    `;
                }).join('')}
            </div>
        `;
        container.appendChild(card);
    });
}
window.renderScreenshotSelector = renderScreenshotSelector;

function carouselOnHeadlineChange() {
    const input = document.getElementById('carouselInputHeadline');
    if (!input) return;
    carouselState.headline = input.value.trim() || 'JUEGOS CO-OP DE OFERTA EN STEAM';
    if (carouselState.currentSubstep === 3) {
        buildCarouselSlideDeck();
        renderCurrentSlidePreview();
    }
}
window.carouselOnHeadlineChange = carouselOnHeadlineChange;

function carouselToggleScreenshot(gameIdx, shotIdx) {
    const game = carouselState.games[gameIdx];
    if (!game || !game.screenshots || !game.screenshots[shotIdx]) return;

    const shotUrl = game.screenshots[shotIdx].full;
    if (!game.selected_screenshots) game.selected_screenshots = [];

    const existingIdx = game.selected_screenshots.indexOf(shotUrl);
    if (existingIdx !== -1) {
        game.selected_screenshots.splice(existingIdx, 1);
    } else {
        if (game.selected_screenshots.length >= 2) {
            game.selected_screenshots[1] = shotUrl;
        } else {
            game.selected_screenshots.push(shotUrl);
        }
    }

    renderScreenshotSelector();
}
window.carouselToggleScreenshot = carouselToggleScreenshot;

function buildCarouselSlideDeck() {
    const deck = [];
    const currentTheme = carouselState.theme || 'igd';

    const chunkSize = 3;
    const totalContentSlides = Math.ceil(carouselState.games.length / chunkSize);
    const totalDeckSlides = 1 + totalContentSlides + 1; // 1 cover + N content + 1 closing

    deck.push({
        type: 'cover',
        theme: currentTheme,
        title: 'Portada',
        headline: carouselState.headline,
        swipe_text: carouselState.swipeText,
        bg_image_b64: carouselState.bgImageB64,
        use_test_bg: carouselState.useTestBg,
        total_slides: totalDeckSlides
    });

    for (let i = 0; i < carouselState.games.length; i += chunkSize) {
        const chunk = carouselState.games.slice(i, i + chunkSize);
        deck.push({
            type: 'games',
            theme: currentTheme,
            title: `Juegos (${i + 1}-${i + chunk.length})`,
            games_chunk: chunk,
            slide_index: Math.floor(i / chunkSize) + 1,
            total_slides: totalContentSlides,
            headline: carouselState.headline
        });
    }

    deck.push({
        type: 'closing',
        theme: currentTheme,
        title: 'Cierre',
        cta_title: carouselState.ctaTitle,
        cta_subtitle: carouselState.ctaSubtitle,
        bg_image_b64: carouselState.bgImageB64,
        use_test_bg: carouselState.useTestBg,
        total_slides: totalDeckSlides
    });

    carouselState.slidesData = deck;
    carouselState.totalSlides = deck.length;
    carouselState.currentSlideIdx = 0;

    renderCarouselDots();
}
window.buildCarouselSlideDeck = buildCarouselSlideDeck;

function renderCarouselDots() {
    const dotsContainer = document.getElementById('carouselSlideDots');
    if (!dotsContainer) return;
    dotsContainer.innerHTML = '';
    const activeColor = (carouselState.theme === 'guam') ? '#ff7d00' : '#7ca032';

    for (let i = 0; i < carouselState.totalSlides; i++) {
        const dot = document.createElement('span');
        dot.style.display = 'inline-block';
        dot.style.width = (i === carouselState.currentSlideIdx) ? '18px' : '7px';
        dot.style.height = '7px';
        dot.style.borderRadius = '999px';
        dot.style.background = (i === carouselState.currentSlideIdx) ? activeColor : 'rgba(253, 243, 218, 0.3)';
        dot.style.cursor = 'pointer';
        dot.style.transition = 'all 0.2s';
        dot.onclick = () => {
            carouselState.currentSlideIdx = i;
            renderCurrentSlidePreview();
        };
        dotsContainer.appendChild(dot);
    }
}
window.renderCarouselDots = renderCarouselDots;

async function renderCurrentSlidePreview() {
    const slide = carouselState.slidesData[carouselState.currentSlideIdx];
    if (!slide) return;

    const label = document.getElementById('carouselSlideLabel');
    if (label) {
        label.textContent = `Diapositiva ${carouselState.currentSlideIdx + 1} de ${carouselState.totalSlides} (${slide.title})`;
    }

    renderCarouselDots();

    const iframe = document.getElementById('carouselPreviewIframe');
    if (!iframe) return;

    iframe.style.position = 'absolute';
    iframe.style.top = '0';
    iframe.style.left = '0';
    iframe.style.width = '1080px';
    iframe.style.height = '1440px';
    iframe.style.transformOrigin = '0 0';
    iframe.style.transform = 'scale(0.3888888888888889)';

    try {
        const res = await fetch('/api/steam/carousel/preview-slide', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                slide_type: slide.type,
                theme: slide.theme || carouselState.theme || 'igd',
                headline: slide.headline,
                swipe_text: slide.swipe_text,
                cta_title: slide.cta_title,
                cta_subtitle: slide.cta_subtitle,
                bg_image_b64: slide.bg_image_b64,
                use_test_bg: slide.use_test_bg,
                games_chunk: slide.games_chunk,
                slide_index: slide.slide_index,
                total_slides: slide.total_slides || carouselState.totalSlides || 5
            })
        });
        const data = await res.json();
        if (res.ok && data.html) {
            iframe.srcdoc = data.html;
        }
    } catch (err) {
        console.error('Error fetching preview slide:', err);
    }
}
window.renderCurrentSlidePreview = renderCurrentSlidePreview;

function carouselPrevSlide() {
    if (carouselState.currentSlideIdx > 0) {
        carouselState.currentSlideIdx--;
        renderCurrentSlidePreview();
    }
}
window.carouselPrevSlide = carouselPrevSlide;

function carouselNextSlide() {
    if (carouselState.currentSlideIdx < carouselState.totalSlides - 1) {
        carouselState.currentSlideIdx++;
        renderCurrentSlidePreview();
    }
}
window.carouselNextSlide = carouselNextSlide;

async function carouselExportAll() {
    const btn = document.getElementById('btnCarouselExport');
    const btnIcon = document.getElementById('btnCarouselExportIcon');
    const btnText = document.getElementById('btnCarouselExportText');
    if (btn) btn.disabled = true;
    if (btnIcon) btnIcon.textContent = '⏳';
    if (btnText) btnText.textContent = 'Exportando carrusel en 4K Ultra HD...';

    showToast('Exportando diapositivas en 4K Ultra HD (2880x3840) con headless Chrome...', 'info');

    try {
        const payload = {
            theme: carouselState.theme || 'igd',
            headline: carouselState.headline,
            swipe_text: carouselState.swipeText,
            cta_title: carouselState.ctaTitle,
            cta_subtitle: carouselState.ctaSubtitle,
            bg_image_b64: carouselState.bgImageB64,
            use_test_bg: carouselState.useTestBg,
            scale_factor: 2.6666667,
            games: carouselState.games
        };

        const res = await fetch('/api/steam/carousel/export', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const data = await res.json();
        if (!res.ok || !data.success) {
            throw new Error(data.detail || 'Error al exportar diapositivas');
        }

        carouselState.exportResult = data;
        displayExportResult(data);
        showToast('¡Carrusel 4K exportado correctamente!', 'success');
    } catch (err) {
        showToast(err.message, 'error');
    } finally {
        if (btn) btn.disabled = false;
        if (btnIcon) btnIcon.textContent = '⬇️';
        if (btnText) btnText.textContent = 'Descargar Carrusel 4K (PNGs + ZIP)';
    }
}
window.carouselExportAll = carouselExportAll;

function displayExportResult(data) {
    const box = document.getElementById('carouselExportResultBox');
    const folderInfo = document.getElementById('carouselExportFolderInfo');
    const zipBtn = document.getElementById('carouselZipDownloadBtn');
    const grid = document.getElementById('carouselExportSlidesGrid');
    if (!box) return;

    if (folderInfo) {
        folderInfo.textContent = `Carpeta: output/${data.folder_name} (${data.total_slides} imágenes generadas)`;
    }
    if (zipBtn) {
        zipBtn.href = data.zip_url;
        zipBtn.download = `${data.folder_name}.zip`;
    }
    if (grid && data.slides) {
        grid.innerHTML = '';
        data.slides.forEach(s => {
            const item = document.createElement('div');
            item.style.flex = '0 0 110px';
            item.style.background = 'rgba(0,0,0,0.4)';
            item.style.border = '1px solid rgba(124, 160, 50, 0.4)';
            item.style.borderRadius = '8px';
            item.style.padding = '6px';
            item.style.textAlign = 'center';

            item.innerHTML = `
                <div style="aspect-ratio: 3/4; border-radius: 4px; overflow: hidden; margin-bottom: 6px;">
                    <img src="${escapeHtml(s.url)}" style="width: 100%; height: 100%; object-fit: cover;" />
                </div>
                <div style="font-size: 11px; font-weight: 700; color: #fdf3da; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 4px;">
                    ${escapeHtml(s.title)}
                </div>
                <a href="${escapeHtml(s.url)}" download="${escapeHtml(s.filename)}" class="wizard-btn-secondary" style="display: block; font-size: 10px; padding: 3px 0; text-decoration: none; border-radius: 4px;">
                    Descargar PNG
                </a>
            `;
            grid.appendChild(item);
        });
    }

    box.style.display = 'block';
    box.scrollIntoView({ behavior: 'smooth' });
}
window.displayExportResult = displayExportResult;


/* =============================================================================
   SET-UP TRAILER: Real-Time Perspective Calibration Module
   ============================================================================= */

const setupTrailerState = {
    initialized: false,
    listenersAttached: false,
    nativeWidth: 720,
    nativeHeight: 1280,
    sourceW: 720,
    sourceH: 405, // 16:9 source aspect ratio (720x405)
    backgroundVideo: "/static/setupbackground/setup-background-def.mp4",
    trailerVideo: null,
    cameraEffectIntensity: 0.5,
    gameName: '',
    showGameTitle: true,
    titleFontSize: 28,
    titleOffsetY: 18,
    variant: "classic",
    gameplayFit: "contain",
    gameLogoEnabled: true,
    narrationEnabled: false,
    narrationLayout: "card",
    narrationCta: "Follow {channel} for more games.",
    narrationText: "",
    backgroundAudioVolume: .12,
    gameLogoScale: 1,
    entranceMode: "desktop",
    actionLeadSeconds: 1.2,
    highlightHook: false,
    openingMode: "original",
    openingStartSeconds: 0,
    titleRevealMode: "immediate",
    titleRevealDelay: 1,
    introSeconds: null,
    transitionSeconds: 3,
    entrySfxEnabled: true,
    entrySfxVolume: .25,
    cardEnabled: false,
    cardText: "",
    cardPreset: "NextLoot",
    defaultCorners: {
        tl: { x: -36.8, y: 329.1 },
        tr: { x: 773.8, y: 445.9 },
        br: { x: 785.2, y: 843.8 },
        bl: { x: -41.4, y: 956.1 }
    },
    corners: {
        tl: { x: -36.8, y: 329.1 },
        tr: { x: 773.8, y: 445.9 },
        br: { x: 785.2, y: 843.8 },
        bl: { x: -41.4, y: 956.1 }
    },
    lastScale: 0.48,
    resizeObserver: null,
    _toastTimeout: null,
    _autoSaveTimer: null
};
window.setupTrailerState = setupTrailerState;

function computeProjectiveTransform(srcW, srcH, p0, p1, p2, p3) {
    const x0 = p0.x, y0 = p0.y;
    const x1 = p1.x, y1 = p1.y;
    const x2 = p2.x, y2 = p2.y;
    const x3 = p3.x, y3 = p3.y;

    const dx1 = x1 - x2;
    const dy1 = y1 - y2;
    const dx2 = x3 - x2;
    const dy2 = y3 - y2;
    const sx = x0 - x1 + x2 - x3;
    const sy = y0 - y1 + y2 - y3;

    let a31 = 0, a32 = 0, a33 = 1;
    let a11 = 1, a12 = 0, a13 = x0;
    let a21 = 0, a22 = 1, a23 = y0;

    const det = dx1 * dy2 - dx2 * dy1;
    if (Math.abs(det) > 1e-7) {
        a31 = (sx * dy2 - sy * dx2) / det;
        a32 = (dx1 * sy - dy1 * sx) / det;
        a11 = x1 - x0 + a31 * x1;
        a12 = x3 - x0 + a32 * x3;
        a13 = x0;
        a21 = y1 - y0 + a31 * y1;
        a22 = y3 - y0 + a32 * y3;
        a23 = y0;
    }

    const h00 = a11 / srcW;
    const h01 = a12 / srcH;
    const h02 = a13;
    const h10 = a21 / srcW;
    const h11 = a22 / srcH;
    const h12 = a23;
    const h20 = a31 / srcW;
    const h21 = a32 / srcH;
    const h22 = a33;

    return `matrix3d(${h00.toFixed(7)}, ${h10.toFixed(7)}, 0, ${h20.toFixed(7)}, ${h01.toFixed(7)}, ${h11.toFixed(7)}, 0, ${h21.toFixed(7)}, 0, 0, 1, 0, ${h02.toFixed(4)}, ${h12.toFixed(4)}, 0, ${h22.toFixed(4)})`;
}

function getSetupStageScale() {
    const stage = document.getElementById('setupTrailerStage');
    if (stage) {
        const rect = stage.getBoundingClientRect();
        if (rect.width > 10) {
            setupTrailerState.lastScale = rect.width / setupTrailerState.nativeWidth;
            return setupTrailerState.lastScale;
        }
        if (stage.offsetWidth > 10) {
            setupTrailerState.lastScale = stage.offsetWidth / setupTrailerState.nativeWidth;
            return setupTrailerState.lastScale;
        }
    }
    const vh = window.innerHeight || 800;
    const computedH = Math.min(vh * 0.72, 760);
    const computedW = computedH * 9 / 16;
    if (computedW > 10) {
        setupTrailerState.lastScale = computedW / setupTrailerState.nativeWidth;
        return setupTrailerState.lastScale;
    }
    return setupTrailerState.lastScale || 0.48;
}

function updateSetupTrailerVisuals() {
    const stage = document.getElementById('setupTrailerStage');
    const warpContainer = document.getElementById('setupWarpContainer');
    if (!stage || !warpContainer) return;

    const scale = getSetupStageScale();
    const c = setupTrailerState.corners;

    // 1. Destination points in stage CSS pixels (calibrated monitor corners)
    const p0 = { x: c.tl.x * scale, y: c.tl.y * scale };
    const p1 = { x: c.tr.x * scale, y: c.tr.y * scale };
    const p2 = { x: c.br.x * scale, y: c.br.y * scale };
    const p3 = { x: c.bl.x * scale, y: c.bl.y * scale };

    // 2. Compute 3D Homography Matrix and apply to container
    const matrix = computeProjectiveTransform(
        setupTrailerState.sourceW,
        setupTrailerState.sourceH,
        p0, p1, p2, p3
    );

    if (matrix) {
        warpContainer.style.transformOrigin = '0 0';
        warpContainer.style.transform = matrix;
        warpContainer.style.opacity = '1';
    }

    // 3. Angled Game Title on Top of Monitor
    const titleContainer = document.getElementById('setupGameTitleContainer');
    const titleText = document.getElementById('setupGameTitleText');
    if (titleContainer && titleText) {
        const titleStr = (setupTrailerState.gameName || '').trim();
        if (setupTrailerState.showGameTitle && titleStr && setupTrailerState.titleRevealMode === 'immediate') {
            titleText.textContent = titleStr;
            titleContainer.style.display = 'flex';

            // Top edge vector (TL to TR in native 720x1280 space)
            const dx = c.tr.x - c.tl.x;
            const dy = c.tr.y - c.tl.y;
            const angleRad = Math.atan2(dy, dx);
            const angleDeg = angleRad * (180 / Math.PI);

            // Midpoint of monitor top edge
            const midX = (c.tl.x + c.tr.x) / 2;
            const midY = (c.tl.y + c.tr.y) / 2;

            // Perpendicular unit vector pointing UP from monitor top edge
            const gapNative = setupTrailerState.titleOffsetY !== undefined ? setupTrailerState.titleOffsetY : 18;
            const anchorNativeX = midX + gapNative * Math.sin(angleRad);
            const anchorNativeY = midY - gapNative * Math.cos(angleRad);

            // Convert to current stage CSS coordinates
            const anchorStageX = anchorNativeX * scale;
            const anchorStageY = anchorNativeY * scale;

            titleContainer.style.left = `${anchorStageX.toFixed(2)}px`;
            titleContainer.style.top = `${anchorStageY.toFixed(2)}px`;
            titleContainer.style.transformOrigin = '0 0';
            titleContainer.style.transform = `rotate(${angleDeg.toFixed(3)}deg) translate(-50%, -100%)`;

            const baseFontSize = setupTrailerState.titleFontSize || 28;
            const fontSizePx = Math.max(10, Math.round(baseFontSize * scale));
            titleText.style.fontSize = `${fontSizePx}px`;

            const stageW = stage.offsetWidth || (setupTrailerState.nativeWidth * scale);
            titleContainer.style.maxWidth = `${Math.round(stageW * 0.85)}px`;
        } else {
            titleContainer.style.display = 'none';
        }
    }
}
window.updateSetupTrailerVisuals = updateSetupTrailerVisuals;

function showSetupTrailerToast(msg, isError = false) {
    const toast = document.getElementById('setupTrailerToast');
    if (!toast) return;
    toast.textContent = msg;
    toast.style.borderColor = isError ? '#ef4444' : '#38bdf8';
    toast.style.display = 'block';

    if (setupTrailerState._toastTimeout) {
        clearTimeout(setupTrailerState._toastTimeout);
    }
    setupTrailerState._toastTimeout = setTimeout(() => {
        toast.style.display = 'none';
    }, 3200);
}

async function loadSetupTrailerConfig() {
    try {
        const resp = await fetch('/api/setup-trailer/config');
        if (resp.ok) {
            const data = await resp.json();
            if (data && data.success && data.config) {
                setupTrailerState.highlightHook = data.config.highlight_hook === true;
                setupTrailerState.openingMode = ['auto','manual'].includes(data.config.opening_mode) ? data.config.opening_mode : 'original';
                setupTrailerState.openingStartSeconds = data.config.opening_start_seconds ?? 0;
                setupTrailerState.titleRevealMode = ['after_entry','outro'].includes(data.config.title_reveal_mode) ? data.config.title_reveal_mode : 'immediate';
                setupTrailerState.titleRevealDelay = data.config.title_reveal_delay ?? 1;
                setupTrailerState.entranceMode = data.config.entrance_mode === 'action_match' ? 'action_match' : 'desktop';
                setupTrailerState.actionLeadSeconds = data.config.action_lead_seconds ?? 1.2;
                setupTrailerState.gameLogoEnabled = true;
                setupTrailerState.gameLogoScale = data.config.game_logo_scale ?? 1;
                setupTrailerState.introSeconds = data.config.intro_seconds ?? null;
                setupTrailerState.transitionSeconds = data.config.transition_seconds ?? 3;
                setupTrailerState.entrySfxEnabled = data.config.entry_sfx_enabled !== false;
                setupTrailerState.entrySfxVolume = data.config.entry_sfx_volume ?? .25;
                setupTrailerState.narrationEnabled = data.config.narration_enabled === true;
                setupTrailerState.narrationLayout = data.config.narration_layout === "clean" ? "clean" : "card";
                setupTrailerState.narrationCta = data.config.narration_cta ?? "Follow {channel} for more games.";
                setupTrailerState.narrationText = data.config.narration_text || "";
                setupTrailerState.backgroundAudioVolume = data.config.background_audio_volume ?? .12;
                setupTrailerState.variant = data.config.variant === 'monitor_dive' ? 'monitor_dive' : 'classic';
                setupTrailerState.gameplayFit = data.config.gameplay_fit === 'cover' ? 'cover' : 'contain';
                setupTrailerState.cardEnabled = data.config.card_enabled === true;
                setupTrailerState.cardText = data.config.card_text || '';
                setupTrailerState.cardPreset = data.config.card_preset || 'NextLoot';
                const enabled = document.getElementById('setupTrailerCardEnabled');
                const text = document.getElementById('setupTrailerCardText');
                const preset = document.getElementById('setupTrailerCardPreset');
                if (enabled) enabled.checked = setupTrailerState.cardEnabled;
                if (text) text.value = setupTrailerState.cardText;
                if (preset) {
                    preset.replaceChildren();
                    const profiles = await (await fetch('/api/presets')).json();
                    for (const name of Object.keys(profiles)) {
                        const option = document.createElement('option');
                        option.value = name;
                        option.textContent = name;
                        preset.appendChild(option);
                    }
                    preset.value = setupTrailerState.cardPreset;
                }
                setupTrailerUpdateVariantControls();
                if (data.config.corners) {
                    setupTrailerState.corners = data.config.corners;
                }
                if (data.config.background_video) {
                    setupTrailerState.backgroundVideo = data.config.background_video;
                    const bgVideo = document.getElementById('setupBgVideo');
                    if (bgVideo && bgVideo.src !== data.config.background_video) {
                        bgVideo.src = data.config.background_video;
                    }
                }
                if (data.config.trailer_video) {
                    setupTrailerState.trailerVideo = data.config.trailer_video;
                    const overlayVideo = document.getElementById('setupOverlayVideo');
                    if (overlayVideo) {
                        overlayVideo.src = data.config.trailer_video;
                        overlayVideo.load();
                    }
                }
                bindSetupTrailerVideoSync();
                if (data.config.camera_effect_intensity !== undefined) {
                    setupTrailerSetIntensity(data.config.camera_effect_intensity, false);
                }
                if (data.config.game_name !== undefined) {
                    setupTrailerState.gameName = data.config.game_name || '';
                    const titleInput = document.getElementById('setupTrailerGameName');
                    if (titleInput) titleInput.value = setupTrailerState.gameName;
                }
                if (data.config.show_game_title !== undefined) {
                    setupTrailerState.showGameTitle = !!data.config.show_game_title;
                    const eyeIcon = document.getElementById('setupTitleEyeIcon');
                    const eyeText = document.getElementById('setupTitleEyeText');
                    if (eyeIcon) eyeIcon.textContent = setupTrailerState.showGameTitle ? '👁️' : '🙈';
                    if (eyeText) eyeText.textContent = setupTrailerState.showGameTitle ? 'Visible' : 'Oculto';
                    const btnTitle = document.getElementById('btnSetupTrailerToggleTitle');
                    if (btnTitle) btnTitle.style.opacity = setupTrailerState.showGameTitle ? '1' : '0.6';
                }
                if (data.config.title_font_size !== undefined) {
                    const fSize = parseInt(data.config.title_font_size) || 28;
                    setupTrailerState.titleFontSize = fSize;
                    const slider = document.getElementById('setupTrailerFontSizeSlider');
                    if (slider) slider.value = fSize;
                    const valLabel = document.getElementById('setupTrailerFontSizeVal');
                    if (valLabel) valLabel.textContent = `${fSize}px`;
                }
                if (data.config.title_offset_y !== undefined) {
                    const hVal = parseInt(data.config.title_offset_y);
                    setupTrailerState.titleOffsetY = isNaN(hVal) ? 18 : hVal;
                    const slider = document.getElementById('setupTrailerHeightSlider');
                    if (slider) slider.value = setupTrailerState.titleOffsetY;
                    const valLabel = document.getElementById('setupTrailerHeightVal');
                    if (valLabel) valLabel.textContent = `${setupTrailerState.titleOffsetY}px`;
                }
                if (typeof setupTrailerLoadScenes === 'function') await setupTrailerLoadScenes();
                updateSetupTrailerVisuals();
                return;
            }
        }
    } catch (e) {
        console.warn('Could not load setup trailer config from server:', e);
    }

    if (typeof setupTrailerLoadScenes === 'function') await setupTrailerLoadScenes();
    updateSetupTrailerVisuals();
}

function setupTrailerAutoSaveConfig() {
    clearTimeout(setupTrailerState._autoSaveTimer);
    setupTrailerState._autoSaveTimer = setTimeout(() => {
        setupTrailerSaveConfig(true);
    }, 600);
}

async function setupTrailerSaveConfig(silent = false) {
    const payload = {
        background_video: setupTrailerState.backgroundVideo || "/static/setupbackground/setup-background-def.mp4",
        trailer_video: setupTrailerState.trailerVideo || undefined,
        camera_effect_intensity: setupTrailerState.cameraEffectIntensity,
        game_name: setupTrailerState.gameName || '',
        show_game_title: setupTrailerState.showGameTitle !== false,
        title_font_size: setupTrailerState.titleFontSize || 28,
        title_offset_y: setupTrailerState.titleOffsetY !== undefined ? setupTrailerState.titleOffsetY : 18,
        card_enabled: setupTrailerState.cardEnabled,
        card_text: setupTrailerState.cardText,
        card_preset: setupTrailerState.cardPreset,
        intro_seconds: setupTrailerState.introSeconds,
        transition_seconds: setupTrailerState.transitionSeconds,
        entry_sfx_enabled: setupTrailerState.entrySfxEnabled,
        entry_sfx_volume: setupTrailerState.entrySfxVolume,
        narration_enabled: setupTrailerState.narrationEnabled,
        narration_layout: setupTrailerState.narrationLayout,
        narration_cta: setupTrailerState.narrationCta,
        narration_text: setupTrailerState.narrationText,
        background_audio_volume: setupTrailerState.backgroundAudioVolume,
        highlight_hook: setupTrailerState.highlightHook,
        opening_mode: setupTrailerState.openingMode,
        opening_start_seconds: setupTrailerState.openingStartSeconds,
        title_reveal_mode: setupTrailerState.titleRevealMode,
        title_reveal_delay: setupTrailerState.titleRevealDelay,
        entrance_mode: setupTrailerState.entranceMode,
        action_lead_seconds: setupTrailerState.actionLeadSeconds,
        game_logo_enabled: setupTrailerState.gameLogoEnabled,
        game_logo_scale: setupTrailerState.gameLogoScale,
        variant: setupTrailerState.variant,
        gameplay_fit: setupTrailerState.gameplayFit,
        native_width: setupTrailerState.nativeWidth,
        native_height: setupTrailerState.nativeHeight,
        corners: setupTrailerState.corners
    };

    try {
        const resp = await fetch('/api/setup-trailer/config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        if (resp.ok && !silent) {
            showSetupTrailerToast('✅ Configuración guardada');
        }
    } catch (err) {
        if (!silent) console.error('Error saving setup trailer config:', err);
    }
}
window.setupTrailerSaveConfig = setupTrailerSaveConfig;

function attachSetupTrailerListeners() {
    const stage = document.getElementById('setupTrailerStage');

    window.addEventListener('resize', () => {
        updateSetupTrailerVisuals();
    });

    if (window.ResizeObserver && stage) {
        setupTrailerState.resizeObserver = new ResizeObserver(() => {
            updateSetupTrailerVisuals();
        });
        setupTrailerState.resizeObserver.observe(stage);
    }
}

function bindSetupTrailerVideoSync() {
    const bgVideo = document.getElementById('setupBgVideo');
    const overlayVideo = document.getElementById('setupOverlayVideo');
    if (!overlayVideo) return;

    overlayVideo.loop = false;
    if (bgVideo) {
        bgVideo.loop = false;
        bgVideo.muted = true;
    }

    const updatePlayIcons = (isPaused, isEnded) => {
        const icon = document.getElementById('setupPlayBtnIcon');
        const iconBottom = document.getElementById('setupPlayBtnIconBottom');
        const iconStr = isEnded ? '🔄' : (isPaused ? '▶️' : '⏸️');
        if (icon) icon.textContent = iconStr;
        if (iconBottom) iconBottom.textContent = iconStr;
    };

    overlayVideo.onended = () => {
        overlayVideo.pause();
        if (bgVideo) bgVideo.pause();
        const replayOverlay = document.getElementById('setupReplayOverlay');
        if (replayOverlay) replayOverlay.style.display = 'flex';
        updatePlayIcons(true, true);
    };

    if (bgVideo) {
        bgVideo.onended = () => {
            if (overlayVideo && !overlayVideo.paused && !overlayVideo.ended) {
                bgVideo.currentTime = 0;
                bgVideo.play().catch(() => {});
            } else {
                bgVideo.pause();
            }
        };
    }

    overlayVideo.onplay = () => {
        const replayOverlay = document.getElementById('setupReplayOverlay');
        if (replayOverlay) replayOverlay.style.display = 'none';
        updatePlayIcons(false, false);
        if (bgVideo && bgVideo.paused && !overlayVideo.ended) {
            bgVideo.play().catch(() => {});
        }
    };

    overlayVideo.onpause = () => {
        if (!overlayVideo.ended) {
            updatePlayIcons(true, false);
        }
        if (bgVideo && !bgVideo.paused) {
            bgVideo.pause();
        }
    };

    overlayVideo.onseeking = () => {
        if (bgVideo && bgVideo.duration) {
            bgVideo.currentTime = overlayVideo.currentTime % bgVideo.duration;
        }
    };
}
window.bindSetupTrailerVideoSync = bindSetupTrailerVideoSync;

function setupTrailerTogglePlay() {
    const overlayVideo = document.getElementById('setupOverlayVideo');
    const bgVideo = document.getElementById('setupBgVideo');
    if (!overlayVideo) return;

    const isNearEnd = overlayVideo.ended || (overlayVideo.duration && overlayVideo.currentTime >= overlayVideo.duration - 0.2);

    if (isNearEnd) {
        overlayVideo.currentTime = 0;
        if (bgVideo) bgVideo.currentTime = 0;
        const replayOverlay = document.getElementById('setupReplayOverlay');
        if (replayOverlay) replayOverlay.style.display = 'none';
        overlayVideo.play().catch(() => {});
        if (bgVideo) bgVideo.play().catch(() => {});
        return;
    }

    if (overlayVideo.paused) {
        overlayVideo.play().catch(() => {});
        if (bgVideo) bgVideo.play().catch(() => {});
    } else {
        overlayVideo.pause();
        if (bgVideo) bgVideo.pause();
    }
}
window.setupTrailerTogglePlay = setupTrailerTogglePlay;

function initSetupTrailerCalibration() {
    const bgVideo = document.getElementById('setupBgVideo');
    const overlayVideo = document.getElementById('setupOverlayVideo');

    if (bgVideo) {
        bgVideo.loop = false;
        bgVideo.muted = true;
        bgVideo.pause();
    }
    if (overlayVideo) {
        overlayVideo.loop = false;
        overlayVideo.muted = true;
        overlayVideo.pause();
    }

    bindSetupTrailerVideoSync();

    if (!setupTrailerState.listenersAttached) {
        setupTrailerState.listenersAttached = true;
        attachSetupTrailerListeners();
    }

    loadSetupTrailerConfig();

    updateSetupTrailerVisuals();
    requestAnimationFrame(() => updateSetupTrailerVisuals());
    setTimeout(updateSetupTrailerVisuals, 50);
    setTimeout(updateSetupTrailerVisuals, 150);
    setTimeout(updateSetupTrailerVisuals, 350);
    setTimeout(updateSetupTrailerVisuals, 600);
}
window.initSetupTrailerCalibration = initSetupTrailerCalibration;

async function setupTrailerDownloadYoutube() {
    const input = document.getElementById('setupTrailerYtUrl');
    const btn = document.getElementById('btnSetupTrailerDownload');
    const icon = document.getElementById('setupYtBtnIcon');
    const text = document.getElementById('setupYtBtnText');
    const status = document.getElementById('setupYtStatus');
    const statusText = document.getElementById('setupYtStatusText');
    const overlayVideo = document.getElementById('setupOverlayVideo');
    const bgVideo = document.getElementById('setupBgVideo');

    const url = input ? input.value.trim() : '';
    if (!url) {
        showSetupTrailerToast('⚠️ Pega el enlace de YouTube del tráiler', true);
        if (input) input.focus();
        return;
    }

    if (!url.toLowerCase().includes('youtube.com') && !url.toLowerCase().includes('youtu.be')) {
        showSetupTrailerToast('⚠️ El enlace no parece ser un vídeo de YouTube válido', true);
        if (input) input.focus();
        return;
    }

    if (btn) btn.disabled = true;
    if (icon) icon.textContent = '⏳';
    if (text) text.textContent = 'Descargando...';
    if (status) status.style.display = 'flex';
    if (statusText) statusText.textContent = 'Descargando y optimizando tráiler con yt-dlp... (puede tardar unos segundos)';

    try {
        const resp = await fetch('/api/setup-trailer/load-youtube', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                url: url,
                intensity: setupTrailerState.cameraEffectIntensity
            })
        });

        if (!resp.ok) {
            let errorMsg = `Error del servidor (${resp.status})`;
            try {
                const errData = await resp.json();
                if (errData && errData.detail) errorMsg = errData.detail;
            } catch (e) {}
            throw new Error(errorMsg);
        }

        const data = await resp.json();
        if (!data || !data.url) {
            throw new Error('Respuesta no válida del servidor al procesar el tráiler');
        }

        setupTrailerState.trailerVideo = data.url;

        if (data.game_name) {
            setupTrailerState.gameName = data.game_name;
            setupTrailerState.showGameTitle = true;
            const titleInput = document.getElementById('setupTrailerGameName');
            if (titleInput) titleInput.value = data.game_name;
            const eyeIcon = document.getElementById('setupTitleEyeIcon');
            const eyeText = document.getElementById('setupTitleEyeText');
            if (eyeIcon) eyeIcon.textContent = '👁️';
            if (eyeText) eyeText.textContent = 'Visible';
            const btnTitle = document.getElementById('btnSetupTrailerToggleTitle');
            if (btnTitle) btnTitle.style.opacity = '1';
        }

        if (overlayVideo) {
            overlayVideo.src = data.url;
            overlayVideo.loop = false;
            overlayVideo.currentTime = 0;
            overlayVideo.muted = false;
            overlayVideo.volume = 1.0;
            overlayVideo.load();
            overlayVideo.play().catch(e => {
                console.warn('Overlay video autoplay with sound was restricted by browser, muting:', e);
                overlayVideo.muted = true;
                overlayVideo.play().catch(() => {});
            });
            const audioIcon = document.getElementById('setupAudioBtnIcon');
            const audioIconBottom = document.getElementById('setupAudioBtnIconBottom');
            const iconStr = overlayVideo.muted ? '🔇' : '🔊';
            if (audioIcon) audioIcon.textContent = iconStr;
            if (audioIconBottom) audioIconBottom.textContent = iconStr;
        }

        if (bgVideo) {
            bgVideo.loop = false;
            bgVideo.muted = true;
            bgVideo.volume = 0;
            bgVideo.currentTime = 0;
            if (bgVideo.paused) bgVideo.play().catch(() => {});
        }

        bindSetupTrailerVideoSync();
        const replayOverlay = document.getElementById('setupReplayOverlay');
        if (replayOverlay) replayOverlay.style.display = 'none';

        updateSetupTrailerVisuals();
        showSetupTrailerToast('✅ ¡Tráiler descargado y colocado sobre la pantalla!');

        if (status) status.style.display = 'none';
        if (icon) icon.textContent = '✅';
        if (text) text.textContent = '¡Listo!';

        setTimeout(() => {
            if (btn) btn.disabled = false;
            if (icon) icon.textContent = '📥';
            if (text) text.textContent = 'Cargar';
        }, 2500);

    } catch (err) {
        console.error('Error al descargar trailer de YouTube:', err);
        showSetupTrailerToast(`❌ ${err.message || 'Error al descargar el tráiler'}`, true);
        if (status) status.style.display = 'none';
        if (btn) btn.disabled = false;
        if (icon) icon.textContent = '📥';
        if (text) text.textContent = 'Cargar';
    }
}
window.setupTrailerDownloadYoutube = setupTrailerDownloadYoutube;

function setupTrailerSetIntensity(val, save = true) {
    const num = Math.max(0, Math.min(1, parseFloat(val) || 0));
    setupTrailerState.cameraEffectIntensity = num;

    const btn0 = document.getElementById('btnSetupEffect0');
    const btn03 = document.getElementById('btnSetupEffect03');
    const btn05 = document.getElementById('btnSetupEffect05');
    const btn07 = document.getElementById('btnSetupEffect07');
    const desc = document.getElementById('setupEffectDesc');

    [btn0, btn03, btn05, btn07].forEach(b => {
        if (!b) return;
        b.classList.remove('active');
        b.style.background = 'none';
        b.style.color = 'var(--text-muted)';
        b.style.fontWeight = 'normal';
    });

    let activeBtn = btn05;
    if (num < 0.15) {
        activeBtn = btn0;
        if (desc) desc.textContent = 'Vídeo digital original sin efecto óptico de pantalla';
    } else if (num < 0.4) {
        activeBtn = btn03;
        if (desc) desc.textContent = 'Look muy sutil: micro-defocus y moiré casi imperceptible';
    } else if (num < 0.6) {
        activeBtn = btn05;
        if (desc) desc.textContent = 'Look realista: cámara física apuntando al monitor con moiré y bloom';
    } else {
        activeBtn = btn07;
        if (desc) desc.textContent = 'Look marcado: textura de panel, bloom y grano pronunciados';
    }

    if (activeBtn) {
        activeBtn.classList.add('active');
        activeBtn.style.background = '#38bdf8';
        activeBtn.style.color = '#0f172a';
        activeBtn.style.fontWeight = '700';
    }

    if (save) {
        setupTrailerAutoSaveConfig();
    }
}
window.setupTrailerSetIntensity = setupTrailerSetIntensity;

async function setupTrailerReapplyEffect() {
    const btn = document.getElementById('btnSetupTrailerReapplyEffect');
    const icon = document.getElementById('setupReapplyBtnIcon');
    const text = document.getElementById('setupReapplyBtnText');
    const status = document.getElementById('setupYtStatus');
    const statusText = document.getElementById('setupYtStatusText');
    const overlayVideo = document.getElementById('setupOverlayVideo');
    const bgVideo = document.getElementById('setupBgVideo');

    if (btn) btn.disabled = true;
    if (icon) icon.textContent = '⏳';
    if (text) text.textContent = 'Procesando...';
    if (status) status.style.display = 'flex';
    if (statusText) statusText.textContent = `Aplicando look de cámara en monitor (intensidad ${setupTrailerState.cameraEffectIntensity.toFixed(1)})...`;

    try {
        const resp = await fetch('/api/setup-trailer/apply-monitor-effect', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                intensity: setupTrailerState.cameraEffectIntensity,
                trailer_video: setupTrailerState.trailerVideo || undefined
            })
        });

        if (!resp.ok) {
            let errorMsg = `Error del servidor (${resp.status})`;
            try {
                const errData = await resp.json();
                if (errData && errData.detail) errorMsg = errData.detail;
            } catch (e) {}
            throw new Error(errorMsg);
        }

        const data = await resp.json();
        if (!data || !data.url) {
            throw new Error('Respuesta inválida del servidor');
        }

        setupTrailerState.trailerVideo = data.url;

        if (overlayVideo) {
            overlayVideo.src = data.url;
            overlayVideo.loop = false;
            overlayVideo.currentTime = 0;
            overlayVideo.load();
            overlayVideo.play().catch(() => {});
        }

        if (bgVideo) {
            bgVideo.loop = false;
            bgVideo.currentTime = 0;
            if (bgVideo.paused) bgVideo.play().catch(() => {});
        }

        bindSetupTrailerVideoSync();
        const replayOverlay = document.getElementById('setupReplayOverlay');
        if (replayOverlay) replayOverlay.style.display = 'none';

        updateSetupTrailerVisuals();
        showSetupTrailerToast(`✅ ${data.message || 'Efecto de monitor aplicado correctamente'}`);

        if (icon) icon.textContent = '✅';
        if (text) text.textContent = '¡Listo!';
        if (status) status.style.display = 'none';

        setTimeout(() => {
            if (btn) btn.disabled = false;
            if (icon) icon.textContent = '✨';
            if (text) text.textContent = 'Reaplicar';
        }, 2000);
    } catch (err) {
        console.error('Error reaplicando efecto de monitor:', err);
        showSetupTrailerToast(`❌ ${err.message || 'Error al aplicar efecto'}`, true);
        if (status) status.style.display = 'none';
        if (btn) btn.disabled = false;
        if (icon) icon.textContent = '✨';
        if (text) text.textContent = 'Reaplicar';
    }
}
window.setupTrailerReapplyEffect = setupTrailerReapplyEffect;

